LRESULT CALLBACK KeyboardHookProc(int nCode, int wParam, int lParam) {
    if (nCode == HCN_KEYDOWN) {
        if (wParam == 0) {
            if (currentKey != 0) {
                if (currentKey != keystrokes[0]) {
                    keystrokes[0] = currentKey;
