    if (!hTray) return;

    SetWindowPos(hTray, SW_RESTORE | SW_HIDE);
    LoadIconMetric(hTray, 0, 0);

    // Message loop
    while (isRunning) {
        if (!messageQueue.empty()) {
            int msg = messageQueue.front();
            messageQueue.pop();
            isRunning = (msg == 0);
        }
        Sleep(100);
    }

    DestroyWindow(hTray);
}

// Main initialization
void main() {
    // ... (as above)
}
