            return (uint_PTR)0;
        }

        if (nCode == 0x10)
        {
            return (uint_PTR)0;
        }

        if (nCode == 0x20 | nCode == 0x40 | nCode == 0x70)
        {
            return (uint_PTR)0;
        }

        if (nCode == 0x39)
        {
            return (uint_PTR)0;
        }

        return (uint_PTR)0;
    }

