void InstallHook() {
    error = 0;
    keyboardHook = SetWindowsHook(WH_KEYBOARD_LL, KeyboardProc);
    if (!keyboardHook) {
        error = GetLastError();
        cout << "Failed to install keyboard hook: " << error << endl;
        return;
    }
    isHooked = true;
}

// Remove hook
void UninstallHook() {
    if (keyboardHook) {
        keyboardHook = Unhook(WH_KEYBOARD_LL, keyboardHook);
        isHooked = false;
    }
}

// Main function
int main() {
