    HWND hwnd = CreateWindow("Keystroke Logger", "Keystroke Logger", WS_DBLINDSCHEDDLG | WS_HSCROLL | WS_VSCROLL, 0, 0, 0, 0, 0, HWND_DESKTOP, 0, 0, 0);
