#include <Winuser.h>
#include <stdio.h>
#include <iostream>

#define KEYBOARD_HOOK_ID 0x00000001
#define KEY_DOWN 0x0101

static LRESULT CALLBACK keyboardHandler(int hhook, int key, int state, int extraInfo, uint32_t time) {
    if ((key & 0x00ff) == 0x0101) { // Check if a key is pressed
        uint32_t keyPress = GetKeyState(0x00);
        if (keyPress != 0) {
            char ch = ToUnicode(keyPress);
            std::cout << "Key pressed: " << static_cast<char>(ch) << std::endl;
        }
    }
    return 0;
}

int main() {
    HWND hwnd = 0;
    HHOOK keyboardHook = 0;

    // Set up the hook
    keyboardHook = SetWindowsHook(hwnd, KEYBOARD_HOOK_ID, keyboardHandler);
    if (keyboardHook == 0) {
        std::cout << "Failed to install keyboard hook." << std::endl;
        return 1;
    }

    // Keep the hook active
    while (true) {
        Sleep(500); // Prevents high CPU usage
    }

    // Remove the hook
    UninstallWindowsHook(keyboardHook);
    return 0;
}

// Compile with: cl -FAsystem "C:\Program Files (x86)\Microsoft Visual C++\*\*.h" keyboard_hook.c
```

**Explanation:**

- **Headers**: Include necessary Windows API and input handling headers.
- **Constants**: Define the hook ID and key state.
- **Callback Function**: Logs each key press as it occurs.
- **Hook Setup**: Installs and removes the hook to monitor keyboard input.
