        }
        Sleep(100);
    }

    UninstallHook();
    return 0;
}

// In the main function, 'g_hhook' and 'dwThreadId' need to be declared as global variables or passed as references.

int g_hhook = 0;
DWORD dwThreadId = 0;
```

