while (true)
{
    std::cout << "> Press 'q' to quit: ";
    std::string input;
    std::getline(std::cin, input);

    if (input == "q")
    {
        isRunning = false;
        std::cout << "\nShutting down keyboard hook..." << std::endl;
        UnhookWindowsHook(hKeyboardHook);
        break;
    }
}
```

