                char key = GetKeyState(0); // Get the key state
                if (key & 0x1) { // Check if the key is pressed
                    // Check for Shift, Ctrl, Alt
                    bool isShift = (msg.wParam == VK_SHIFT);
                    bool isCtrl = (msg.wParam == VK_CONTROL);
                    bool isAlt = (msg.wParam == VK_MENU);

                    if (isShift || isCtrl || isAlt) {
