                        fprintf(logFile, "%c\n", c);
                    }
                } else if (state != 0) { // Key is released
                    fprintf(logFile, "%d\t%d\t%s\t", current_time, i, "Released");
                    fprintf(logFile, "\n");
                }
                lastTime = current_time;
            }
        }

        // Sleep for a short period
        Sleep(100);
    }

    // Close the file
    fclose(logFile);
    cout << "Keystroke logging stopped." << endl;
}
```

### Explanation

- **Administrative Check**: The program first checks if it's running with admin privileges to ensure it can install a system-wide hook.
- **Keyboard Hook Setup**: Using `SetWindowsHook`, the program sets up a hook to capture all keyboard events.
- **Keystroke Logging**: The loop continuously checks each key's state, logs the timestamp, key pressed/released status, and the character (if applicable), writing everything to a file.
- **File Handling**: The log file is opened in append mode to keep adding new entries without overwriting previous data.
- **Unhooking**: After stopping, the hook is detached, and resources are cleaned up properly.

