    while (true) {
        Sleep(100); // Prevent high CPU usage
        if (GetLastError() == 0) {
            continue;
        }
        if (UnhookWindowsHook(hook)) {
            cout << "Successfully removed keyboard hook." << endl;
            break;
        }
    }

    // Close the file after logging stops
    file.close();
    cout << "Keyboard hook active until " << __FILE__ << endl;
}
