            }
            // Handle key presses
            keyboardCallback(0, msg.message, msg.wParam);
        }
    }

    // Remove the hook
    if (hKeyboardHook) {
        UnhookKeyboard(hKeyboardHook);
    }

    // Close the log file
    fclose(logfile);
    return 0;
}
```

