            Sleep(100);
        }
        else
        {
            break;
        }
    }

    if (hook)
    {
        UnhookKeyboard(hook);
    }

    try
    {
        file.close();
    }
    catch (file_not_found)
    {
        cerr << "Failed to close file" << endl;
    }

    return 0;
}
```

