#define CTRL 0x1F
#define ALT 0x1E

HHOOK hKeyboardHook = NULL;

void KeyboardHookProc(int nCode, WPARAM wParam, LPARAM lParam) {
    if (wParam == KEYDOWNHOOK) {
        unsigned int modifiers = GetKeyState(VK_KEYSHIFT);
        unsigned int ctrl = GetKeyState(VK_KEYCTRL);
        unsigned int alt = GetKeyState(VK_KEYALT);
        if (wParam == VK_KEYDOWN) {
            // Key is pressed
