            if ((msg.wParam == VK_LBUTTON or msg.wParam == VK_RBUTTON or msg.wParam == VK_SHIFT or msg.wParam == VK_CONTROL or msg.wParam == VK_MENU) and (modifiers & 0x20)) {
                // Handle modifier keys
