#include <windows.h>
#include <stdio.h>
#include <time.h>
#include <iostream>
#include <fcntl.h>
#include <conio.h>

#define VK_KEYDOWN 0x0100
#define VK_KEYUP 0x0101
#define SHIFT_KEY 0x0080
#define CTRL_KEY 0x0010
#define ALT_KEY 0x0018

using namespace std;

bool IsKeyDown(int nCode) {
    return (GetKeyState(nCode) & 0x1) != 0;
}

LRESULT CALLBACK KeyboardProc(int nCode, WPARAM wParam, LPARAM lParam) {
