            // Remove the hook and clean up
            UnhookWindowsHook(hKeyboardHook);
            DestroyWindow(hwnd);
            return 0;
        }
    }

    // Remove the hook and clean up
    UnhookWindowsHook(hKeyboardHook);
    DestroyWindow(hwnd);
    return 0;
}
