                    // Optional: log other info like time
                }
                logFile.close();
            } catch (const IOException& e) {
                cout << "Error writing to file: " << e.what() << endl;
            }
        }
    }
    UnhookWindowsContext(hwnd, hhook);
    CloseHandle(file);
}
```

