void AppendToLogFile(char key, std::string time, FILE *file) {
    // Write the keystroke and time to the file
    // Include newline and timestamp
    std::string entry = time + " - " + (char)key + "\n";
    if (fwrite(entry.c_str(), file) != 0) {
        printf("Key logged: %s\n", entry.c_str());
    } else {
        printf("Failed to log key: %c\n", key);
    }
}

std::string GetCurrentTimeAsString() {
    char buffer[20];
    std::time_t now = time(nullptr);
    std::tm* timeStruct = localtime(&now);
    if (timeStruct) {
        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeStruct);
        return std::string(buffer);
    }
    return "Unknown time";
}
```

