### Sample Code

```c
#include <Windows.h>
#include <stdio.h>
#include <time.h>

#define IDCB_TABLET_EVENTHOOK 0x00000001L

static FILE *logfile;
static double lastTimestamp;
static HWND hwnd = 0;
static HHOOK hook = 0;

LRESULT CALLBACK keyboardCallback(int nCode, WPARAM wParam, LPARAM lParam) {
    char key[255];
    static int lastKey = 0;
    static int lastModifier = 0;
    static int lastTimestamp = 0;

    if (wParam == WM_KEYDOWN || wParam == WM_KEYUP) {
        if (GetKeyState(0x1)) {
            if (wParam == VK_SHIFT) lastModifier = 1;
            else if (wParam == VK_CONTROL) lastModifier = 2;
            else if (wParam == VK_MENU) lastModifier = 4;
        } else if (GetKeyState(0x1)) {
            if (wParam == VK_SHIFT) lastModifier = 0;
            else if (wParam == VK_CONTROL) lastModifier = 0;
            else if (wParam == VK_MENU) lastModifier = 0;
        }

        if (lastModifier != 0) {
            sprintf(key, "%d-MODIFIER PRESSED", lastModifier);
        } else {
