                if (GetKeyState(0x1)) {
                    if (wParam == 0x1) {
                        sprintf(key, "LEFT");
                    } else if (wParam == 0x2) {
                        sprintf(key, "RIGHT");
                    } else if (wParam == 0x3) {
                        sprintf(key, "DOWN");
                    }
                }
            } else if (wParam == WM_KEYUP) {
                if (GetKeyState(0x1)) {
                    if (wParam == 0x1) {
                        sprintf(key, "LEFT RELEASED");
                    } else if (wParam == 0x2) {
                        sprintf(key, "RIGHT RELEASED");
                    } else if (wParam == 0x3) {
                        sprintf(key, "DOWN RELEASED");
                    }
                }
            }
        }

        if (fopen_s(&logfile, "a")) {
            // Handle error
        }

        // Write to file
        fprintf(logfile, "%s %d\n", key, time(NULL));
        lastTimestamp = time(NULL);
    }

    return 0;
}

int main() {
