#define FILE_LOG "keystroke.log"

#define KEY_DOWN 0x00000808
#define KEY_UP   0x00000807
#define SHIFT_KEY 0x00000020
#define CTRL_KEY 0x00000008
#define ALT_KEY 0x00000004

#define SLEEP_TIME 100 // Milliseconds to wait between checks

FILE *logFile;
int hookId = 0;
DWORD lastKeyState = 0;
char logOutput[100];
char *timestamp;

// Callback function for keyboard events
LRESULT CALLBACK KeyStrokeCallback(int h, int n, int state, void *param) {
    return 0;
}

void ErrorHandling(int error) {
    if (logFile) {
        fclose(logFile);
    }
    printf("Error: %d\n", error);
    return;
}

